    if (canvasMaxWidthType === 'px') _maxWidth = (canvasMaxWidth || DEFAULT_CANVAS_WIDTH) + 'px';
    if (canvasMaxWidthType === '%') _maxWidth = canvasMaxWidth + '%';

    setMaxWidth(_maxWidth);
