  if (appType !== 'module') {
    const headerHeight = showCanvasHeader ? pageCanvasHeaderHeight : 0;
    const footerHeight = showCanvasFooter ? pageCanvasFooterHeight : 0;
    return `calc(${height} - ${headerHeight + footerHeight}px)`;
  }

  return height;
}
