  const isActive = page?.id === currentPageId;

  if (isPageHidden || page.disabled || (page?.restricted && currentMode !== 'edit')) return null;

  const IconElement = (props) => {
    if (!isSidebarPinned || labelStyle?.label?.hidden) {
      return (
