        )}
        {!isPagesSidebarHidden && position === 'side' && collapsable && style === 'texticon' && (
          <ButtonComponent
            className="left-sidebar-item !tw-w-[36px] !tw-h-[36px]"
            onClick={handleToggle}
            variant="ghost"
            size="large"
            iconOnly
