const WIDGETS_WITH_PORTALED_CONTENT = ['ModalV2'];

const RenderWidget = ({
  id,
  widgetHeight,
  componentType,
  subContainerIndex,
  resolveIndex,
  nearestListviewId,
  effectiveSubContainerIndex,
  onOptionChange,
  onOptionsChange,
  widgetWidth,
