            show={hasUserTooltip}
            darkMode={darkMode}
          >
            {innerWidget}
          </WidgetTooltip>
        )}
      </FallbackBoundary>
    );
  }

  return (
    <FallbackBoundary
      variant="inline"
      label={componentName}
      location={`Component ${componentName}`}
      canRetry
      canReport={currentMode === 'edit'}
      darkMode={darkMode}
