  const darkMode = localStorage.getItem('darkMode') === 'true';

  const searchIcon = (text) => {
    if (searchText === text) return;
    setSearchText(text);
  };

  const filteredIcons =
    searchText === ''
      ? iconList.current
      : iconList.current.filter((icon) => icon?.toLowerCase().includes(searchText ? searchText.toLowerCase() : ''));

  const onIconSelect = (icon) => {
    onChange(icon);
  };

  const eventPopover = () => {
    return (
      <Popover
        id="popover-basic"
        style={{ width: '460px', maxWidth: '460px' }}
        className={`icon-widget-popover ${darkMode && 'dark-theme theme-dark'}`}
        onClick={(event) => event.stopPropagation()}
      >
        <Popover.Header>
          <SearchBox onSubmit={searchIcon} width="100%" />
        </Popover.Header>
        <Popover.Body>
          <div className="row">
            {
              <VirtuosoGrid
                style={{ height: 300 }}
                totalCount={filteredIcons.length}
                listClassName="icon-list-wrapper"
                itemClassName="icon-list"
                itemContent={(index) => {
                  if (filteredIcons[index] === undefined || filteredIcons[index] === 'createReactComponent')
                    return null;
                  // eslint-disable-next-line import/namespace
                  const IconElement = Icons[filteredIcons[index]];
                  return (
                    <div
                      className="icon-element p-2"
                      onClick={() => {
                        onIconSelect(filteredIcons[index]);
                        setPopOverVisibility(false);
                      }}
                    >
                      <IconElement
                        color={`${darkMode ? '#fff' : '#000'}`}
                        stroke={1.5}
                        strokeLinejoin="miter"
                        style={{ width: '24px', height: '24px' }}
                      />
                    </div>
                  );
                }}
              />
            }
          </div>
        </Popover.Body>
      </Popover>
    );
  };

  function RenderIconPicker() {
    // eslint-disable-next-line import/namespace
    const IconElement = Icons?.[value] ?? Icons?.['IconHome2'];

    return (
      <>
        <div className="color-picker-input icon-style-container" style={{ position: 'relative' }}>
          <div className="p-0">
            <div className="field">
              <OverlayTrigger
                trigger="click"
                placement={'left'}
                show={showPopOver}
                onToggle={(showing) => setPopOverVisibility(showing)}
                rootClose={true}
                overlay={eventPopover()}
              >
                <div className="d-flex align-items-center" role="button">
                  <div className="" style={{ marginRight: '2px', marginLeft: '6px', height: '20px', width: '18px' }}>
                    <IconElement
                      data-cy={`icon-on-side-panel`}
                      color={`${darkMode ? '#fff' : '#000'}`}
                      stroke={1.5}
                      strokeLinejoin="miter"
                      style={{ width: '18px', height: '18px' }}
                    />
                  </div>
                  <div
                    className="text-truncate tj-text-xsm"
                    style={{
                      width: '80px',
                      color: 'var(--slate12)',
                    }}
                  >
                    {String(value)}
                  </div>
                  {isVisibilityEnabled && (
                    <Visibility
                      value={value}
                      onChange={onChange}
                      onVisibilityChange={onVisibilityChange}
                      component={component}
                      styleDefinition={styleDefinition}
                      iconVisibility={iconVisibility}
                    />
                  )}
                </div>
              </OverlayTrigger>
            </div>
          </div>
        </div>
      </>
    );
  }
  return <>{RenderIconPicker()}</>;
};
