    if (!input) return false;
    if (Array.isArray(input)) {
      return input.length ? true : false;
    }
    if (typeof input === 'object' && !Array.isArray(input)) {
      if (!Object.keys(input).length) return false;
      if (!input.value) return false;
      return true;
