              setIsOverflown(false);
              onChange && onChange(values);
              setSelected(values);
            }}
            selected={selected}
            closePopup={() => setShowMenu(isForeignKeyInEditCell ? true : false)}
            onAdd={onAdd}
            addBtnLabel={addBtnLabel}
            loader={loader}
            isLoading={isLoading}
            emptyError={emptyError}
            highlightSelected={highlightSelected}
            foreignKeyAccess={foreignKeyAccess}
            showRedirection={showRedirection}
            columnInfoForTable={columnInfoForTable}
            showColumnInfo={showColumnInfo}
            showDescription={showDescription}
            foreignKeyAccessInRowForm={foreignKeyAccessInRowForm}
            isCellEdit={isCellEdit}
            scrollEventForColumnValues={scrollEventForColumnValues}
            organizationId={organizationId}
            foreignKeys={foreignKeys}
            setReferencedColumnDetails={setReferencedColumnDetails}
            shouldShowForeignKeyIcon={shouldShowForeignKeyIcon}
            cellColumnName={cellColumnName}
            isInitialForeignKeyDataLoaded={isInitialForeignKeyDataLoaded}
            setIsInitialForeignKeyDataLoaded={setIsInitialForeignKeyDataLoaded}
            totalRecords={totalRecords}
            setTotalRecords={setTotalRecords}
            pageNumber={pageNumber}
            setPageNumber={setPageNumber}
            tableName={tableName}
            targetTable={targetTable}
            actions={actions}
            actionName={actionName}
            referencedForeignKeyDetails={referencedForeignKeyDetails}
            cachedOptions={cachedOptions}
            columnDataType={columnDataType}
            isCreateRow={isCreateRow}
            isEditRow={isEditRow}
            isEditColumn={isEditColumn}
            isCreateColumn={isCreateColumn}
            isEditTable={isEditTable}
            isCreateTable={isCreateTable}
            customChildren={customChildren}
            isForeignKeyInEditCell={isForeignKeyInEditCell}
            closeFKMenu={closeFKMenu}
            saveFKValue={saveFKValue}
            columnDefaultValue={columnDefaultValue}
            setColumnDefaultValue={setColumnDefaultValue}
            showControlComponent={showControlComponent}
          />
        </Popover>
      }
    >
      {isForeignKeyInEditCell ? (
        <div
          className={`col-auto`}
          style={{
            position: 'relative',
            left: '-10px',
            top: selected.label === null || selected.label === undefined || isCellEdit ? '0px' : '2px',
            paddingLeft: '10px',
            paddingBottom: '4px',
          }}
          id={popoverBtnId.current}
          onClick={() => {
            setShowMenu(true);
          }}
        >
          <p
            className={cx({
              'd-flex align-items-center justify-content-center m-0':
                selected.label === null || selected.label === undefined,
              'cell-menu-text m-0': selected.label !== null || selected.label !== undefined,
            })}
            style={{
              color: darkMode ? '#fff' : '',
              width: (selected.label === null || selected.label === undefined) && '40px',
              background: (selected.label === null || selected.label === undefined) && 'var(--slate3)',
            }}
          >
            {selected?.label ?? 'Null'}
          </p>
        </div>
      ) : (
        <div className={`col-auto ${buttonClasses} h-100`} id={popoverBtnId.current}>
          <ButtonSolid
            size="sm"
            variant="tertiary"
            disabled={disabled}
            onClick={(e) => {
              e.stopPropagation();
              if (disabled) {
                return;
              }
              setShowMenu((show) => !show);
              if (onTableClick === true) {
                fetchTables();
              }
            }}
            className={cx(
              {
                'justify-content-start': !shouldCenterAlignText,
                'justify-content-centre': shouldCenterAlignText,
                'border-1 tdb-dropdown-btn-foreignKeyAccess': foreignKeyAccess || foreignKeyAccessInRowForm,
                'border-0 tdb-dropdown-btn': !foreignKeyAccess || !foreignKeyAccessInRowForm,
              },
              'gap-0',
              'w-100',
              'h-100',
              'align-items-start',
              'rounded-0',
              'position-relative',
              'font-weight-normal',
              'px-1'
            )}
            data-cy={dataCy}
          >
            <ToolTip
              message={fetchTooltipMessageForDropdownSelected(selected)}
              show={!!fetchTooltipMessageForDropdownSelected(selected) && isTruncated}
            >
              <div className={`text-truncate`} ref={valueRef}>
                {renderSelected && renderSelected(selected)}
                <>
                  {!renderSelected && isValidInput(selected) ? (
                    Array.isArray(selected) ? (
                      !isOverflown && (
                        <MultiSelectValueBadge
                          options={options}
                          selected={selected}
                          setSelected={setSelected}
                          onChange={onChange}
                        />
                      )
                    ) : (
                      selected?.label
                    )
                  ) : showPlaceHolder ? (
                    <span style={{ color: '#9e9e9e', fontSize: '12px', fontWeight: '400', lineHeight: '20px' }}>
                      {foreignKeyAccessInRowForm || showPlaceHolderInForeignKeyDrawer
                        ? topPlaceHolder
                        : placeholder
                          ? placeholder
                          : 'Select...'}
                    </span>
                  ) : (
                    ''
                  )}
                  {!renderSelected && isOverflown && !Array.isArray(selected) && (
                    <Badge className="me-1 dd-select-value-badge" bg="secondary">
                      {selected?.length} selected
                      <span
                        role="button"
                        onClick={(e) => {
                          setSelected([]);
                          onChange && onChange([]);
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                      >
                        <Remove fill="var(--slate12)" width="12px" />
                      </span>
                    </Badge>
                  )}
                </>
              </div>
            </ToolTip>
            <div className="dd-select-control-chevron">
              <CheveronDown width="15" height="15" />
            </div>
          </ButtonSolid>
        </div>
      )}
    </OverlayTrigger>
  );
};

function MultiSelectValueBadge({ options, selected, setSelected, onChange }) {
  if (options?.length === selected?.length && selected?.length !== 0) {
    // Filter Options without 'Select All'
    const optionsWithoutSelectAll = options?.filter((option) => option?.value !== 'SELECT ALL');
    return (
      <Badge className={`me-1 dd-select-value-badge`} bg="secondary">
        All {optionsWithoutSelectAll?.length} selected
        <span
          role="button"
          onClick={(e) => {
            e.stopPropagation();
            setSelected([]);
            onChange([]);
            e.preventDefault();
          }}
        >
          <Remove fill="var(--slate12)" />
        </span>
      </Badge>
    );
  }

  return selected?.map((option) => (
    <Badge key={option?.value} className="me-1 dd-select-value-badge" bg="secondary">
      {option?.label}
      <span
        role="button"
        onClick={(e) => {
          setSelected((selected) => {
            onChange && onChange(selected.filter((opt) => opt?.value !== option?.value));
            return selected?.filter((opt) => opt?.value !== option?.value);
          });
          e.preventDefault();
          e.stopPropagation();
        }}
      >
        <Remove fill="var(--slate12)" />
      </span>
    </Badge>
  ));
}

export default DropDownSelect;
import React from 'react';
import { Container, Row, Col } from 'react-bootstrap';
import { useToolJetDbOperationsContext } from './ToolJetDbOperationsContext';
import DropDownSelect from './DropDownSelect';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import AddRectangle from '@/_ui/Icon/bulkIcons/AddRectangle';
import Trash from '@/_ui/Icon/solidIcons/Trash';
import Remove from '@/_ui/Icon/solidIcons/Remove';
import Information from '@/_ui/Icon/solidIcons/Information';
import Icon from '@/_ui/Icon/solidIcons/index';
import set from 'lodash/set';
import { isEmpty } from 'lodash';
import { getPrivateRoute } from '@/_helpers/routes';
import { useNavigate } from 'react-router-dom';
import useConfirm from './Confirm';
import { deepClone } from '@/_helpers/utilities/utils.helpers';
import CodeHinter from '@/AppBuilder/CodeEditor';
import { ToolTip } from '@/_components';
import { resolveColumnDisplayName, columnIdOf } from './util';

const JoinConstraint = ({ darkMode, index, onRemove, onChange, data }) => {
  const { selectedTableId, tables, joinOptions, findTableDetails, tableForeignKeyInfo, tableInfo } =
    useToolJetDbOperationsContext();
  const joinType = data?.joinType;
  const baseTableDetails = (selectedTableId && findTableDetails(selectedTableId)) || {};
  const conditionsList = isEmpty(data?.conditions?.conditionsList) ? [{}] : data?.conditions?.conditionsList;

  const operator = data?.conditions?.operator;
  const leftFieldTable = conditionsList?.[0]?.leftField?.table || selectedTableId;
  const rightFieldTable = conditionsList?.[0]?.rightField?.table;

  const navigate = useNavigate();
  const { confirm, ConfirmDialog } = useConfirm();

  const tableSet = new Set();
  (joinOptions || [])
    .filter((_join, i) => i < index)
    .forEach((join) => {
      const { table, conditions } = join;
      tableSet.add(table);
      conditions?.conditionsList?.forEach((condition) => {
        const { leftField, rightField } = condition;
        if (leftField?.table) {
          tableSet.add(leftField?.table);
        }
        if (rightField?.table) {
          tableSet.add(rightField?.table);
        }
      });
    });
  tableSet.add(selectedTableId);

  // In Joins-Query, the table on the LHS should be the ones which we already selected for base table or the tables which we selected on RHS
  const leftTableList = [];
  [...tableSet]
    .filter((table) => table !== rightFieldTable)
    .forEach((t) => {
      const tableDetails = findTableDetails(t);
      const targetTableFKListWithAdjacentTable = checkIfAdjacentTableHasForeignKey(true, t?.table_id);
      if (targetTableFKListWithAdjacentTable.length) {
        leftTableList.unshift({
          label: tableDetails?.table_name ?? '',
          value: t,
          isTargetTable: !!targetTableFKListWithAdjacentTable.length,
        });
      } else {
        leftTableList.push({
          label: tableDetails?.table_name ?? '',
          value: t,
          isTargetTable: !!targetTableFKListWithAdjacentTable.length,
        });
      }
    });

  // Tables to list on Right-Hand-Side of Join operation, Omits already selected table
  const tableList = [];
  tables
    .filter((table) => ![...tableSet, leftFieldTable].includes(table.table_id))
    .forEach((t) => {
      const targetTableFKListWithAdjacentTable = checkIfAdjacentTableHasForeignKey(false, t?.table_id);
      if (targetTableFKListWithAdjacentTable.length) {
        tableList.unshift({
          label: t?.table_name ?? '',
          value: t?.table_id,
          isTargetTable: !!targetTableFKListWithAdjacentTable.length,
        });
      } else {
        tableList.push({
          label: t?.table_name ?? '',
          value: t?.table_id,
          isTargetTable: !!targetTableFKListWithAdjacentTable.length,
        });
      }
    });

  const foreignKeyTableDetails = Object.values(tableForeignKeyInfo)?.flatMap(
    (foreignKeyDetails) => foreignKeyDetails || []
  );

  function isMatchingForeignKeyObjects(foreignKeyTableList, tableList) {
    const foreignKeyObjects = [];
    for (const fkObject of foreignKeyTableList) {
      for (const table of tableList) {
        if (fkObject.referenced_table_id === table.value) {
          foreignKeyObjects.push(fkObject);
        }
      }
    }
    return foreignKeyObjects;
  }

  const foreignKeyDetails = isMatchingForeignKeyObjects(foreignKeyTableDetails, tableList);

  // OnSelecting LHS ro RHS table on Join Operation, Checking if Adjacent table has FK relation and Auto Fill the column values
  function checkIfAdjacentTableHasForeignKey(isChoosingLHStable, tableId) {
    if (isChoosingLHStable && rightFieldTable) {
      const rightFieldTableDetails = findTableDetails(rightFieldTable);
      if (rightFieldTableDetails?.table_name && tableForeignKeyInfo[rightFieldTableDetails.table_name]) {
        return tableForeignKeyInfo[rightFieldTableDetails.table_name].filter(
          (foreignKeyDetail) => foreignKeyDetail.referenced_table_id === tableId
        );
      }
    }

    if (!isChoosingLHStable && leftFieldTable) {
      const leftFieldTableTableDetails = findTableDetails(leftFieldTable);
      if (leftFieldTableTableDetails?.table_name && tableForeignKeyInfo[leftFieldTableTableDetails.table_name]) {
        return tableForeignKeyInfo[leftFieldTableTableDetails.table_name].filter(
          (foreignKeyDetail) => foreignKeyDetail.referenced_table_id === tableId
        );
      }
    }

    return [];
  }

  // Looks up a column's permanent id by table + column name, from the same tableInfo/column list
  // used by the manual dropdown paths below - so an auto-filled FK condition carries a columnId
  // just like a user-picked one, and both survive a column rename identically.
  function findColumnIdByName(tableId, columnName) {
    if (!tableId || !columnName) return undefined;
    const tableDetails = findTableDetails(tableId);
    return tableInfo[tableDetails?.table_name]?.find((col) => col.Header === columnName)?.column_id;
  }

  function autoFillColumnIfForeignKeyExists(tableId, isChoosingLHStable) {
    const adjacentTableForeignKeyDetails = checkIfAdjacentTableHasForeignKey(isChoosingLHStable, tableId);
    if (isChoosingLHStable) {
      if (adjacentTableForeignKeyDetails.length) {
        const newData = deepClone({ ...data });
        const newConditionsList = adjacentTableForeignKeyDetails.map((adjacentTableForeignKey) => {
          const { referenced_column_names = [], column_names = [] } = adjacentTableForeignKey;
          const newCondition = {
            leftField: {
              table: tableId,
              type: 'Column',
              ...(referenced_column_names[0] && {
                columnName: referenced_column_names[0],
                columnId: findColumnIdByName(tableId, referenced_column_names[0]),
              }),
            },
            operator: '=',
            rightField: {
              table: rightFieldTable,
              type: 'Column',
              ...(column_names[0] && {
                columnName: column_names[0],
                columnId: findColumnIdByName(rightFieldTable, column_names[0]),
              }),
            },
          };

          return newCondition;
        });
        set(newData, 'conditions.conditionsList', newConditionsList);
        onChange(newData);
      } else {
        const newData = deepClone({ ...data });
        const { conditionsList = [{}] } = newData?.conditions || {};
        const newConditionsList = conditionsList.map((condition) => {
          const newCondition = { ...condition };
          set(newCondition, 'leftField.table', tableId);
          set(newCondition, 'operator', '='); //should we removed when we have more options
          return newCondition;
        });
        set(newData, 'conditions.conditionsList', newConditionsList);
        // set(newData, 'table', value?.value);
        onChange(newData);
      }
    } else {
      if (adjacentTableForeignKeyDetails.length) {
        const newData = deepClone({ ...data });
        const newConditionsList = adjacentTableForeignKeyDetails.map((adjacentTableForeignKey) => {
          const { referenced_column_names = [], column_names = [] } = adjacentTableForeignKey;
          const newCondition = {
            leftField: {
              table: leftFieldTable,
              type: 'Column',
              ...(column_names[0] && {
                columnName: column_names[0],
                columnId: findColumnIdByName(leftFieldTable, column_names[0]),
              }),
            },
            operator: '=',
            rightField: {
              table: tableId,
              type: 'Column',
              ...(referenced_column_names[0] && {
                columnName: referenced_column_names[0],
                columnId: findColumnIdByName(tableId, referenced_column_names[0]),
              }),
            },
          };

          return newCondition;
        });
        set(newData, 'conditions.conditionsList', newConditionsList);
        set(newData, 'table', tableId);
        onChange(newData);
      } else {
        const newData = deepClone({ ...data });
        const { conditionsList = [] } = newData?.conditions || {};
        const newConditionsList = conditionsList.map((condition) => {
          const newCondition = { ...condition };
          set(newCondition, 'rightField.table', tableId);
          set(newCondition, 'operator', '='); //should we removed when we have more options
          return newCondition;
        });
        set(newData, 'conditions.conditionsList', newConditionsList);
        set(newData, 'table', tableId);
        onChange(newData);
      }
    }
  }

  return (
    <Container fluid className="p-0">
      <Row className={`mx-0 ${index === 0 && 'pb-2'}`}>
        <Col sm="2"></Col>
        <Col sm="4" className="text-left">
          Selected Table
        </Col>
        <Col sm="1"></Col>
        <Col sm="4" className="text-left">
          Joining Table
        </Col>
        {index !== 0 && (
          <Col sm="1" className="justify-content-end d-flex pe-0">
            <ButtonSolid
              variant="ghostBlack"
              size="sm"
              className="p-0"
              onClick={async () => {
                const result = await confirm(
                  'Deleting a join will also delete its associated conditions. Are you sure you want to continue ?',
                  'Delete'
                );
                if (result) onRemove();
              }}
            >
              <Remove style={{ height: '16px' }} />
            </ButtonSolid>
          </Col>
        )}
      </Row>
      <Row className="mb-2 mx-0">
        <Col sm="2" className="p-0">
          <div
            style={{
              borderRadius: 0,
              height: '30px',
            }}
            className="tj-small-btn px-2 border border-end-0 rounded-start"
          >
            Join
          </div>
        </Col>
        <Col sm="4" className="p-0">
          {index ? (
            <DropDownSelect
              buttonClasses="border border-end-0"
              showPlaceHolder
              options={leftTableList}
              darkMode={darkMode}
              onChange={async (value) => {
                let result = false;
                if (leftFieldTable.length) {
                  result = await confirm(
                    'Changing the table will also delete its associated conditions. Are you sure you want to continue?',
                    'Change table?'
                  );
                } else {
                  result = true;
                }

                if (result) autoFillColumnIfForeignKeyExists(value?.value, true);
              }}
              onAdd={() => navigate(getPrivateRoute('database'))}
              addBtnLabel={'Add new table'}
              value={leftTableList.find((val) => val?.value === leftFieldTable)}
              shouldShowForeignKeyIcon
            />
          ) : (
            <div
              style={{
                borderRadius: 0,
                height: '30px',
              }}
              className="tj-small-btn px-2 border border-end-0"
            >
              {baseTableDetails?.table_name ?? ''}
            </div>
          )}
        </Col>
        <Col sm="1" className="p-0">
          <DropDownSelect
            buttonClasses="border border-end-0"
            shouldCenterAlignText
            options={staticJoinOperationsList}
            darkMode={darkMode}
            onChange={(value) => onChange({ ...data, joinType: value?.value })}
            value={staticJoinOperationsList.find((val) => val.value === joinType)}
            renderSelected={(selected) =>
              selected ? (
                <div className="w-100">
                  <Icon name={selected?.icon} height={20} width={20} viewBox="" />
                </div>
              ) : (
                ''
              )
            }
          />
        </Col>
        <Col sm="5" className="p-0">
          <DropDownSelect
            buttonClasses="border rounded-end"
            showPlaceHolder
            options={tableList}
            darkMode={darkMode}
            onChange={async (value) => {
              let result = true;
              if (rightFieldTable?.length) {
                result = await confirm(
                  'Changing the table will also delete its associated conditions. Are you sure you want to continue?',
                  'Change table?'
                );
              }

              if (result) autoFillColumnIfForeignKeyExists(value?.value, false);
            }}
            onAdd={() => navigate(getPrivateRoute('database'))}
            addBtnLabel={'Add new table'}
            value={tableList.find((val) => val?.value === rightFieldTable)}
            shouldShowForeignKeyIcon
            referencedForeignKeyDetails={foreignKeyDetails}
          />
        </Col>
      </Row>
      {conditionsList.map((condition, index) => (
        <JoinOn
          condition={condition}
          leftFieldTable={leftFieldTable}
          rightFieldTable={rightFieldTable}
          darkMode={darkMode}
          key={index}
          index={index}
          groupOperator={operator}
          onOperatorChange={(value) => {
            const newData = deepClone(data);
            set(newData, 'conditions.operator', value);
            onChange(newData);
          }}
          onChange={(value) => {
            const newConditionsList = conditionsList.map((con, i) => {
              if (i === index) {
                return value;
              }
              return con;
            });
            const newData = deepClone(data);
            set(newData, 'conditions.conditionsList', newConditionsList);
            onChange(newData);
          }}
          onRemove={() => {
            const newConditionsList = conditionsList.filter((_cond, i) => i !== index);
            const newData = deepClone(data);
            set(newData, 'conditions.conditionsList', newConditionsList);
            onChange(newData);
          }}
        />
      ))}
      <Row className="mb-2 mx-1">
        <Col className="p-0">
          <ButtonSolid
            variant="ghostBlue"
            size="sm"
            onClick={() => {
              const newData = deepClone(data);
              set(newData, 'conditions.conditionsList', [...conditionsList, { operator: '=' }]);
              onChange(newData);
            }}
          >
            <AddRectangle width="15" fill="#3E63DD" opacity="1" secondaryFill="#ffffff" />
            &nbsp;&nbsp; Add more
          </ButtonSolid>
        </Col>
      </Row>
      <ConfirmDialog confirmButtonText="Continue" darkMode={darkMode} />
    </Container>
  );
};

