export default function JoinSort({ darkMode }) {
  const { tableInfo, joinOrderByOptions, setJoinOrderByOptions, joinOptions, findTableDetails } =
    useToolJetDbOperationsContext();

  const tableSet = new Set();
  (joinOptions || []).forEach((join) => {
    const { table, conditions } = join;
    tableSet.add(table);
    conditions?.conditionsList?.forEach((condition) => {
      const { leftField, rightField } = condition;
      if (leftField?.table) {
        tableSet.add(leftField?.table);
      }
      if (rightField?.table) {
        tableSet.add(rightField?.table);
      }
    });
  });

  const tables = [...tableSet];
  const tableList = [];

  tables.forEach((tableId) => {
    const tableDetails = findTableDetails(tableId);
    if (tableDetails?.table_name && tableInfo[tableDetails.table_name]) {
      const tableDetailsForDropDown = {
        label: tableDetails.table_name,
        value: tableId,
        options:
          tableInfo[tableDetails.table_name]?.map((columns) => ({
            label: columns.Header,
            value: columns.Header + '_' + tableId,
            table: tableId,
            icon: columns.dataType,
            columnId: columns.column_id,
          })) || [],
      };
      tableList.push(tableDetailsForDropDown);
    }
  });

  const sortbyConstants = [
    { label: 'Ascending', value: 'ASC' },
    { label: 'Descending', value: 'DESC' },
  ];

  return (
    <div className="p-0">
      {isEmpty(joinOrderByOptions) ? (
        <NoCondition />
      ) : (
        joinOrderByOptions.map((options, i) => {
          const tableDetails = options?.table ? findTableDetails(options?.table) : '';
          const resolvedColumnName = resolveColumnDisplayName(
            tableInfo[tableDetails?.table_name],
            options?.columnName,
            options?.columnId,
            'Header'
          );
          const isColumnJsonbType =
            tableInfo[tableDetails?.table_name]?.find((col) => col.accessor === resolvedColumnName)?.dataType ===
            'jsonb';
          return (
            <Row className="mb-2 mx-0 " key={i}>
              <Col sm="6" className="p-0">
                <DropDownSelect
                  buttonClasses={`border ${
                    isColumnJsonbType ? 'rounded-top-left' : 'rounded rounded-top-right-0 rounded-bottom-right-0'
                  }   overflow-hidden`}
                  showPlaceHolder
                  options={tableList}
                  darkMode={darkMode}
                  value={{
                    value: resolvedColumnName && options.table ? resolvedColumnName + '_' + options.table : '',
                    label: tableDetails?.table_name
                      ? tableDetails?.table_name + '.' + resolvedColumnName
                      : resolvedColumnName,
                    table: options.table,
                  }}
                  onChange={(option) => {
                    setJoinOrderByOptions(
                      joinOrderByOptions.map((sortBy, index) => {
                        if (i === index) {
                          return {
                            ...sortBy,
                            columnName: option?.label,
                            columnId: columnIdOf(option),
                            table: option.table,
                          };
                        }
                        return sortBy;
                      })
                    );
                  }}
                />
                {isColumnJsonbType && (
                  <div className="tjdb-codehinter-jsonpath">
                    <ToolTip
                      message={
                        options?.jsonpath
                          ? options.jsonpath
                          : 'Access nested JSON fields by using -> for JSON object and ->> for text'
                      }
                      tooltipClassName="tjdb-table-tooltip"
                      placement="top"
                      trigger={['hover', 'focus']}
                      width="160px"
                    >
                      <span>
                        <CodeHinter
                          type="basic"
                          initialValue={options?.jsonpath || ''}
                          lang="javascript"
                          onChange={(value) => {
                            setJoinOrderByOptions(
                              joinOrderByOptions.map((sortBy, index) => {
                                if (i === index) {
                                  return {
                                    ...sortBy,
                                    jsonpath: value,
                                  };
                                }
                                return sortBy;
                              })
                            );
                          }}
                          enablePreview={false}
                          height="30"
                          placeholder="->>'key'"
                          componentName={resolvedColumnName ? `{}${resolvedColumnName}` : ''}
                        />
                      </span>
                    </ToolTip>
                  </div>
                )}
              </Col>
              <Col sm="6" className="p-0 d-flex">
                <div className="flex-grow-1">
                  <DropDownSelect
                    buttonClasses="border border-start-0 border-end-0 overflow-hidden"
                    showPlaceHolder
                    options={sortbyConstants}
                    darkMode={darkMode}
                    value={sortbyConstants.find((opt) => opt.value === options.direction)}
                    onChange={(option) => {
                      setJoinOrderByOptions(
                        joinOrderByOptions.map((sortBy, index) => {
                          if (i === index) {
                            return {
                              ...sortBy,
                              direction: option?.value,
                            };
                          }
                          return sortBy;
                        })
                      );
                    }}
                  />
                </div>
                <ButtonSolid
                  size="sm"
                  variant="ghostBlack"
                  className="px-1 rounded-0 border rounded-end qm-delete-btn"
                  onClick={() => setJoinOrderByOptions(joinOrderByOptions.filter((opt, idx) => idx !== i))}
                >
                  <Trash fill="var(--slate9)" style={{ height: '16px' }} />
                </ButtonSolid>
              </Col>
            </Row>
          );
        })
      )}
      {/* Dynamically render below Row */}
      <Row className="mx-1 mb-1">
        <Col className="p-0">
          <ButtonSolid variant="ghostBlue" size="sm" onClick={() => setJoinOrderByOptions([...joinOrderByOptions, {}])}>
            <AddRectangle width="15" fill="#3E63DD" opacity="1" secondaryFill="#ffffff" />
            &nbsp;&nbsp; Add more
          </ButtonSolid>
        </Col>
      </Row>
    </div>
  );
}
import React, { useCallback } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import Trash from '@/_ui/Icon/solidIcons/Trash';
import AddRectangle from '@/_ui/Icon/bulkIcons/AddRectangle';
import { clone, isEmpty } from 'lodash';
import { useToolJetDbOperationsContext } from './ToolJetDbOperationsContext';
import DropDownSelect from './DropDownSelect';
import JoinConstraint from './JoinConstraint';
import JoinSelect from './JoinSelect';
import JoinSort from './JoinSort';
import { filterOperatorOptions, nullOperatorOptions, resolveColumnDisplayName, columnIdOf } from './util';
import CodeHinter from '@/AppBuilder/CodeEditor';
import { AggregateFilter } from './AggregateUI';
