const RenderFilterFields = ({
  column,
  columnId,
  operator,
  value,
  id,
  columns,
  updateFilterOptionsChanged,
  updateRowsOptions,
  darkMode,
  removeFilterConditionPair,
  jsonpath = '',
}) => {
  const resolvedColumn = resolveColumnDisplayName(columns, column, columnId);
  let displayColumns = columns.map(({ accessor, dataType, column_id }) => ({
    value: accessor,
    label: accessor,
    icon: dataType,
    columnId: column_id,
  }));

  operator = operators.find((val) => val.value === operator);

  const handleColumnChange = (selectedOption) => {
    updateFilterOptionsChanged({
      ...updateRowsOptions?.where_filters[id],
      ...{ column: selectedOption.value, columnId: columnIdOf(selectedOption) },
    });
  };

  const handleOperatorChange = (selectedOption) => {
    updateFilterOptionsChanged({ ...updateRowsOptions?.where_filters[id], ...{ operator: selectedOption.value } });
  };

  const handleValueChange = (newValue) => {
    updateFilterOptionsChanged({ ...updateRowsOptions?.where_filters[id], ...{ value: newValue } });
  };

  const handleJsonPathChange = (value) => {
    updateFilterOptionsChanged({
      ...updateRowsOptions?.where_filters[id],
      jsonpath: value,
    });
  };

  const isSelectedColumnJsonbType = columns.find((col) => col.accessor === resolvedColumn)?.dataType === 'jsonb';

  return (
    <RenderFilterSectionUI
      column={resolvedColumn}
      displayColumns={displayColumns}
      handleColumnChange={handleColumnChange}
      darkMode={darkMode}
      operator={operator}
      operators={operators}
      handleOperatorChange={handleOperatorChange}
      value={value}
      isOperatorOptions={isOperatorOptions}
      handleValueChange={handleValueChange}
      removeFilterConditionPair={removeFilterConditionPair}
      id={id}
      handleJsonPathChange={handleJsonPathChange}
      isSelectedColumnJsonbType={isSelectedColumnJsonbType}
      jsonpath={jsonpath}
    />
  );
};

const RenderColumnOptions = ({
  column,
  columnId,
  value,
  id,
  columns,
  updateRowsOptions,
  handleColumnOptionChange,
  darkMode,
  removeColumnOptionsPair,
}) => {
  const filteredColumns = columns.filter(({ column_default }) =>
    isObject(column_default) ? true : !column_default?.startsWith('nextval(')
  );

  const resolvedColumn = resolveColumnDisplayName(columns, column, columnId);
  const existingColumnOptions = Object.values(updateRowsOptions?.columns).map(({ column }) => column);
  let displayColumns = filteredColumns.map(({ accessor, dataType, column_id }) => ({
    value: accessor,
    label: accessor,
    icon: dataType,
    columnId: column_id,
  }));

  const currentColumnType = columns?.find((columnDetails) => columnDetails.accessor === resolvedColumn)?.dataType;

  if (existingColumnOptions.length > 0) {
    displayColumns = displayColumns.filter(
      ({ value }) => !existingColumnOptions.map((item) => item !== resolvedColumn && item).includes(value)
    );
  }

  const handleColumnChange = (selectedOption) => {
    const columnOptions = updateRowsOptions?.columns;
    const updatedOption = {
      ...columnOptions[id],
      column: selectedOption.value,
      columnId: columnIdOf(selectedOption),
    };

    const newColumnOptions = { ...columnOptions, [id]: updatedOption };
    handleColumnOptionChange(newColumnOptions);
  };

  const handleValueChange = (newValue) => {
    const columnOptions = updateRowsOptions?.columns;
    const updatedOption = {
      ...columnOptions[id],
      value: newValue,
    };

    const newColumnOptions = { ...columnOptions, [id]: updatedOption };

    handleColumnOptionChange(newColumnOptions);
  };

  return (
    <RenderColumnUI
      column={resolvedColumn}
      displayColumns={displayColumns}
      handleColumnChange={handleColumnChange}
      darkMode={darkMode}
      value={value}
      handleValueChange={handleValueChange}
      removeColumnOptionsPair={removeColumnOptionsPair}
      id={id}
      currentColumnType={currentColumnType}
    />
  );
};
import { get } from 'lodash';
/**
 * Checks if the queryOptions object contains a filter with an 'eq' (equal) operator and a value equal to '{{null}}'.
 *
 * @function hasNullValueInFilters
 * @param {Object} queryOptions - The query options object to check for the presence of the specified filter.
 * @property {Object} queryOptions.list_rows.where_filters - An object containing the filters to be checked.
 * @returns {boolean} - Returns true if the specified filter is found, false otherwise.
 *
 * @example
 * const queryOptions = {
 *   list_rows: {
 *     where_filters: {
 *       filter1: {
 *         operator: 'eq',
 *         value: '{{null}}',
 *       },
 *     },
 *   },
 * };
 *
 * const result = hasNullValueInFilters(queryOptions); // true
 */
export const hasNullValueInFilters = (queryOptions, operation) => {
  const filters = get(queryOptions, `${operation}.where_filters`);
  if (filters) {
    const filterKeys = Object.keys(filters);
    for (let i = 0; i < filterKeys.length; i++) {
      const filter = filters[filterKeys[i]];
      if (filter.operator !== 'is' && filter.value === null) {
        return true;
      }
    }
  }
  return false;
};

/**
 * Resolves a column's displayed name against a live column list: match by columnId first
 * (matches the backend's resolution order in tooljet-db-data-operations.service.ts), falling
 * back to the stored name string when there's no id, or the id no longer matches any column
 * (column deleted). Keeps pre-migration saved queries (no columnId) rendering unchanged.
 */
export const resolveColumnDisplayName = (columns, name, columnId, nameField = 'accessor', idField = 'column_id') => {
  if (columnId) {
    const match = columns?.find((col) => col?.[idField] === columnId);
    if (match) return match[nameField];
  }
  return name;
};

