      <div className="tj-accordion-close-btn">
        <button
          type="button"
          disabled={isDisabled}
          aria-label={isExpanded ? 'Collapse accordion' : 'Expand accordion'}
          data-cy={`accordion-close-button`}
          onClick={(e) => {
            if (isDisabled) return;
            e.stopPropagation();
            const expand = !isExpanded;
