            fireEvent(expand ? 'onExpand' : 'onCollapse');
          }}
        >
          <TablerIcon
            iconName="IconChevronUp"
            size={24}
            color={chevronIconColor}
            className={`tw-transition-transform tw-duration-200 ${isExpanded ? '' : 'tw-rotate-180'}`}
          />
