    });

  // Helpers
  const updateExposedVariablesState = (key, value) => {
    setExposedVariablesTemporaryState((prevState) => ({
      ...prevState,
      [key]: value,
    }));
  };

  const openMicPermissionsHelp = () => {
    window.open('https://support.google.com/chrome/answer/2693767', '_blank');
