            <RecorderActions
              accentColor={accentColor}
              status={status}
              permissionState={permissionState}
              onSave={onSave}
              onReset={onReset}
              openMicPermissionsHelp={openMicPermissionsHelp}
            />
          </div>
        </div>
      )}
    </div>
  );
