    labelColor,
    alignment,
    direction,
    auto: labelAutoWidth,
    labelWidth,
    backgroundColor,
    hoverBackgroundMode = 'auto',
    hoverBackgroundColor = 'var(--cc-primary-brand)',
    borderColor,
    textColor,
    textSize = 14,
    fontWeight = 'normal',
    iconColor,
    errTextColor,
    selectedBackgroundColor,
    selectedTextColor,
    selectedIconColor,
