    isTwentyFourHourMode,
    currentTimestamp: selectedTimestamp,
    onTimeChange,
    minTime,
    maxTime,
  };

  const customDateInputProps = {
    dateInputRef,
    onInputChange: onDateSelect,
    displayFormat: timeFormat,
    setDisplayTimestamp,
    setTextInputFocus,
    setShowValidationError,
    onTextParse: (parsed) => setTextParseError(parsed.hasError),
    showValidationError,
    isValid,
    validationError,
    showClearBtn,
    onClear: handleClear,
    inputPlaceholder: placeholder,
  };

  return (
    <BaseDateComponent
      styles={styles}
      height={height}
      disable={disable}
      loading={loading}
      darkMode={darkMode}
      label={label}
      focus={focus}
      visibility={visibility}
      isMandatory={isMandatory}
      componentName={componentName}
      datePickerRef={datePickerRef}
      componentProps={componentProps}
      customTimeInputProps={customTimeInputProps}
      customDateInputProps={customDateInputProps}
