                  }}
                  data-index={virtualItem.index}
                  ref={virtualizer.measureElement}
                >
                  <MenuList {...props} selectProps={selectProps}>
                    <div>{child}</div>
                  </MenuList>
                </div>
              );
            })}
          </div>
        </div>
      )}
      {optionsLoadingState && (
        <div className="text-center py-4" style={{ minHeight: '188px' }}>
          <Loader style={{ zIndex: 3, position: 'absolute' }} width="36" />
        </div>
      )}
    </div>
  );
};

