const typeResolver = (type) => {
  switch (type) {
    case 'textinput':
      return 'TextInput';
    case 'dropdown':
      return 'DropDown';
    case 'button':
      return 'Button';
    case 'emailinput':
      return 'EmailInput';
    case 'phoneinput':
      return 'PhoneInput';
    case 'currencyinput':
      return 'CurrencyInput';
    case 'text':
      return 'Text';
    case 'number':
      return 'NumberInput';
    case 'password':
      return 'PasswordInput';
    case 'datepicker':
      return 'Datepicker';
    case 'checkbox':
      return 'Checkbox';
    case 'radio':
      return 'RadioButton';
    case 'toggle':
      return 'ToggleSwitch';
    case 'textarea':
      return 'TextArea';
    case 'daterangepicker':
      return 'DaterangePicker';
    case 'multiselect':
      return 'Multiselect';
    case 'starrating':
      return 'StarRating';
    case 'filepicker':
      return 'FilePicker';
    default:
      return null;
  }
};

const validBooleanChecker = (input) => {
  if (/^(true|false)$/i.test(input) == true) return JSON.parse(input);
  return true;
};

export const getBodyHeight = (height, showHeader, showFooter, headerHeight = 60, footerHeight = 60) => {
  let modalHeight = height ? parseInt(height, 10) : 0;
  let parsedHeaderHeight = showHeader ? parseInt(headerHeight, 10) : 0;
  let parsedFooterHeight = showFooter ? parseInt(footerHeight, 10) : 0;

  if (showHeader) {
    // 10 is header padding
    modalHeight = modalHeight - parsedHeaderHeight - 10;
  }
  if (showFooter) {
    // 14 is footer padding
    modalHeight = modalHeight - parsedFooterHeight - 14;
  }

  const rounded = Math.ceil(modalHeight / 10) * 10;

  return `${Math.max(rounded - 20, 40)}px`;
};
import React, { useMemo, useCallback, Suspense } from 'react';
import { getComponentToRender } from '@/AppBuilder/_helpers/editorHelpers';
import useStore from '@/AppBuilder/_stores/store';
import { shallow } from 'zustand/shallow';

const RenderSchema = ({ component, parent, id, onOptionChange, onOptionsChange, darkMode }) => {
  const ComponentToRender = useMemo(() => getComponentToRender(component?.component), [component?.component]);
  const validateWidget = useStore((state) => state.validateWidget, shallow);

  const setExposedVariable = useCallback(
    (key, value) => {
      onOptionChange(component, key, value, id);
    },
    [id, onOptionChange]
  );

  const setExposedVariables = useCallback(
    (exposedValues) => {
      onOptionsChange(component, exposedValues, id);
    },
    [id, onOptionsChange]
  );

  const validate = useCallback(
    (value) => {
      return validateWidget({
        ...{ widgetValue: value },
        ...{ validationObject: component.definition.validation },
        componentType: component?.component,
      });
    },
    [component.definition.validation]
  );

  const fireEvent = useCallback(() => {
    return Promise.resolve();
  }, []);

  const formId = `${parent}-${id}`;
  return (
    <Suspense fallback="Loading...">
      <ComponentToRender
        properties={component?.definition?.properties}
        styles={component?.definition?.styles}
        generalProperties={component?.definition?.general}
        generalStyles={component?.definition?.generalStyles}
        width={component?.defaultSize?.width}
        height={component?.defaultSize?.height}
        setExposedVariable={setExposedVariable}
        setExposedVariables={setExposedVariables}
        validate={validate}
        darkMode={darkMode}
        fireEvent={fireEvent}
        formId={formId}
        id={id}
      />
    </Suspense>
  );
};

export default RenderSchema;
