import { useState, useCallback, useEffect, useLayoutEffect } from 'react';

export function useCalculateOverflow({
  containerRef,
  measurementContainerRef,
  visibleMenuItems,
  orientation,
  padding,
  width,
}) {
  const [links, setLinks] = useState({
    visible: visibleMenuItems,
    overflow: [],
  });

  const calculateOverflow = useCallback(() => {
    if (!containerRef.current || visibleMenuItems.length === 0) {
      setLinks({ visible: [], overflow: [] });
      return;
    }

    if (orientation !== 'horizontal') {
      setLinks({ visible: visibleMenuItems, overflow: [] });
      return;
    }

    // Use clientWidth (excludes border) and subtract both sides of padding
    const CONTAINER_PADDING = parseInt(padding) || 8;
    const availableWidth = containerRef.current.clientWidth - 2 * CONTAINER_PADDING;

    const measuredItems = measurementContainerRef.current?.children
      ? Array.from(measurementContainerRef.current.children)
      : [];

    if (measuredItems.length === 0) {
      setLinks({ visible: visibleMenuItems, overflow: [] });
      return;
    }

    // Match the CSS gap: 6px from navigation.scss .navigation-horizontal-list
    const FLEX_GAP = 6;
    const MORE_BUTTON_WIDTH = 80;

    let currentWidth = 0;
    const finalVisible = [];
    const finalOverflow = [];

    for (let i = 0; i < visibleMenuItems.length; i++) {
      const item = visibleMenuItems[i];
      const measuredElement = measuredItems.find((el) => el.dataset.id === item.id);

      if (!measuredElement) {
        finalOverflow.push(item);
        continue;
      }

      const itemWidth = measuredElement.offsetWidth;
      const widthNeeded = itemWidth + (finalVisible.length > 0 ? FLEX_GAP : 0);

      const remainingItems = visibleMenuItems.length - (i + 1);
      const needsMoreButton = remainingItems > 0 || finalOverflow.length > 0;
      const moreButtonSpace = needsMoreButton ? MORE_BUTTON_WIDTH + FLEX_GAP : 0;

      if (currentWidth + widthNeeded + moreButtonSpace <= availableWidth) {
        finalVisible.push(item);
        currentWidth += widthNeeded;
      } else {
        finalOverflow.push(item);
      }
    }

    while (
      finalOverflow.length > 0 &&
      finalVisible.length > 0 &&
      currentWidth + MORE_BUTTON_WIDTH + FLEX_GAP > availableWidth
    ) {
      const lastVisible = finalVisible.pop();
      const lastMeasured = measuredItems.find((el) => el.dataset.id === lastVisible.id);
      if (lastMeasured) {
        currentWidth -= lastMeasured.offsetWidth + (finalVisible.length > 0 ? FLEX_GAP : 0);
      }
      finalOverflow.unshift(lastVisible);
    }

    setLinks({ visible: finalVisible, overflow: finalOverflow });
  }, [visibleMenuItems, orientation, padding]);

  // Recalculate on resize and observe container size changes
  useLayoutEffect(() => {
    const handleResize = () => {
      requestAnimationFrame(calculateOverflow);
    };

    handleResize();

    window.addEventListener('resize', handleResize);

    // ResizeObserver catches container size changes that don't trigger window resize
    // (e.g., editor sidebar toggle, viewer layout settling)
    let resizeObserver;
    if (containerRef.current) {
      resizeObserver = new ResizeObserver(() => {
        requestAnimationFrame(calculateOverflow);
      });
      resizeObserver.observe(containerRef.current);
    }

    return () => {
      window.removeEventListener('resize', handleResize);
      if (resizeObserver) resizeObserver.disconnect();
    };
  }, [calculateOverflow]);

  // Recalculate when width changes
  useEffect(() => {
    calculateOverflow();
  }, [width, calculateOverflow]);

  return links;
}
// Guards against non-primitive fx-resolved values crashing JSX rendering.
export const toDisplayText = (value) => (typeof value === 'string' || typeof value === 'number' ? value : '');

// parseInt(value) || fallback would replace an explicit 0 with the fallback, since 0 is falsy.
export const parseStyleDimension = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isNaN(parsed) ? fallback : parsed;
};

export const isItemVisible = (item) =>
  typeof item.visible === 'object' ? item.visible.value !== '{{true}}' : item.visible !== true;

export const isItemDisabled = (item) =>
  typeof item.disable === 'object'
    ? item.disable.value === '{{true}}' || item.disable.value === true
    : item.disable === true;

// A group is only visible if it isn't hidden itself AND at least one of its children
// is visible. A child being disabled doesn't count against the group — disabled just
// means greyed-out/unclickable, not hidden, so it shouldn't hide the group.
export const isGroupVisible = (group) => {
  if (!isItemVisible(group)) return false;
  return Array.isArray(group.children) && group.children.some((child) => isItemVisible(child));
};

export const isMenuItemVisible = (item) => (item.isGroup ? isGroupVisible(item) : isItemVisible(item));

// Recursively replace an item (by id) anywhere in the tree, including inside group children
export const updateItemById = (items, targetId, updater) =>
  items.map((item) => {
    if (item.id === targetId) return updater(item);
    if (item.isGroup && item.children) {
      return { ...item, children: updateItemById(item.children, targetId, updater) };
    }
    return item;
  });

// Helper to find item by ID (including nested items)
export const findItemById = (items, targetId) => {
  for (const item of items) {
    if (item.id === targetId) return item;
    if (item.isGroup && item.children) {
      const found = findItemById(item.children, targetId);
      if (found) return found;
    }
  }
  return null;
};

// Helper to find parent group of an item
export const findParentGroup = (items, targetId) => {
  for (const item of items) {
    if (item.isGroup && item.children) {
      if (item.children.some((child) => child.id === targetId)) {
        return item;
      }
      const found = findParentGroup(item.children, targetId);
      if (found) return found;
    }
  }
  return null;
};
