const toCssWidth = (val) => {
  if (val === undefined || val === null) return null;
  if (typeof val === 'number') return `${val}px`;
  if (typeof val === 'string') {
    const trimmed = val.trim();
    if (!trimmed) return null;
    if (/^-?\d+(?:\.\d+)?$/.test(trimmed)) return `${trimmed}px`;
    return trimmed;
  }
  return null;
