          ref={sliderRef}
          trackStyle={rangeStyles.trackStyle}
          railStyle={rangeStyles.railStyle}
          handleStyle={rangeStyles.handleStyle}
          ariaLabelledByForHandle={`Range Slider with two handles, with min value ${min} and max value ${max}`}
        />
      ) : (
