    labelStyle,
    textColor: selectedBgColorStars,
    boxShadow,
    alignment,
    direction,
    auto,
    labelWidth,
    widthType,
    labelColor: labelTextColor,
    selectedBackgroundHearts,
    unselectedBackground,
