import { useInput } from './BaseComponents/hooks/useInput';

export const TextInput = (props) => {
  const transformedProps = {
    ...props,
    inputType: 'TextInput',
  };
  const inputLogic = useInput(transformedProps);
  const showClearBtn = props.properties?.showClearBtn;
  const handleClear = () => {
    inputLogic.setInputValue('');
    // Clearing is a completed action, not a keystroke, so it reveals any resulting error the way a blur does.
    inputLogic.setShowValidationError(true);
    props.fireEvent('onChange');
  };
  const getCustomStyles = (baseStyles) => {
    return {
      ...baseStyles,
      paddingRight: showClearBtn ? '25px' : '0px',
    };
  };
  return (
    <BaseInput
      {...props}
      {...inputLogic}
      inputType="text"
      showClearBtn={showClearBtn}
      onClear={handleClear}
      getCustomStyles={getCustomStyles}
    />
  );
};
import React from 'react';
import { isArray } from 'lodash';
import { getSafeRenderableValue } from './utils';
import { useDynamicHeight } from '@/_hooks/useDynamicHeight';

export const Timeline = function Timeline({
  id,
  height,
  width,
  darkMode,
  properties,
  styles,
  dataCy,
  currentLayout,
  currentMode,
  subContainerIndex,
  componentType,
}) {
  const { boxShadow } = styles;
  const { data, hideDate, visibility } = properties;

  const darkModeStyle = darkMode && 'text-white-50';

  const isDynamicHeightEnabled = properties.dynamicHeight && currentMode === 'view';
  // Timeline height is a function of its items (and whether dates show). Trigger the reflow
  // off that data rather than a DOM observer — width changes are already a hook dependency,
  // so text re-wrapping on resize is still re-measured.
  useDynamicHeight({
    isDynamicHeightEnabled,
    id,
    height,
    value: JSON.stringify({ data, hideDate }),
    currentLayout,
    width,
    visibility,
    subContainerIndex,
    componentType,
  });

  return (
    <div
      className="card"
      style={{
        display: visibility ? '' : 'none',
        height: isDynamicHeightEnabled ? 'auto' : height,
        ...(isDynamicHeightEnabled && { minHeight: height }),
        overflow: isDynamicHeightEnabled ? 'visible' : 'auto',
        overflowWrap: 'normal',
        boxShadow,
        backgroundColor: 'var(--cc-surface1-surface)',
      }}
      data-cy={dataCy}
    >
      <div className="card-body">
        <ul className={`list list-timeline ${hideDate && 'list-timeline-simple'}`}>
          {(isArray(data) ? data : []).map((item, index) => (
            <li key={index}>
              <div className="list-timeline-icon" style={{ backgroundColor: item.iconBackgroundColor }}></div>
              <div className="list-timeline-content">
                {!hideDate && (
                  <div className={`list-timeline-time ${darkModeStyle}`}>{getSafeRenderableValue(item.date)}</div>
                )}
                <p className="list-timeline-title">{getSafeRenderableValue(item.title)}</p>
                <p className={`${darkModeStyle || 'text-muted'}`}>{getSafeRenderableValue(item.subTitle)}</p>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};
import React, { useEffect, useMemo, useState } from 'react';

export const Timer = function Timer({ height, properties = {}, styles, setExposedVariable, fireEvent, dataCy }) {
  const getTimeObj = ({ HH, MM, SS, MS }) => {
    return {
      hour: isNaN(HH) ? 0 : parseInt(HH, 10),
      minute: !isNaN(MM) && MM <= 59 ? parseInt(MM, 10) : 0,
      second: !isNaN(SS) && SS <= 59 ? parseInt(SS, 10) : 0,
      mSecond: !isNaN(MS) && MS <= 999 ? parseInt(MS, 10) : 0,
    };
  };
  const getDefaultValue = useMemo(() => {
    const [HH, MM, SS, MS] = (properties.value && properties.value.split(':')) || [];
    return { HH, MM, SS, MS };
  }, [properties.value]);

  const [time, setTime] = useState(getTimeObj(getDefaultValue));
  const [state, setState] = useState('initial');
  const [intervalId, setIntervalId] = useState(0);

  const TimerType = {
    COUNTDOWN: 'countDown',
    COUNTUP: 'countUp',
  };

  useEffect(() => {
    if (
      properties.type === TimerType.COUNTDOWN &&
      time.mSecond === 0 &&
      time.second === 0 &&
      time.minute === 0 &&
      time.hour === 0
    ) {
      intervalId && clearInterval(intervalId);
      setState('initial');
      fireEvent('onCountDownFinish');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [time]);

  useEffect(() => {
    setExposedVariable('value', {});
  }, []);

  useEffect(() => {
    intervalId && clearInterval(intervalId);
    setState('initial');
    setTime(getTimeObj(getDefaultValue));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [properties.type, getDefaultValue]);

  useEffect(() => {
    return () => {
      intervalId && clearInterval(intervalId);
    };
  }, [intervalId]);

  const onReset = () => {
    intervalId && clearInterval(intervalId);
    setTime(getTimeObj(getDefaultValue));
    setExposedVariable('value', getTimeObj(getDefaultValue));
    fireEvent('onReset');
    setState('initial');
  };

  const onStart = (isResume) => {
    setIntervalId(
      setInterval(() => {
        setTime((previousTime) => {
          let HH = previousTime.hour,
            MM = previousTime.minute,
            SS = previousTime.second,
            MS = previousTime.mSecond;

          if (properties.type === TimerType.COUNTUP) {
            MS = MS + 15;
            if (MS >= 1000) {
              MS = MS - 1000;
              SS++;

              if (SS >= 60) {
                SS = SS - 60;
                MM++;

                if (MM >= 60) {
                  MM = MM - 60;
                  HH++;
                }
              }
            }
          } else if (properties.type === TimerType.COUNTDOWN) {
            MS = MS - 15;
            if (MS < 0) {
              MS = MS + 1000;
              SS--;

              if (SS < 0) {
                SS = SS + 60;
                MM--;

                if (MM < 0) {
                  MM = MM + 60;
                  HH--;

                  if (HH < 0) {
                    ((MS = 0), (SS = 0), (MM = 0), (HH = 0));
                  }
                }
              }
            }
          }
          return getTimeObj({ HH, MM, SS, MS });
        });
      }, 15)
    );
    setExposedVariable('value', time);
    setState('running');
    fireEvent(isResume ? 'onResume' : 'onStart');
  };

  const onPause = () => {
    intervalId && clearInterval(intervalId);
    setExposedVariable('value', time);
    setState('paused');
    fireEvent('onPause');
  };

  const onResume = () => {
    onStart(true);
  };

  const prependZero = (value, count = 1) => {
    if (!value) {
      return count === 2 ? '000' : '00';
    }
    if (count === 2) {
      return `${value.toString().length === 1 ? `00${value}` : value.toString().length === 2 ? `0${value}` : value}`;
    } else {
      return `${value.toString().length === 1 ? `0${value}` : value}`;
    }
  };

  const isCountDownFinished = () => {
    return time.hour === 0 && time.minute === 0 && time.second === 0 && time.mSecond === 0;
  };

  const isStartDisabled = () => {
    return properties.type === TimerType.COUNTDOWN && isCountDownFinished();
  };

  return (
    <div
      className="card"
      style={{
        height,
        display: styles.visibility ? '' : 'none',
        boxShadow: styles.boxShadow,
        backgroundColor: 'var(--cc-surface1-surface)',
      }}
      data-cy={dataCy}
    >
      <div className="timer-wrapper">
        <div className="counter-container">
          {`${prependZero(time.hour)}:${prependZero(time.minute)}:${prependZero(time.second)}:${prependZero(
            time.mSecond,
            2
          )}`}
        </div>
        <div className="btn-list justify-content-end">
          {state === 'initial' && (
            <a
              className={`btn btn-primary timer-btn${styles.disabledState || isStartDisabled() ? ' disabled' : ''}`}
              onClick={() => onStart()}
            >
              Start
            </a>
          )}
          {state === 'running' && (
            <a
              className={`btn btn-outline-primary timer-btn-hover ${styles.disabledState ? ' disabled' : ''}`}
              onClick={onPause}
            >
              Pause
            </a>
          )}
          {state === 'paused' && (
            <a
              className={`btn btn-outline-primary timer-btn-hover ${styles.disabledState ? ' disabled' : ''}`}
              onClick={onResume}
            >
              Resume
            </a>
          )}
          <a
            className={`btn${styles.disabledState ? ' disabled' : ''}`}
            style={{ color: 'var(--cc-primary-text)' }}
            onClick={onReset}
          >
            Reset
          </a>
        </div>
      </div>
    </div>
  );
};
import React, { useEffect } from 'react';
class Switch extends React.Component {
  render() {
    const { on, onClick, onChange, disabledState, color, visibility, id } = this.props;

    return (
      <label className="form-switch form-check-inline">
        <input
          style={{
            backgroundColor: on ? `${color}` : 'var(--cc-surface1-surface)',
            marginTop: '0px',
          }}
          className="form-check-input focus:!tw-shadow-none focus-visible:tw-ring-2 focus-visible:tw-ring-interactive-focus-outline focus-visible:tw-ring-offset-1"
          type="checkbox"
          id={`component-${id}`}
          checked={on}
          onChange={onChange}
          onClick={onClick}
          // native disabled: removes from tab order + blocks Space/click activation
          disabled={disabledState}
          aria-disabled={disabledState}
          aria-hidden={!visibility}
          aria-labelledby={`${id}-label`}
        />
      </label>
    );
  }
}

export const ToggleSwitch = ({ height, properties, styles, fireEvent, setExposedVariable, darkMode, dataCy, id }) => {
  // definition props
  const defaultValue = properties.defaultValue ?? false;
  const [on, setOn] = React.useState(defaultValue);
  const label = properties.label;

  const { visibility, disabledState, toggleSwitchColor, boxShadow } = styles;
  const textColor = darkMode && styles.textColor === '#000' ? '#fff' : styles.textColor;

  function toggleValue(e) {
    const toggled = e.target.checked;
    setExposedVariable('value', toggled);
    fireEvent('onChange');
  }

  // Exposing the initially set false value once on load
  useEffect(() => {
    setExposedVariable('value', defaultValue);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    setOn(defaultValue);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [defaultValue]);

  const toggle = () => setOn(!on);

  return (
    <div className="row py-1" style={{ height, display: visibility ? '' : 'none', boxShadow }} data-cy={dataCy}>
      <span
        className="form-check-label form-check-label col-auto my-auto"
        style={{ color: textColor }}
        id={`${id}-label`}
      >
        {label}
      </span>
      <div className="col px-1 py-0 mt-0">
        <Switch
          disabledState={disabledState}
          visibility={visibility}
          id={id}
          on={on}
          onClick={toggle}
          onChange={toggleValue}
          color={toggleSwitchColor}
        />
      </div>
    </div>
  );
};
import React, { useEffect, useRef, useState, useId } from 'react';
import Loader from '@/ToolJetUI/Loader/Loader';
import { useShowValidationOnFormSubmit, useFormClear } from '@/AppBuilder/Widgets/Form/FormSignalContext';
import OverflowTooltip from '@/_components/OverflowTooltip';

const Switch = ({
  on,
  onClick,
  onChange,
  disabledState,
  color,
  alignment,
  borderColor,
  setOn,
  styles,
  fireEvent,
  setUserInteracted,
  visibility,
  isMandatory,
  isValid,
  inputId,
}) => {
  const handleToggleChange = () => {
    if (disabledState) return;
    setOn(!on);
    fireEvent('onChange');
    setUserInteracted(true);
  };

  const switchStyle = {
    position: 'relative',
    display: 'inline-block',
    width: '28px',
    height: '18px',
    marginRight: '0px',
    paddingRight: '0px',
  };

  const sliderStyle = {
    position: 'absolute',
    cursor: 'pointer',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: on ? styles.toggleSwitchColor : styles.uncheckedColor,
    transition: 'background-color 0.2s',
    borderRadius: '34px',
    outline: `1px solid ${styles.borderColor}`,
  };

  const circleStyle = {
    position: 'absolute',
    content: '',
    height: '12px',
    width: '12px',
    left: '2px',
    bottom: '3px',
    backgroundColor: styles.handleColor,
    transition: 'transform 0.2s',
    borderRadius: '50%',
    transform: on ? 'translateX(12px)' : 'translateX(0)',
  };

  return (
    <div>
      <div className="d-flex" style={switchStyle} onClick={handleToggleChange}>
        <input
          type="checkbox"
          id={inputId}
          style={{
            opacity: 0,
            width: 0,
            height: 0,
            backgroundColor: on ? `${color}` : 'white',
            marginTop: '0px',
            marginLeft: alignment === 'left' && '-2rem',
            border: `1 px solid ${borderColor}`,
          }}
          // native disabled: removes the (hidden, focusable) input from the tab
          // order + blocks Space; the wrapper div's onClick is guarded separately
          disabled={disabledState}
          aria-disabled={disabledState}
          aria-hidden={!visibility}
          aria-required={isMandatory}
          aria-invalid={!isValid}
          className="form-check-input tw-peer"
          checked={on}
          onChange={onChange}
          onClick={onClick}
        />

        <span
          className="peer-focus-visible:tw-ring-2 peer-focus-visible:tw-ring-interactive-focus-outline peer-focus-visible:tw-ring-offset-1"
          style={sliderStyle}
        >
          <span style={circleStyle}></span>
        </span>
      </div>
    </div>
  );
};

export const ToggleSwitchV2 = ({
  height,
  properties,
  styles,
  fireEvent,
  setExposedVariable,
  setExposedVariables,
  dataCy,
  validation,
  componentName,
  validate,
  width,
}) => {
  const isInitialRender = useRef(true);
  const reactId = useId();
  const inputId = `component-${reactId}`;
  const defaultValue = properties.defaultValue ?? false;
  const [on, setOn] = useState(Boolean(defaultValue));
  const label = properties.label;
  const isMandatory = validation?.mandatory ?? false;
  const [validationStatus, setValidationStatus] = useState(validate(on));
  const { isValid, validationError } = validationStatus;
  const [loading, setLoading] = useState(properties?.loadingState);
  const [disable, setDisable] = useState(properties.disabledState || properties.loadingState);
  const [visibility, setVisibility] = useState(properties.visibility);
  const [userInteracted, setUserInteracted] = useState(false);
  useShowValidationOnFormSubmit(setUserInteracted);

  const { toggleSwitchColor, boxShadow, alignment, borderColor } = styles;
  const textColor = styles.textColor === '#1B1F24' ? 'var(--text-primary)' : styles.textColor;

  const toggleValue = (e) => {
    const toggled = e.target.checked;
    setExposedVariable('value', toggled);
    fireEvent('onChange');
    setUserInteracted(true);
  };
  // Exposing the initially set false value once on load

  const setInputValue = (value) => {
    setOn(value);
    setExposedVariable('value', value);
    const validationStatus = validate(value);
    setValidationStatus(validationStatus);
    setExposedVariable('isValid', validationStatus?.isValid);
  };

  useEffect(() => {
    if (isInitialRender.current) return;
    // eslint-disable-next-line react-hooks/exhaustive-deps

    setInputValue(defaultValue);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [defaultValue]);

  const toggle = () => {
    setInputValue(!on);
    setUserInteracted(true);
  };

  useEffect(() => {
    if (disable !== properties.disabledState) setDisable(properties.disabledState);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [properties.disabledState]);

  useEffect(() => {
    if (visibility !== properties.visibility) setVisibility(properties.visibility);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [properties.visibility]);

  useEffect(() => {
    if (loading !== properties.loadingState) setLoading(properties.loadingState);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [properties.loadingState]);

  useEffect(() => {
    if (isInitialRender.current) return;
    setExposedVariable('label', label);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [label]);

  useEffect(() => {
    if (isInitialRender.current) return;
    setExposedVariable('isMandatory', isMandatory);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isMandatory]);

  useEffect(() => {
    if (isInitialRender.current) return;
    const validationStatus = validate(on);
    setValidationStatus(validationStatus);
    setExposedVariable('isValid', validationStatus?.isValid);
  }, [validate]);

  useEffect(() => {
    if (isInitialRender.current) return;
    setExposedVariable('isLoading', loading);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading]);
  useEffect(() => {
    if (isInitialRender.current) return;
    setExposedVariable('isVisible', visibility);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visibility]);

  useEffect(() => {
    if (isInitialRender.current) return;
    setExposedVariable('isDisabled', disable);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [disable]);

  useEffect(() => {
    const exposedVariables = {
      setValue: async function (value) {
        setInputValue(value);
        setUserInteracted(true);
      },
      setVisibility: async function (state) {
        setVisibility(!!state);
        setExposedVariable('isVisible', !!state);
      },
      setDisable: async function (disable) {
        setDisable(!!disable);
        setExposedVariable('isDisabled', !!disable);
      },
      setLoading: async function (loading) {
        setLoading(!!loading);
        setExposedVariable('isLoading', !!loading);
      },
      label: label,
      isMandatory: isMandatory,
      isLoading: loading,
      isVisible: visibility,
      isDisabled: disable,
      isValid: isValid,
      value: defaultValue,
    };
    setExposedVariables(exposedVariables);
    isInitialRender.current = false;
  }, []);

  useEffect(() => {
    setExposedVariable('toggle', async function () {
      setInputValue(!on);
      fireEvent('onChange');
      setUserInteracted(true);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [on]);

  useFormClear(() => setInputValue(false));

  const renderInput = () => (
    <div
      data-disabled={properties.disabledState}
      className={`${alignment === 'right' ? 'flex-row-reverse' : 'flex-row'}`}
      style={{
        display: visibility ? 'flex' : 'none',
        boxShadow,
        alignItems: loading && 'center',
        gap: '6px ',
        justifyContent: `${properties.loadingState ? 'center' : alignment === 'left' ? 'space-between' : 'start'}`,
        height,
        whiteSpace: 'nowrap',
        paddingTop: '3px',
      }}
      data-cy={dataCy}
    >
      {loading ? (
        <Loader width="16" />
      ) : (
        <>
          <OverflowTooltip
            className="form-check-label"
            style={{
              lineHeight: '20px',
              color: textColor,
              fontWeight: 400,
              fontSize: '14px',
            }}
            whiteSpace="normal"
            width={width - 20}
          >
            <label htmlFor={inputId}>{label}</label>
            {isMandatory && <span style={{ color: 'var(--cc-error-systemStatus)', marginLeft: '1px' }}>{'*'}</span>}
          </OverflowTooltip>

          <Switch
            disabledState={disable}
            on={on}
            onClick={toggle}
            onChange={toggleValue}
            color={toggleSwitchColor}
            alignment={alignment}
            isValid={isValid}
            properties={properties}
            borderColor={borderColor}
            setOn={setInputValue}
            styles={styles}
            fireEvent={fireEvent}
            setUserInteracted={setUserInteracted}
            visibility={visibility}
            isMandatory={isMandatory}
            inputId={inputId}
          />
        </>
      )}
    </div>
  );

  return (
    <div
      style={{
        justifyContent: `${loading ? 'center' : 'flex-start'}`,
      }}
    >
      {renderInput()}
      {userInteracted && visibility && !isValid && (
        <div
          data-cy={`${String(componentName).toLowerCase()}-invalid-feedback`}
          style={{
            color: 'var(--cc-error-systemStatus)',
            fontSize: '11px',
            fontWeight: '400',
            lineHeight: '16px',
          }}
        >
          {validationError}
        </div>
      )}
    </div>
  );
};
import React from 'react';
const DASH_WIDTH = 4;
const DASH_GAP = 4;

export const VerticalDivider = function Divider({ styles, height, width, dataCy, darkMode, properties }) {
  const { dividerColor, boxShadow, dividerStyle } = styles;
  const color =
    dividerColor === '' || ['#000', '#000000'].includes(dividerColor) ? (darkMode ? '#fff' : '#000') : dividerColor;

  return (
    <div
      className="justify-content-center"
      style={{ display: properties?.visibility ? 'flex' : 'none', width: '100%', height: '100%' }}
