        Object.keys(propertyObj).forEach((type) => {
          const color = propertyObj[type][mode];
          root.style.setProperty(`--cc-${camelCase(type)}-${camelCase(category)}`, `${color}`);
          if (type === 'placeholder' && category === 'text') {
