        if (page == 3) {
          setIsLoading(true);
          setCompleted(true);
        }
      }}
      data-cy="continue-button"
    >
      {isLoading ? (
        <div className="spinner-center">
          <Spinner />
        </div>
      ) : (
        <>
          <p className="mb-0">Continue</p>
          <EnterIcon
            className="enter-icon-onboard"
            fill={
              (Object.values(formData)[page] == '' && page !== 3) || isLoading
                ? darkMode
                  ? '#656565'
                  : ' #D1D5DB'
                : '#fff'
            }
          />
        </>
      )}
    </button>
  );
}

