          window.location.href = buildURLWithQuery(data.redirect_url, {
            ...(organizationId ? { oid: organizationId } : {}),
            ...(source ? { source } : {}),
          });
          return;
        }
        setUserDetails(data);
        setIsLoading(false);
        if (data?.email !== '') {
          if (organizationToken) {
            setShowJoinWorkspace(true);
            return;
          }
          setVerifiedToken(true);
        }
      })
      .catch(({ error }) => {
        setIsLoading(false);
