      }
    >
      <Button
        className={classnames('left-sidebar-item', btnClassName)}
        onClick={toggleDarkMode}
        variant="ghost"
        size={toggleSize}
        iconOnly
      >
        {darkMode ? (
          <Sun width="16" height="16" className="tw-text-icon-strong" />
        ) : (
          <Moon width="16" height="16" className="tw-text-icon-strong" />
        )}
      </Button>
    </OverlayTrigger>
  );
};
