        return Zendesk;
      case 'columns':
        return MultiColumn;
      case 'filters':
        return ConditionFilter;
      case 'sorts':
        return CondtionSort;
      case 'react-component-api-endpoint':
        return ApiEndpointInput;
      case 'react-component-api-endpoint-old':
        return ApiEndpointInputOld;
      case 'react-component-sharepoint':
        return Sharepoint;
