      case 'react-component-sort': {
        let isRenderedAsQueryEditor;
        if (isGDS) {
          isRenderedAsQueryEditor = false;
        } else {
          isRenderedAsQueryEditor = !isGDS;
        }
        return {
          getter: key,
          options: isRenderedAsQueryEditor
            ? (options?.[key] ?? schema?.defaults?.[key])
            : (options?.[key]?.value ?? schema?.defaults?.[key]?.value),
          optionchanged,
          isRenderedAsQueryEditor,
          workspaceConstants: currentOrgEnvironmentConstants,
          isDisabled:
            isWorkspaceBranchLocked || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          encrypted: options?.[key]?.encrypted,
          buttonText,
          width: width,
        };
      }
      case 'react-component-oauth-authentication':
        return {
          isGrpc: source === 'grpc' || source === 'grpcv2',
          grant_type: options?.grant_type?.value,
          auth_type: options?.auth_type?.value,
          add_token_to: options?.add_token_to?.value,
          header_prefix: options?.header_prefix?.value,
          access_token_url: options?.access_token_url?.value,
          access_token_custom_headers: options?.access_token_custom_headers?.value,
          client_id: options?.client_id?.value,
          client_secret: options?.client_secret?.value,
          client_auth: options?.client_auth?.value,
          scopes: options?.scopes?.value,
          username: options?.username?.value,
          password: options?.password?.value,
          grpc_apiKey_key: options?.grpc_apikey_key?.value,
          grpc_apiKey_value: options?.grpc_apikey_value?.value,
          bearer_token: options?.bearer_token?.value,
          auth_url: options?.auth_url?.value,
          auth_key: options?.auth_key?.value,
          audience: options?.audience?.value,
          custom_auth_params: options?.custom_auth_params?.value,
          custom_query_params: options?.custom_query_params?.value,
          multiple_auth_enabled: options?.multiple_auth_enabled?.value,
          optionchanged,
          workspaceConstants: currentOrgEnvironmentConstants,
          isDisabled:
            isWorkspaceBranchLocked || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          options,
          optionsChanged,
          selectedDataSource,
          isRestApi: source === 'restapi',
        };
      case 'react-component-google-sheets':
      case 'react-component-slack':
      case 'react-component-zendesk':
      case 'react-component-sharepoint':
      case 'react-component-oauth':
        return {
          optionchanged,
          createDataSource,
          options,
          isSaving,
          selectedDataSource,
          currentAppEnvironmentId,
          workspaceConstants: currentOrgEnvironmentConstants,
          // Permission-only — branch-lock is passed separately so the OAuth save button
          // can still enable when an encrypted field is edited on the default branch.
          isDisabled: !canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource(),
          isWorkspaceBranchLocked,
          optionsChanged,
          multiple_auth_enabled: options?.multiple_auth_enabled?.value,
          scopes: options?.scopes?.value,
          oauth_configs,
        };
      case 'tooljetdb-operations':
        return {
          optionchanged,
          createDataSource,
          options,
          isSaving,
          selectedDataSource,
          darkMode,
          optionsChanged,
          renderCopilot,
        };
      case 'codehinter': {
        let theme;
        if (darkMode) {
          theme = 'monokai';
        } else if (lineNumbers) {
          theme = 'duotone-light';
        } else {
          theme = 'default';
        }
        return {
          type: editorType,
          initialValue: options[key]
            ? typeof options[key] === 'string'
              ? options[key]
              : JSON.stringify(options[key])
            : initialValue,
          lang: mode,
          lineNumbers,
          className: className ? className : lineNumbers ? 'query-hinter' : 'codehinter-query-editor-input',
          onChange: (value) => optionchanged(key, value),
          theme: theme,
          placeholder,
          height,
          width,
          componentName: queryName ? `${queryName}::${key ?? ''}` : null,
          cyLabel: label
            ? generateCypressDataCy(label)
            : key
              ? `${String(key).toLocaleLowerCase().replace(/\s+/g, '-')}`
              : '',
          disabled,
          delayOnChange: false,
          renderCopilot,
          ...(helpText && { helpText }),
        };
      }
      case 'react-component-openapi-validator':
        return {
          selectedDataSource,
          isSaving,
          currentAppEnvironmentId,
          multiple_auth_enabled: options?.multiple_auth_enabled?.value,
          format: options.format?.value,
          definition: options.definition?.value,
          auth_type: options.auth_type?.value,
          auth_key: options.auth_key?.value,
          username: options.username?.value,
          password: options.password?.value,
          bearer_token: options.bearer_token?.value,
          api_keys: options.api_keys?.value,
          optionchanged,
          grant_type: options.grant_type?.value,
          add_token_to: options.add_token_to?.value,
          header_prefix: options.header_prefix?.value,
          access_token_url: options.access_token_url?.value,
          access_token_custom_headers: options.access_token_custom_headers?.value,
          client_id: options.client_id?.value,
          client_secret: options.client_secret?.value,
          client_auth: options.client_auth?.value,
          scopes: options.scopes?.value,
          auth_url: options.auth_url?.value,
          custom_auth_params: options.custom_auth_params?.value,
          custom_query_params: options.custom_query_params?.value,
          spec: options.spec?.value,
          audience: options?.audience?.value,
          workspaceConstants: currentOrgEnvironmentConstants,
          isDisabled:
            isWorkspaceBranchLocked || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          optionsChanged,
        };
      case 'filters':
        return {
          operators: list || [],
          value: options?.[key] ?? {},
          onChange: (value) => optionchanged(key, value),
          placeholders,
        };
      case 'sorts':
        return {
          orders: list || [],
          value: options?.[key] ?? {},
          onChange: (value) => optionchanged(key, value),
          placeholders,
        };
      case 'columns':
        return {
          value: options?.[key] ?? {},
          onChange: (value) => optionchanged(key, value),
          placeholders,
        };
      case 'react-component-api-endpoint':
        return {
          specUrl: spec_url,
          optionsChanged,
          options,
          darkMode,
        };
      case 'react-component-api-endpoint-old':
        return {
          specUrl: spec_url,
          optionsChanged,
          options,
          darkMode,
        };
      case 'dynamic-selector':
        return {
          operation: operation,
          dependsOn: dependsOn || depends_on,
          selectedDataSource,
          currentAppEnvironmentId,
          optionchanged,
          options,
          label: label,
          description,
          disabled,
          computeSelectStyles,
          disableMenuPortal,
          queryName,
          propertyKey: key,
          value: options?.[key]?.value || options?.[key],
          optionsChanged,
          fxEnabled: fxEnabled || fx_enabled,
          isMulti: isMulti || false,
          autoFetch: autoFetch || false,
          pagination: pagination || false,
          pageSize: pageSize || 25,
        };
      case 'react-component-sql-filters':
        return {
          getter: key,
          parseKey: parse_key,
          options: options,
          handleOptionChange: (changeKey, changeValue) => optionchanged(changeKey, changeValue),
          workspaceConstants: currentOrgEnvironmentConstants,
          columnSelectorOperation: columnSelectorOperation,
          columnSelectorDependsOn: columnSelectorDependsOn || [],
          selectedDataSource,
          currentAppEnvironmentId,
          queryName,
        };
      case 'react-component-sql-columns':
      case 'react-component-sql-sort':
      case 'react-component-sql-groupby':
      case 'react-component-sql-aggregate':
        return {
          getter: key,
          parseKey: parse_key,
          options: options,
          handleOptionChange: (changeKey, changeValue) => optionchanged(changeKey, changeValue),
          workspaceConstants: currentOrgEnvironmentConstants,
          darkMode,
          columnSelectorOperation: columnSelectorOperation,
          columnSelectorDependsOn: columnSelectorDependsOn || [],
          selectedDataSource,
          currentAppEnvironmentId,
          queryName,
        };
      default:
        return {};
    }
  };

  const getLayout = (obj) => {
    if (isEmpty(obj)) return null;
    const flipComponentDropdown = isFlipComponentDropdown(obj);

    if (flipComponentDropdown) {
      return flipComponentDropdown;
    }

    const handleEncryptedFieldsToggle = (event, field) => {
      if (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()) {
        return;
      }
      const isEditing = computedProps[field]['disabled'];
      const workspaceConstant = options?.[field]?.workspace_constant;
      const isWorkspaceConstant = !!workspaceConstant;

      if (isEditing) {
        if (isWorkspaceConstant) {
          optionchanged(field, workspaceConstant);
        } else {
          optionchanged(field, '');
        }
      } else {
        const newOptions = { ...options };
        const oldFieldValue = selectedDataSource?.['options']?.[field];
        if (oldFieldValue) {
          optionsChanged({ ...newOptions, [field]: oldFieldValue });
        } else {
          delete newOptions[field];
          optionsChanged({ ...newOptions });
        }
      }
      setComputedProps({
        ...computedProps,
        [field]: {
          ...computedProps[field],
          disabled: !isEditing,
        },
      });
    };

    const renderLabel = (label, tooltip, fieldType) => {
      const labelElement = (
        <label
          className="form-label"
          data-cy={
            fieldType === 'dropdown'
              ? `${generateCypressDataCy(label)}-dropdown-label`
              : `${generateCypressDataCy(label)}-label`
          }
          style={{
            textDecoration: tooltip ? 'underline 2px dashed' : 'none',
            textDecorationColor: 'var(--slate8)',
            marginBottom: '2px',
          }}
        >
          {label}
        </label>
      );

      if (tooltip) {
        return (
          <OverlayTrigger
            placement="top"
            trigger="click"
            rootClose
            overlay={<Tooltip id={`tooltip-${label}`}>{tooltip}</Tooltip>}
          >
            {labelElement}
          </OverlayTrigger>
        );
      }

      return labelElement;
    };

    return (
      <div className={`${isHorizontalLayout ? '' : 'row'}`}>
        {Object.keys(obj).map((key) => {
          const fieldConfig = obj[key];
          const { label, type, encrypted, className, key: propertyKey, shouldRenderTheProperty = '' } = fieldConfig;

          const Element = getElement(type);
          const isSpecificComponent = [
            'tooljetdb-operations',
            'react-component-api-endpoint',
            'react-component-api-endpoint-old',
            'react-component-oauth',
          ].includes(type);
          // shouldRenderTheProperty - key is used for Dynamic connection parameters
          const enabled = shouldRenderTheProperty
            ? (selectedDataSource?.options?.[shouldRenderTheProperty]?.value ?? false)
            : true;

          // const elementProps = getElementProps({
          //   ...fieldConfig,
          //   key,
          //   type,
          // });

          return (
            enabled && (
              <div
                className={cx({
                  'my-2': type !== 'react-component-oauth', // Remove my-2 for react-component-oauth to prevent gap
                  'col-md-12': !className && !isHorizontalLayout && type !== 'react-component-oauth',
                  [className]: !!className,
                  'd-flex': isHorizontalLayout,
                  'dynamic-form-row': isHorizontalLayout,
                })}
                data-cy={`${generateCypressDataCy(label ?? key)}-section`}
                key={key}
              >
                {!isSpecificComponent && (
                  <div
                    className={cx('d-flex', {
                      'form-label': isHorizontalLayout,
                      'align-items-center': !isHorizontalLayout,
                    })}
                    style={{ minWidth: '100px', marginBottom: '0' }}
                  >
                    {label && renderLabel(label, obj[key].tooltip, type)}

                    {(type === 'password' || encrypted) && selectedDataSource?.id && (
                      <div className="mx-1 col">
                        <ButtonSolid
                          className="datasource-edit-btn mb-2"
                          type="a"
                          variant="tertiary"
                          target="_blank"
                          rel="noreferrer"
                          disabled={!canUpdateDataSource() && !canDeleteDataSource()}
                          onClick={(event) => handleEncryptedFieldsToggle(event, propertyKey)}
                          data-cy={`${generateCypressDataCy(
                            computedProps?.[propertyKey]?.['disabled'] ? 'Edit' : 'Cancel'
                          )}-button`}
                        >
                          {computedProps?.[propertyKey]?.['disabled'] ? 'Edit' : 'Cancel'}
                        </ButtonSolid>
                      </div>
                    )}
                    {(type === 'password' || encrypted) && (
                      <div className="col-auto mb-2">
                        <small className="text-green" data-cy="encrypted-text">
                          <img
                            className="mx-2 encrypted-icon"
                            src="assets/images/icons/padlock.svg"
                            width="12"
                            height="12"
                          />
                          Encrypted
                        </small>
                      </div>
                    )}
                  </div>
                )}
                <div
                  className={cx(
                    {
                      'flex-grow-1': isHorizontalLayout && !isSpecificComponent,
                      'w-100': isHorizontalLayout && type !== 'codehinter',
                    },
                    'dynamic-form-element'
                  )}
                  style={{ width: '100%' }}
                  data-cy={
                    type === 'dropdown' || type === 'dropdown-component-flip'
                      ? `${generateCypressDataCy(label ?? key)}-select-dropdown`
                      : `${generateCypressDataCy(label ?? key)}-${generateCypressDataCy(type ?? key)}-element`
                  }
                >
                  <Element
                    key={`${selectedDataSource?.id}-${propertyKey}`}
                    {...getElementProps(obj[key])}
                    {...computedProps[propertyKey]}
                    data-cy={`${generateCypressDataCy(label)}-text-field`}
                    dataCy={generateCypressDataCy(obj[key].label ?? obj[key].key)}
                    isHorizontalLayout={isHorizontalLayout}
                  />
                </div>
              </div>
            )
          );
        })}
      </div>
    );
  };

  const FlipComponentDropdown = (obj) => {
    const flipComponentDropdowns = filter(obj, ['type', 'dropdown-component-flip']);

    const dropdownComponents = flipComponentDropdowns.map((flipComponentDropdown) => {
      const selector = options?.[flipComponentDropdown?.key]?.value || options?.[flipComponentDropdown?.key];

      return (
        <div key={flipComponentDropdown.key}>
          <div className={isHorizontalLayout ? '' : 'row'}>
            {flipComponentDropdown.commonFields && getLayout(flipComponentDropdown.commonFields)}

            <div
              className={cx('my-2', {
                'col-md-12': !flipComponentDropdown.className && !isHorizontalLayout,
                'd-flex': isHorizontalLayout,
                'dynamic-form-row': isHorizontalLayout,
                [flipComponentDropdown.className]: !!flipComponentDropdown.className,
              })}
              data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-section`}
            >
              {(flipComponentDropdown.label || isHorizontalLayout) && (
                <label
                  className={cx('form-label')}
                  data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-dropdown-label`}
                  style={{ marginBottom: '2px' }}
                >
                  {flipComponentDropdown.label}
                </label>
              )}

              <div
                data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-select-dropdown`}
                className={cx({ 'flex-grow-1': isHorizontalLayout })}
              >
                <Select
                  {...getElementProps(flipComponentDropdown)}
                  styles={computeSelectStyles ? computeSelectStyles('100%') : {}}
                  useCustomStyles={computeSelectStyles ? true : false}
                  dataCy={generateCypressDataCy(flipComponentDropdown.label)}
                />
              </div>
              {flipComponentDropdown.helpText && (
                <span className="flip-dropdown-help-text">{flipComponentDropdown.helpText}</span>
              )}
            </div>
          </div>

          {getLayout(obj[selector])}
        </div>
      );
    });

    const normalComponents = Object.keys(obj).map((key) => {
      const component = obj[key];

      if (component.type && component.type !== 'dropdown-component-flip') {
        return <div key={key}>{getLayout({ [key]: component })}</div>;
      }
      return null;
    });

    return (
      <>
        {normalComponents}
        {dropdownComponents}
      </>
    );
  };

  const isFormComponent = (obj, getLayout) => {
    const formComponent = find(obj, ['type', 'react-form-component']);
    if (formComponent) {
      return <AccordionForm formComponent={formComponent} getLayout={getLayout} />;
    }
    return null;
  };

  const isFlipComponentDropdown = (obj) => {
    const checkFlipComponents = filter(obj, ['type', 'dropdown-component-flip']);
    if (checkFlipComponents.length > 0) {
      return FlipComponentDropdown(obj);
    } else {
      return null;
    }
  };

  const flipComponentDropdown = isFlipComponentDropdown(schema.properties);
  const formComponent = isFormComponent(schema.properties, getLayout);

  if (flipComponentDropdown) {
    return flipComponentDropdown;
  }
  if (formComponent) {
    return formComponent;
  }

  return getLayout(schema.properties);
};

export default DynamicForm;
import React from 'react';
import cx from 'classnames';
import DataSourceSchemaManager from '@/_helpers/dataSourceSchemaManager';
import Textarea from '@/_ui/Textarea';
import Input from '@/_ui/Input';
import Select from '@/_ui/Select';
import Headers from '@/_ui/HttpHeaders';
import OAuthWrapper from './OAuthWrapper';
import Toggle from '@/_ui/Toggle';
import ToggleV2 from '@/_ui/ToggleV2';
import InputV3 from '@/_ui/Input-V3';
import SqlFilters from '@/_components/SqlFilters';
import SqlColumns from '@/_components/SqlColumns';
import SqlSort from '@/_components/SqlSort';
import SqlGroupBy from '@/_components/SqlGroupBy';
import SqlAggregate from '@/_components/SqlAggregate';
import { filter, find, isEmpty } from 'lodash';
import { useGlobalDataSourcesStatus } from '@/_stores/dataSourcesStore';
import { canDeleteDataSource, canUpdateDataSource } from '@/_helpers';
import { OverlayTrigger, Tooltip } from 'react-bootstrap';
import { orgEnvironmentConstantService } from '../_services';
import { Constants } from '@/_helpers/utils';
import { generateCypressDataCy } from '../modules/common/helpers/cypressHelpers.js';
import { Checkbox, CheckboxGroup } from '@/_ui/CheckBox';
import { getAutoFillStrategy } from '@/_helpers/autoFillRegistry';
import { useConnectionStringAutoFill } from '@/_hooks/useConnectionStringAutofill';
import OracleWalletPicker from '@/_components/OracleWalletPicker';

const DynamicFormV2 = ({
  schema,
  options,
  optionchanged,
  optionsChanged,
  selectedDataSource,
  isEditMode,
  layout = 'vertical',
  onBlur,
  setDefaultOptions,
  currentAppEnvironmentId,
  isGDS,
  validationMessages,
  setValidationMessages,
  clearValidationMessages,
  showValidationErrors,
  clearValidationErrorBanner,
  elementsProps = null,
  isWorkspaceBranchLocked = false,
  createDataSource = null,
  isSaving = false,
}) => {
  const uiProperties = schema['tj:ui:properties'] || {};
  const dsm = React.useMemo(() => new DataSourceSchemaManager(schema), [schema]);
  const encryptedProperties = React.useMemo(() => dsm.getEncryptedProperties(), [dsm]);
  const [conditionallyRequiredProperties, setConditionallyRequiredProperties] = React.useState([]);
  const [workspaceVariables, setWorkspaceVariables] = React.useState([]);
  const [currentOrgEnvironmentConstants, setCurrentOrgEnvironmentConstants] = React.useState([]);
  const [computedProps, setComputedProps] = React.useState({});
  const [hasUserInteracted, setHasUserInteracted] = React.useState(false);
  const [interactedFields, setInteractedFields] = React.useState(new Set());

  const isHorizontalLayout = layout === 'horizontal';
  const prevDataSourceIdRef = React.useRef(selectedDataSource?.id);

  const globalDataSourcesStatus = useGlobalDataSourcesStatus();
  const { isEditing: isDataSourceEditing } = globalDataSourcesStatus;

  // --- Abstracted autofill ---
  const autoFillStrategy = React.useMemo(() => getAutoFillStrategy(schema), [schema]);

  const { handleManualFieldEdit } = useConnectionStringAutoFill({
    strategy: autoFillStrategy,
    options,
    optionsChanged,
    selectedDataSource,
  });

  // --- Workspace constants ---
  const lastAutoFilledConnRef = React.useRef('');
  const autoFillTimeoutRef = React.useRef(null);
  const manuallyEditedFieldsRef = React.useRef(new Set());
  const skipNextAutoFillRef = React.useRef(false);

  const getSortedKeys = (obj) => {
    if (!obj || typeof obj !== 'object') return [];

    const keys = Object.keys(obj).filter((key) => key !== 'order');

    // Check if any item has an order defined
    const hasAnyOrder = keys.some((key) => obj[key]?.order !== undefined);

    // If no order defined anywhere, preserve original order
    if (!hasAnyOrder) {
      return keys;
    }

    // Sort by order, preserving original position for items without order
    return keys
      .map((key, index) => ({ key, originalIndex: index }))
      .sort((a, b) => {
        const orderA = obj[a.key]?.order;
        const orderB = obj[b.key]?.order;

        // Both have order - sort by order
        if (orderA !== undefined && orderB !== undefined) {
          return orderA - orderB;
        }
        // Only A has order - A comes first
        if (orderA !== undefined) return -1;
        // Only B has order - B comes first
        if (orderB !== undefined) return 1;
        // Neither has order - preserve original position
        return a.originalIndex - b.originalIndex;
      })
      .map((item) => item.key);
  };
  React.useEffect(() => {
    if (isGDS && currentAppEnvironmentId) {
      orgEnvironmentConstantService.getConstantsFromEnvironment(currentAppEnvironmentId).then((data) => {
        const constants = {
          globals: {},
          secrets: {},
        };
        data.constants.forEach((constant) => {
          if (constant.type === Constants.Secret) {
            constants.secrets[constant.name] = constant.value;
          } else {
            constants.globals[constant.name] = constant.value;
          }
        });
        setCurrentOrgEnvironmentConstants(constants);
      });
    }

    return () => {
      setWorkspaceVariables([]);
      setCurrentOrgEnvironmentConstants([]);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentAppEnvironmentId]);

  // --- Validation ---
  const processAllOfConditions = React.useCallback((schema, options, path = []) => {
    let requiredFields = [];

    if (schema.allOf) {
      schema.allOf.forEach((condition) => {
        if (condition.if && condition.then) {
          const conditionMatches = Object.entries(condition.if.properties || {}).every(([propName, propCondition]) => {
            const propertyPath = [...path, propName];

            let currentValue = options;
            for (const segment of propertyPath) {
              if (!currentValue || typeof currentValue !== 'object') {
                return false;
              }
              currentValue = currentValue[segment]?.value;
            }

            return propCondition.const === currentValue;
          });

          if (conditionMatches) {
            if (condition.then.required) {
              requiredFields = [...requiredFields, ...condition.then.required];
            }

            if (condition.then.allOf) {
              const nestedRequired = processAllOfConditions({ allOf: condition.then.allOf }, options, path);
              requiredFields = [...requiredFields, ...nestedRequired];
            }

            if (condition.then.properties) {
              Object.entries(condition.then.properties).forEach(([propName, propSchema]) => {
                if (propSchema.allOf) {
                  const nestedRequired = processAllOfConditions({ allOf: propSchema.allOf }, options, [
                    ...path,
                    propName,
                  ]);
                  requiredFields = [...requiredFields, ...nestedRequired];
                }
              });
            }
          }
        }
      });
    }

    return requiredFields;
  }, []);

  const validateOptions = React.useCallback(async () => {
    try {
      const { valid, errors } = await dsm.validateData(options, selectedDataSource?.id, currentAppEnvironmentId);

      const conditionallyRequiredFields = processAllOfConditions(schema, options);
      setConditionallyRequiredProperties(conditionallyRequiredFields);

      let finalErrors = [...errors];

      // Strategy-specific validation
      if (autoFillStrategy) {
        const connectionType = options?.[autoFillStrategy.connectionTypeKey]?.value;

        finalErrors = autoFillStrategy.filterValidationErrors(finalErrors, options);

        if (
          connectionType === autoFillStrategy.activeConnectionTypeValue &&
          options[autoFillStrategy.connectionStringKey]?.value
        ) {
          const validation = autoFillStrategy.validate(options[autoFillStrategy.connectionStringKey].value, options);

          if (!validation.valid) {
            finalErrors.push({
              dataPath: `.${autoFillStrategy.connectionStringKey}`,
              keyword: 'custom',
              message: validation.error,
              params: {},
              schemaPath: `#/properties/${autoFillStrategy.connectionStringKey}`,
            });
          }
        }
      }

      if (finalErrors.length === 0) {
        clearValidationMessages();
        clearValidationErrorBanner();
      } else {
        // Auto-mark fields that have errors as interacted so that allOf/if/then
        // conditional required fields (e.g. username triggered by connection_type change)
        // are shown without requiring the user to directly touch them.
        // Compute the updated set locally so we can pass it to setValidationMessages
        // in the same render — avoids a second validation cycle caused by the dep change.
        const errorFields = finalErrors
          .map((e) =>
            e.keyword === 'required'
              ? e.params?.missingProperty
              : (e.instancePath || e.dataPath || '').replace(/^[./]/, '')
          )
          .filter(Boolean);
        const updatedInteractedFields = errorFields.some((f) => !interactedFields.has(f))
          ? new Set([...interactedFields, ...errorFields])
          : interactedFields;
        if (updatedInteractedFields !== interactedFields) {
          setInteractedFields(updatedInteractedFields);
        }
        setValidationMessages(finalErrors, schema, updatedInteractedFields);
      }
    } catch (error) {
      console.error('Validation error:', error);
    }
  }, [
    dsm,
    options,
    processAllOfConditions,
    schema,
    clearValidationMessages,
    clearValidationErrorBanner,
    setValidationMessages,
    interactedFields,
    autoFillStrategy,
  ]);

  React.useEffect(() => {
    if (!hasUserInteracted) return;

    const timeout = setTimeout(() => {
      validateOptions();
    }, 300);

    return () => clearTimeout(timeout);
  }, [options, hasUserInteracted, validateOptions]);

  React.useEffect(() => {
    if (showValidationErrors) {
      setHasUserInteracted(true);
      setInteractedFields(new Set(Object.keys(options)));
    }
  }, [showValidationErrors, options]);

  // --- Computed props for encrypted fields ---
  React.useEffect(() => {
    const prevDataSourceId = prevDataSourceIdRef.current;
    prevDataSourceIdRef.current = selectedDataSource?.id;
    const uiProperties = schema['tj:ui:properties'];
    if (!isEmpty(uiProperties)) {
      let fields = {};
      let encryptedFieldsProps = {};
      const flipComponentDropdown = find(uiProperties, ['widget', 'dropdown-component-flip']);

      if (flipComponentDropdown) {
        const selector = options?.[flipComponentDropdown?.key]?.value;
        const commonFieldsFromSslCertificate = uiProperties[selector]?.ssl_certificate?.commonFields;
        fields = {
          ...commonFieldsFromSslCertificate,
          ...flipComponentDropdown?.commonFields,
          ...uiProperties[selector],
        };
      } else {
        fields = { ...uiProperties };
      }

      const processFields = (fieldsObject) => {
        const processNestedField = (field, propertyKey) => {
          const { widget, encrypted } = field;

          const isEncryptedField =
            widget === 'password-v3' ||
            widget === 'password-v3-textarea' ||
            widget === 'password' ||
            encrypted ||
            encryptedProperties.includes(propertyKey);

          if (isEncryptedField) {
            if (computedProps[propertyKey] !== undefined && computedProps[propertyKey].disabled === false) {
              encryptedFieldsProps[propertyKey] = { disabled: false };
            } else if (!isDataSourceEditing) {
              encryptedFieldsProps[propertyKey] = { disabled: true };
            } else if (!(propertyKey in computedProps)) {
              encryptedFieldsProps[propertyKey] = {
                disabled: !!selectedDataSource?.id,
              };
            }
          }
        };

        Object.keys(fieldsObject).forEach((key) => {
          const field = fieldsObject[key];

          if (field.key) {
            processNestedField(field, field.key);
          }

          if (typeof field === 'object') {
            if (field.widget === 'dropdown-component-flip' || field.widget === 'toggle-flip') {
              const selectedOption = options?.[field.key]?.value;

              if (field.commonFields) {
                Object.keys(field.commonFields).forEach((commonKey) => {
                  const commonField = field.commonFields[commonKey];
                  processNestedField(commonField, commonField.key);
                });
              }

              if (selectedOption && fieldsObject[selectedOption]) {
                processFields(fieldsObject[selectedOption]);
              }
            }

            Object.keys(field).forEach((subKey) => {
              if (typeof field[subKey] === 'object' && field[subKey] !== null) {
                if (field[subKey].widget || field[subKey].key) {
                  processNestedField(field[subKey], field[subKey].key);
                } else {
                  processFields({ [subKey]: field[subKey] });
                }
              }
            });
          }
        });
      };

      processFields(fields);

      if (uiProperties.renderForm) {
        Object.keys(uiProperties.renderForm).forEach((sectionKey) => {
          const section = uiProperties.renderForm[sectionKey];
          const { inputs } = section;
          if (inputs) {
            processFields(inputs);
          }
        });
      }

      if (prevDataSourceId !== selectedDataSource?.id) {
        setComputedProps({ ...encryptedFieldsProps });
      } else {
        setComputedProps({ ...computedProps, ...encryptedFieldsProps });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDataSource?.id, options, isDataSourceEditing]);

  React.useEffect(() => {
    const requiredFields = processAllOfConditions(schema, options);
    setConditionallyRequiredProperties(requiredFields);
  }, [options, processAllOfConditions, schema, selectedDataSource.id]);

  const getElement = (type) => {
    switch (type) {
      case 'password':
      case 'text':
        return Input;
      case 'password-v3':
      case 'text-v3':
      case 'password-v3-textarea':
        return InputV3;
      case 'textarea':
        return Textarea;
      case 'toggle':
        return Toggle;
      case 'toggle-v2':
        return ToggleV2;
      case 'toggle-flip':
        return ToggleV2;
      case 'checkbox':
        return Checkbox;
      case 'checkbox-group':
        return CheckboxGroup;
      case 'react-component-headers':
        return Headers;
      case 'react-component-sql-filters':
        return SqlFilters;
      case 'react-component-sql-columns':
        return SqlColumns;
      case 'react-component-sql-sort':
        return SqlSort;
      case 'react-component-sql-groupby':
        return SqlGroupBy;
      case 'react-component-sql-aggregate':
        return SqlAggregate;
      case 'dropdown':
        return Select;
      case 'react-component-oracle-wallet':
        return OracleWalletPicker;
      case 'react-component-oauth':
        return OAuthWrapper;
      // TODO: Move dropdown component flip logic to be handled here
      // case 'dropdown-component-flip':
      //   return Select;
      default:
        return null;
    }
  };

  const getElementProps = (uiProperties) => {
    const {
      label,
      description,
      widget,
      required,
      width,
      key,
      help_text: helpText,
      list,
      buttonText,
      oauth_configs,
    } = uiProperties;

    const isRequired = required || conditionallyRequiredProperties.includes(key);
    const isEncrypted =
      widget === 'password-v3' ||
      widget === 'password-v3-textarea' ||
      widget === 'password' ||
      encryptedProperties.includes(key);
    const currentValue = options?.[key]?.value;
    const skipValidation =
      (!hasUserInteracted && !showValidationErrors) || (!interactedFields.has(key) && !showValidationErrors);

    // On locked master branch, disable non-encrypted fields (encrypted fields remain editable)
    const isFieldDisabledByBranchLock = isWorkspaceBranchLocked && !isEncrypted;
    const workspaceConstant = options?.[key]?.workspace_constant;
    const isEditing = computedProps[key] && computedProps[key].disabled === false;
    const showEncryptedLockedHelpText = isWorkspaceBranchLocked && isEncrypted;
    const finalHelpText = showEncryptedLockedHelpText
      ? 'Encrypted values are not pushed to git and are updated directly in Tooljet'
      : helpText;

    const handleOptionChange = (key, value, flag = true) => {
      if (!hasUserInteracted) {
        setHasUserInteracted(true);
      }
      setInteractedFields((prev) => new Set(prev).add(key));
      // Delegate manual edit tracking to the autofill hook
      if (autoFillStrategy) {
        handleManualFieldEdit(key, value);

        if (autoFillStrategy.autoFillableFields.includes(key)) {
          optionchanged(key, value, flag);
          return;
        }
      }

      optionchanged(key, value, flag);
    };

    switch (widget) {
      case 'password':
      case 'text':
      case 'textarea': {
        return {
          propertyKey: key,
          widget,
          label,
          placeholder: workspaceConstant ? workspaceConstant : isEncrypted ? '**************' : description,
          className: cx('form-control', {
            'dynamic-form-encrypted-field': isEncrypted,
          }),
          style: { marginBottom: '0px !important' },
          helpText: finalHelpText,
          value: currentValue || '',
          onChange: (e) => handleOptionChange(key, e.target.value, true),
          isGDS: true,
          encrypted: isEncrypted,
          onBlur,
          workspaceVariables,
          workspaceConstants: currentOrgEnvironmentConstants,
          disabled: isFieldDisabledByBranchLock,
          isDisabled: isFieldDisabledByBranchLock,
        };
      }
      case 'password-v3':
      case 'password-v3-textarea':
      case 'text-v3': {
        let customValidation = { valid: null, message: '' };

        if (autoFillStrategy && key === autoFillStrategy.connectionStringKey && currentValue && !skipValidation) {
          const validation = autoFillStrategy.validate(currentValue, options);
          if (!validation.valid) {
            customValidation = { valid: false, message: validation.error };
          } else {
            customValidation = { valid: true, message: '' };
          }
        }

        const validationStatus =
          autoFillStrategy && key === autoFillStrategy.connectionStringKey && customValidation.valid !== null
            ? customValidation
            : skipValidation
              ? { valid: null, message: '' }
              : validationMessages[key]
                ? { valid: false, message: validationMessages[key] }
                : isRequired
                  ? { valid: true, message: '' }
                  : { valid: null, message: '' };

        return {
          propertyKey: key,
          widget,
          label,
          placeholder: workspaceConstant ? workspaceConstant : isEncrypted ? '**************' : description,
          className: cx('form-control', {
            'dynamic-form-encrypted-field': isEncrypted,
          }),
          style: { marginBottom: '0px !important' },
          helpText: finalHelpText,
          value: currentValue || '',
          onChange: (e) => handleOptionChange(key, e.target.value, true),
          isGDS: true,
          encrypted: isEncrypted,
          onBlur,
          isRequired: isRequired,
          isValidatedMessages: validationStatus,
          disabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          isDisabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          workspaceVariables,
          workspaceConstants: currentOrgEnvironmentConstants,
          isEditing: isEditing,
          labelDisabled: false,
        };
      }
      case 'react-component-oauth':
        return {
          optionchanged,
          createDataSource,
          options,
          isSaving,
          selectedDataSource,
          currentAppEnvironmentId,
          workspaceConstants: currentOrgEnvironmentConstants,
          isDisabled: !canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource(),
          optionsChanged,
          multiple_auth_enabled: options?.multiple_auth_enabled?.value,
          scopes: options?.scopes?.value,
          oauth_configs,
        };
      case 'react-component-headers': {
        let isRenderedAsQueryEditor;
        if (isGDS) {
          isRenderedAsQueryEditor = false;
        } else {
          isRenderedAsQueryEditor = !isGDS;
        }
        return {
          getter: key,
          options: isRenderedAsQueryEditor
            ? (options?.[key] ?? schema?.defaults?.[key])
            : (options?.[key]?.value ?? schema?.defaults?.[key]?.value),
          handleOptionChange,
          isRenderedAsQueryEditor,
          workspaceConstants: currentOrgEnvironmentConstants,
          isDisabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          encrypted: isEncrypted,
          buttonText,
          width: width,
          ...elementsProps?.[key],
        };
      }
      case 'react-component-sql-filters': {
        return {
          getter: key,
          parseKey: uiProperties.parse_key,
          options: options,
          handleOptionChange,
          workspaceConstants: currentOrgEnvironmentConstants,
        };
      }
      case 'react-component-sql-columns':
      case 'react-component-sql-sort':
      case 'react-component-sql-groupby':
      case 'react-component-sql-aggregate': {
        return {
          getter: key,
          parseKey: uiProperties.parse_key,
          options: options,
          handleOptionChange,
          workspaceConstants: currentOrgEnvironmentConstants,
          darkMode: localStorage.getItem('darkMode') === 'true',
        };
      }
      case 'toggle':
        return {
          defaultChecked: currentValue,
          checked: currentValue,
          onChange: (e) => handleOptionChange(key, e.target.checked, true),
          disabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
        };
      case 'toggle-flip':
        // eslint-disable-next-line no-case-declarations
        const isEnabled = currentValue === 'enabled' || currentValue === true;
        return {
          checked: isEnabled,
          label: label,
          helpText: helpText,
          disabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          onChange: (e) => {
            // Determine boolean-mode from the schema's declared type rather than the current
            // value, since an old datasource that never stored this field has value === undefined
            // (neither true nor false), which would otherwise wrongly fall back to string mode.
            const booleanMode = schema?.properties?.[key]?.type === 'boolean';
            handleOptionChange(
              key,
              e.target.checked ? (booleanMode ? true : 'enabled') : booleanMode ? false : 'disabled',
              true
            );
          },
        };
      case 'toggle-v2':
        return {
          checked: currentValue,
          label: label,
          helpText: helpText,
          disabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          onChange: (e) => handleOptionChange(key, e.target.checked, true),
        };
      case 'dropdown':
      case 'dropdown-component-flip':
        return {
          options: list,
          value: options?.[key]?.value || options?.[key],
          onChange: (value) => handleOptionChange(key, value, true),
          width: width || '100%',
          encrypted: options?.[key]?.encrypted,
          isDisabled: isFieldDisabledByBranchLock,
        };
      case 'checkbox':
        return {
          propertyKey: key,
          widget,
          label,
          isChecked: currentValue || false,
          onChange: (e) => handleOptionChange(key, e.target.checked, true),
          helpText: helpText,
          isRequired: isRequired,
          disabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
          isDisabled:
            isFieldDisabledByBranchLock || (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()),
        };
      case 'checkbox-group':
        return {
          options: list,
          values: options?.[key] ?? [],
          onChange: (value) => {
            optionchanged(key, [...value]);
          },
        };
      case 'react-component-oracle-wallet':
        return {
          value: options?.[key]?.value ?? '',
          onChange: (val) => handleOptionChange(key, val),
          disabled: !canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource(),
        };
      default:
        return {};
    }
  };

  const getLayout = (uiProperties) => {
    if (isEmpty(uiProperties)) return null;
    const flipComponentDropdown = isFlipComponentDropdown(uiProperties);

    if (flipComponentDropdown) {
      return flipComponentDropdown;
    }

    const handleEncryptedFieldsToggle = (event, field) => {
      if (!canUpdateDataSource(selectedDataSource?.id) && !canDeleteDataSource()) {
        return;
      }

      const isEditing = computedProps[field]['disabled'];
      const workspaceConstant = options?.[field]?.workspace_constant;
      const isWorkspaceConstant = !!workspaceConstant;

      if (isEditing) {
        if (isWorkspaceConstant) {
          optionchanged(field, workspaceConstant);
        } else {
          optionchanged(field, '');
        }
      } else {
        const newOptions = { ...options };
        const oldFieldValue = selectedDataSource?.['options']?.[field];
        if (oldFieldValue) {
          optionsChanged({ ...newOptions, [field]: oldFieldValue });
        } else {
          delete newOptions[field];
          optionsChanged({ ...newOptions });
        }
      }

      setComputedProps({
        ...computedProps,
        [field]: {
          ...computedProps[field],
          disabled: !isEditing,
        },
      });
    };

    const renderLabel = (label, tooltip, fieldType) => {
      const labelElement = (
        <label
          className="form-label"
          data-cy={
            fieldType === 'dropdown'
              ? `${generateCypressDataCy(label)}-dropdown-label`
              : `${generateCypressDataCy(label)}-label`
          }
          style={{ textDecoration: tooltip ? 'underline 2px dashed' : 'none', textDecorationColor: 'var(--slate8)' }}
        >
          {label}
        </label>
      );

      if (tooltip) {
        return (
          <OverlayTrigger
            placement="top"
            trigger="click"
            rootClose
            overlay={<Tooltip id={`tooltip-${label}`}>{tooltip}</Tooltip>}
          >
            {labelElement}
          </OverlayTrigger>
        );
      }

      return labelElement;
    };

    return (
      <div className={`${isHorizontalLayout ? '' : 'row'}`}>
        {getSortedKeys(uiProperties).map((key) => {
          const { label, widget, encrypted, className, key: propertyKey } = uiProperties[key];
          const Element = getElement(widget);

          // Skip rendering if Element is null (invalid widget type)
          if (!Element) {
            return null;
          }

          const isSpecificComponent = ['tooljetdb-operations', 'react-component-api-endpoint'].includes(widget);

          return (
            <div
              className={cx('my-2', {
                'col-md-12': !className && !isHorizontalLayout,
                [className]: !!className,
                'd-flex': isHorizontalLayout,
                'dynamic-form-row': isHorizontalLayout,
              })}
              data-cy={`${generateCypressDataCy(label ?? key)}-section`}
              key={key}
            >
              {!isSpecificComponent && (
                <div
                  className={cx('d-flex', {
                    'form-label': isHorizontalLayout,
                    'align-items-center': !isHorizontalLayout,
                  })}
                  style={{ minWidth: '100px' }}
                >
                  {label &&
                    widget !== 'text-v3' &&
                    widget !== 'password-v3' &&
                    widget !== 'password-v3-textarea' &&
                    widget !== 'checkbox' &&
                    widget !== 'checkbox-group' &&
                    widget !== 'toggle-v2' &&
                    renderLabel(label, uiProperties[key].tooltip, widget)}
                </div>
              )}
              <div
                className={cx(
                  {
                    'flex-grow-1': isHorizontalLayout && !isSpecificComponent,
                    'w-100': isHorizontalLayout && widget !== 'codehinter',
                  },
                  'dynamic-form-element'
                )}
                style={{ width: '100%' }}
                data-cy={
                  widget === 'dropdown' || widget === 'dropdown-component-flip'
                    ? `${generateCypressDataCy(label ?? key)}-select-dropdown`
                    : `${generateCypressDataCy(label ?? key)}-${generateCypressDataCy(widget ?? key)}-element`
                }
              >
                <Element
                  {...getElementProps(uiProperties[key])}
                  {...computedProps[propertyKey]}
                  data-cy={`${generateCypressDataCy(label)}-text-field`}
                  dataCy={generateCypressDataCy(uiProperties[key].label ?? key)}
                  //to be removed after whole ui is same
                  isHorizontalLayout={isHorizontalLayout}
                  handleEncryptedFieldsToggle={handleEncryptedFieldsToggle}
                />
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const FlipComponentDropdown = (uiProperties) => {
    const flipComponentDropdowns = Object.values(uiProperties || {})
      .filter((c) => c.widget === 'dropdown-component-flip' || c.widget === 'toggle-flip')
      .sort((a, b) => {
        const orderA = a?.order ?? Number.MAX_SAFE_INTEGER;
        const orderB = b?.order ?? Number.MAX_SAFE_INTEGER;
        return orderA - orderB;
      });

    // Build all components with their order for sorting
    const allComponents = [];
    let insertIndex = 0;

    // Add dropdown components with their order
    flipComponentDropdowns.forEach((flipComponentDropdown) => {
      const selector = options?.[flipComponentDropdown?.key]?.value || options?.[flipComponentDropdown?.key];
      const scopedChildren = flipComponentDropdown[selector];
      const parentChildren = uiProperties[selector];
      const childrenToRender = scopedChildren !== undefined ? scopedChildren : parentChildren;

      allComponents.push({
        order: flipComponentDropdown.order, // Keep undefined if not set
        insertIndex: insertIndex++,
        key: `dropdown-${flipComponentDropdown.key}`,
        element: (
          <div key={flipComponentDropdown.key}>
            <div className={isHorizontalLayout ? '' : 'row'}>
              {flipComponentDropdown.commonFields && getLayout(flipComponentDropdown.commonFields)}

              <div
                className={cx('my-2', {
                  'col-md-12': !flipComponentDropdown.className && !isHorizontalLayout,
                  'd-flex': isHorizontalLayout,
                  'dynamic-form-row': isHorizontalLayout,
                  [flipComponentDropdown.className]: !!flipComponentDropdown.className,
                })}
                data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-section`}
              >
                {flipComponentDropdown.widget !== 'toggle-flip' &&
                  (flipComponentDropdown.label || isHorizontalLayout) && (
                    <label
                      className={cx('form-label')}
                      data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-dropdown-label`}
                    >
                      {flipComponentDropdown.label}
                    </label>
                  )}

                <div
                  data-cy={`${generateCypressDataCy(flipComponentDropdown.label)}-select-dropdown`}
                  className={cx({ 'flex-grow-1': isHorizontalLayout })}
                >
                  {flipComponentDropdown.widget === 'toggle-flip' ? (
                    <ToggleV2
                      {...getElementProps(flipComponentDropdown)}
                      dataCy={generateCypressDataCy(flipComponentDropdown.label)}
                    />
                  ) : (
                    <Select
                      {...getElementProps(flipComponentDropdown)}
                      styles={{}}
                      useCustomStyles={false}
                      isSearchable={false}
                      dataCy={generateCypressDataCy(flipComponentDropdown.label)}
                    />
                  )}
                </div>
                {flipComponentDropdown.helpText && (
                  <span className="flip-dropdown-help-text">{flipComponentDropdown.helpText}</span>
                )}
              </div>
            </div>

            {getLayout(childrenToRender)}
          </div>
        ),
      });
    });

    // Add normal components with their order
    Object.keys(uiProperties).forEach((key) => {
      const component = uiProperties[key];
      const componentType = component.widget || component.type;

      if (componentType && componentType !== 'dropdown-component-flip' && componentType !== 'toggle-flip') {
        allComponents.push({
          order: component.order, // Keep undefined if not set
          insertIndex: insertIndex++,
          key: `normal-${key}`,
          element: <div key={key}>{getLayout({ [key]: component })}</div>,
        });
      }
    });

    // Check if any component has order defined
    const hasAnyOrder = allComponents.some((item) => item.order !== undefined);

    // Only sort if at least one component has order
    if (hasAnyOrder) {
      allComponents.sort((a, b) => {
        // Both have order - sort by order
        if (a.order !== undefined && b.order !== undefined) {
          return a.order - b.order;
        }
        // Only A has order - A comes first
        if (a.order !== undefined) return -1;
        // Only B has order - B comes first
        if (b.order !== undefined) return 1;
        // Neither has order - preserve insertion order
        return a.insertIndex - b.insertIndex;
      });
    }

    return <>{allComponents.map((item) => item.element)}</>;
  };

  const isFlipComponentDropdown = (uiProperties) => {
    const checkFlipComponents = uiProperties
      ? Object.values(uiProperties).filter((c) => c.widget === 'dropdown-component-flip' || c.widget === 'toggle-flip')
      : [];
    if (checkFlipComponents.length > 0) {
      return FlipComponentDropdown(uiProperties);
    } else {
      return null;
    }
  };

  const flipComponentDropdown = isFlipComponentDropdown(uiProperties);
  if (flipComponentDropdown) return flipComponentDropdown;
  return getLayout(uiProperties);
};

export default DynamicFormV2;
import React, { useState } from 'react';
import { ButtonSolid } from './AppButton';

export default function EncryptedFieldWrapper({
  children,
  options,
  selectedDataSource,
  optionchanged,
  optionsChanged,
  name,
  label,
  encrypted = true,
}) {
  const [disabled, setDisabled] = useState(true);

  const handleEncryptedFieldsToggle = (field) => {
    const isEditing = disabled;
    if (isEditing) {
      optionchanged(field, '');
    } else {
      //Send old field value if editing mode disabled for encrypted fields
      const newOptions = { ...options };
      const oldFieldValue = selectedDataSource?.['options']?.[field];
      optionsChanged({ ...newOptions, [field]: oldFieldValue });
    }
    setDisabled(!isEditing);
  };

  return (
    <>
      <div className="d-flex align-items-center mt-3">
        <label className="form-label" data-cy={`label-${String(label).toLowerCase().replace(/\s+/g, '-')}`}>
          {label}
        </label>
        <div className="mx-1 col">
          <ButtonSolid
            className="datasource-edit-btn mb-2"
            type="a"
            variant="tertiary"
            target="_blank"
            rel="noreferrer"
            onClick={() => handleEncryptedFieldsToggle(name)}
            data-cy={`button-${(disabled ? 'Edit' : 'Cancel').toLowerCase().replace(/\s+/g, '-')}`}
          >
            {disabled ? 'Edit' : 'Cancel'}
          </ButtonSolid>
        </div>
        <div className="col-auto mb-2">
          <small className="text-green mx-2" data-cy="encrypted-text">
            <img className="mx-2 encrypted-icon" src="assets/images/icons/padlock.svg" width="12" height="12" />
