import React from 'react';
import { TriangleAlert, CircleAlert, CircleCheckBig, SquareArrowOutUpRight, X } from 'lucide-react';
import { detailAction } from './detailAction';

// per Figma: error=triangle-alert, info=circle-alert, success=circle-check-big (14px)
const ICON_BY_TYPE = {
  info: { Icon: CircleAlert, color: '#4368E3' },
  success: { Icon: CircleCheckBig, color: '#1E823B' },
  warning: { Icon: TriangleAlert, color: '#E68A1E' },
  error: { Icon: TriangleAlert, color: '#D72D39' },
};

// design copy uses short relative time: "2m ago"
export function timeAgo(iso) {
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (Number.isNaN(s) || s < 60) return 'just now';
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

// branch names render in monospace within the body (design: IBM Plex Mono segments)
function MonoBody({ body, branchName }) {
  if (!branchName || !body?.includes(branchName)) return body ?? null;
  return body.split(branchName).map((segment, i) => (
    <React.Fragment key={i}>
      {i > 0 && <code className="notification-row-mono">{branchName}</code>}
      {segment}
    </React.Fragment>
  ));
}

export default function NotificationRow({ notification, onRemove, onMarkRead, onOpen, darkMode }) {
  const { type, title, body, createdAt, readAt, metadata } = notification;
  const { Icon, color } = ICON_BY_TYPE[type] || ICON_BY_TYPE.info;
  const hasDetail = !!detailAction(notification);

  const handleRowClick = () => {
    if (hasDetail) onOpen(notification);
    else if (!readAt) onMarkRead(notification.recipientId);
  };

  return (
    <div
      className={`notification-row ${readAt ? 'read' : 'unread'} ${darkMode ? 'dark' : ''}`}
      onClick={handleRowClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') handleRowClick();
      }}
    >
      <span className="notification-row-icon">
        <Icon size={14} style={{ color, flexShrink: 0 }} />
      </span>
      <div className="notification-row-content">
        <div className="notification-row-title">{title}</div>
        {body && (
          <div className="notification-row-body">
            <MonoBody body={body} branchName={metadata?.branchName} />
          </div>
        )}
        <div className="notification-row-time">{timeAgo(createdAt)}</div>
      </div>
      <div className="notification-row-side">
        {!readAt && <span className="notification-row-dot" aria-label="Unread" />}
        <div className="notification-row-actions">
          {hasDetail && (
            <button
              className="notification-row-action"
              onClick={(e) => {
                e.stopPropagation();
                onOpen(notification);
              }}
              aria-label="Open"
            >
              <SquareArrowOutUpRight size={14} />
            </button>
          )}
          <button
            className="notification-row-action"
            onClick={(e) => {
              e.stopPropagation();
              onRemove(notification.recipientId);
            }}
            aria-label="Remove"
          >
            <X size={14} />
          </button>
        </div>
      </div>
    </div>
  );
}
import React from 'react';
import toast from 'react-hot-toast';

const TOAST_MS = 5000;

// Arrival toast for live notifications flagged toast:true — never from REST backfill.
// Rides the app's standard react-hot-toast look; optional "View details" opens the detail.
export function showNotificationToast(notification, { onViewDetails } = {}) {
  // design 70:6926: message + bordered secondary button on one row
  const message = (t) => (
    <span className="notification-toast-row">
      <span className="notification-toast-body">{notification.body || notification.title}</span>
      {onViewDetails && (
        <button
          className="notification-toast-view"
          onClick={() => {
            toast.dismiss(t.id);
            onViewDetails(notification);
          }}
        >
          View details
        </button>
      )}
    </span>
  );

  // react-hot-toast caps toasts at 350px — too narrow for message + action on one line (design 70:6926)
  const opts = { duration: TOAST_MS, style: { maxWidth: '640px' } };
  if (notification.type === 'success') return toast.success(message, opts);
  if (notification.type === 'error') return toast.error(message, opts);
  return toast(message, opts);
}
// One rule for row click AND toast "View details" — capability derived from payload
// presence so it can never desync from the data:
//   metadata.error present -> detail modal (renderable trace/body)
//   link present           -> navigate
//   neither                -> no detail affordance
// 'git-sync-modal' is a sentinel, not a URL (P2 deep-link) — not navigable yet.
export function detailAction(notification) {
  if (notification?.metadata?.error) return { kind: 'modal' };
  if (notification?.link && notification.link !== 'git-sync-modal') return { kind: 'link', href: notification.link };
  return null;
}
import React from 'react';
import { toast } from 'react-hot-toast';
import Spinner from '@/_ui/Spinner';
import { useTranslation } from 'react-i18next';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import { IconBellCheck } from '@tabler/icons-react';
import { BrushCleaning } from 'lucide-react';
import { ToolTip } from '@/_components/ToolTip';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import { useNotificationsStore, useNotificationsActions } from '@/_stores/notificationsStore';
import NotificationRow from './NotificationRow';
import ErrorDetailModal from './ErrorDetailModal';

export const NotificationCenter = ({ darkMode }) => {
  const { items, unreadCount, isLoading, hasMore, loadingMore, detailNotification } = useNotificationsStore((s) => ({
    items: s.items,
    unreadCount: s.unreadCount,
    isLoading: s.isLoading,
    hasMore: s.hasMore,
    loadingMore: s.loadingMore,
    detailNotification: s.detailNotification,
  }));
  const actions = useNotificationsActions();

  const { t } = useTranslation();

  // Refresh badge count on mount + open the live socket (pushes deltas, backfills on reconnect)
  React.useEffect(() => {
    actions.refreshUnread();
    actions.connect();
    return () => actions.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleOpen = () => {
    actions.fetch('all');
  };

  const handleMarkAllRead = async () => {
    const { error } = await actions.markAllRead();
    if (error) toast.error('Unable to update notifications');
  };

  const handleClearRead = async () => {
    const { error } = await actions.clearRead();
    if (error) toast.error('Unable to clear notifications');
  };

  const handleRemove = async (recipientId) => {
    const { error } = await actions.remove(recipientId);
    if (error) toast.error('Unable to remove notification');
  };

  const hasRead = items.some((n) => n.readAt);

  const overlay = (
    <div
      className={`notification-center dropdown-menu dropdown-menu-arrow dropdown-menu-end dropdown-menu-card ${
        darkMode && 'dark-theme'
      }`}
      data-bs-popper="static"
    >
      <div className="card notifications-card" data-cy="notifications-card">
        <div className="card-header">
          <h1 className="card-title" data-cy="notifications-card-title">
            {t('header.notificationCenter.notifications', 'Notifications')}
          </h1>
          {unreadCount > 0 && <span className="notification-new-pill">{unreadCount} new</span>}
          <div className="notification-header-actions ms-auto">
            <ToolTip message={t('notifications.markAllRead', 'Mark all as read')} placement="bottom">
              <button
                className="notification-header-action"
                onClick={handleMarkAllRead}
                disabled={unreadCount === 0}
                aria-label="Mark all as read"
                data-cy="mark-all-read-button"
              >
                <IconBellCheck size={16} />
              </button>
            </ToolTip>
            <ToolTip message={t('notifications.clearRead', 'Clear read notifications')} placement="bottom">
              <button
                className="notification-header-action"
                onClick={handleClearRead}
                disabled={!hasRead}
                aria-label="Clear read notifications"
                data-cy="clear-read-button"
              >
                <BrushCleaning size={16} />
              </button>
            </ToolTip>
          </div>
        </div>
        <div className="list-group list-group-flush list-group-hoverable p-2">
          {!isLoading &&
            items.map((n) => (
              <NotificationRow
                key={n.recipientId}
                notification={n}
                darkMode={darkMode}
                onRemove={handleRemove}
                onMarkRead={actions.markRead}
                onOpen={actions.openDetail}
              />
            ))}
          {!isLoading && items.length === 0 && (
            <div className="empty">
              <div className="empty-img" data-cy="empty-notification-icon">
                {/* design 85:9355 uses lucide/bell-check; lucide-react has no BellCheck yet */}
                <IconBellCheck size={20} color="#ACB2B9" />
              </div>
              <p className="empty-title" data-cy="empty-notification-title">
                {t('notifications.allCaughtUp', "You're all caught up!")}
              </p>
              <p className="empty-subtitle text-muted" data-cy="empty-notification-subtitle">
                {t('notifications.emptyHint', 'Status of background operations will appear here')}
              </p>
            </div>
          )}
          {isLoading && (
            <div className="m-auto spinner">
              <Spinner />
            </div>
          )}
        </div>
        {/* design 70:8193: pinned footer bar below the scroll area — centered label, top border */}
        {!isLoading && hasMore && (
          <button
            className="notification-load-more"
            onClick={actions.loadMore}
            disabled={loadingMore}
            data-cy="load-more-notifications"
          >
            {loadingMore ? t('notifications.loading', 'Loading…') : t('notifications.loadMore', 'Load more')}
          </button>
        )}
      </div>
    </div>
  );

  return (
    <>
      <OverlayTrigger onEntering={handleOpen} rootClose trigger="click" placement="right-end" overlay={overlay}>
        <div>
          <ToolTip message="Notifications" placement="right">
            <div className="notification-center-nav-item cursor-pointer tj-leftsidebar-icon-items">
              <SolidIcon data-cy="notifications-icon" name="notification" fill="var(--slate8)" />
              {unreadCount > 0 && (
                <span className="notification-center-badge badge">{unreadCount > 99 ? '99+' : unreadCount}</span>
              )}
            </div>
          </ToolTip>
        </div>
      </OverlayTrigger>
      <ErrorDetailModal notification={detailNotification} show={!!detailNotification} onClose={actions.closeDetail} />
    </>
  );
};
import OAuth from '@/_ui/OAuth';
import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { getHostURL } from '@/_helpers/routes';
import { datasourceService, authenticationService } from '@/_services';
import { capitalize } from 'lodash';
import { toast } from 'react-hot-toast';
import Button from '@/_ui/Button';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import Input from '@/_ui/Input';
import cx from 'classnames';
import { Modal } from 'react-bootstrap';
import SolidIcon from '@/_ui/Icon/SolidIcons';

const OAuthWrapper = ({
  optionchanged,
  createDataSource,
  options,
  isSaving,
  selectedDataSource,
  workspaceConstants,
  optionsChanged,
  isDisabled,
  isWorkspaceBranchLocked = false,
  multiple_auth_enabled,
  scopes,
  oauth_configs,
  currentAppEnvironmentId,
}) => {
  // Inner OAuth fields stay locked when the workspace branch is locked (default
  // branch + branching enabled). The save button uses `isDisabled` alone so an
  // edit to an encrypted field on the default branch can still be saved.
  const isFieldsDisabled = isDisabled || isWorkspaceBranchLocked;
  const [authStatus, setAuthStatus] = useState(null);
  const { t } = useTranslation();
  const [initialOptions, setInitialOptions] = useState(null);
  const [initialName, setInitialName] = useState(null);
  useEffect(() => {
    if (selectedDataSource?.id && !initialOptions) {
      setInitialOptions(options);
      setInitialName(selectedDataSource.name);
    }
  }, [selectedDataSource?.id, options, initialOptions]);

  const hasFieldsChanged = () => {
    if (!selectedDataSource?.id || !initialOptions) {
      return true;
    }

    if (selectedDataSource?.name !== initialName) {
      return true;
    }

    const optionKeys = Object.keys(options || {});
    for (const key of optionKeys) {
      const currentValue = options[key]?.value;
      const initialValue = initialOptions[key]?.value;
      if (currentValue !== initialValue) {
        return true;
      }
    }
    return false;
  };
  const isAuthorizationCodeGrant = ['authorization_code', 'authorization_code_pkce'].includes(
    options?.grant_type?.value
  );
  const needConnectionButton =
    selectedDataSource.kind !== 'openapi' && options?.auth_type?.value === 'oauth2' && isAuthorizationCodeGrant;
  const dataSourceNameCapitalize = capitalize(
    selectedDataSource?.plugin?.manifestFile?.data?.source?.name || selectedDataSource?.kind
  );
  const redirectUri = `${getHostURL()}/oauth2/authorize`;

  const docLink =
    selectedDataSource?.pluginId && selectedDataSource.pluginId.trim() !== ''
      ? `https://docs.tooljet.com/docs/marketplace/plugins/marketplace-plugin-${selectedDataSource?.kind}/`
      : `https://docs.tooljet.com/docs/data-sources/${selectedDataSource?.kind}`;

  function authorizeWithProvider() {
    const provider = selectedDataSource?.kind;
    const plugin_id = selectedDataSource?.plugin?.id;
    const source_options = options;
    const organizationId = authenticationService.currentSessionValue?.current_organization_id;
    setAuthStatus('waiting_for_url');

    // Pass envId, orgId to resolve workspace constants on the backend
    const fetchArgs = plugin_id
      ? [provider, plugin_id, source_options, currentAppEnvironmentId, organizationId]
      : [provider, null, source_options, currentAppEnvironmentId, organizationId];

    datasourceService
      .fetchOauth2BaseUrl(...fetchArgs)
      .then((data) => {
        localStorage.setItem('sourceWaitingForOAuth', 'newSource');
        localStorage.setItem('currentAppEnvironmentIdForOauth', currentAppEnvironmentId);
        optionchanged('provider', provider).then(() => {
          optionchanged('oauth2', true);
          if (plugin_id) {
            optionchanged('plugin_id', plugin_id);
          }
        });
        setAuthStatus('waiting_for_token');
        window.open(data.url);
      })
      .catch(({ error }) => {
        toast.error(error);
        setAuthStatus(null);
      });
  }

  function saveDataSource() {
    optionchanged('code', localStorage.getItem('OAuthCode')).then(() => {
      createDataSource();
    });
  }

  return (
    <div>
      <div>
        <OAuth
          isGrpc={false}
          grant_type={options?.grant_type?.value}
          auth_type={options?.auth_type?.value}
          add_token_to={options?.add_token_to?.value}
          header_prefix={options?.header_prefix?.value}
          access_token_url={options?.access_token_url?.value}
          access_token_custom_headers={options?.access_token_custom_headers?.value}
          client_id={options?.client_id?.value}
          client_secret={options?.client_secret?.value}
          client_auth={options?.client_auth?.value}
          company_id={options?.company_id?.value}
          site_url={options?.site_url?.value}
          code_verifier={options?.code_verifier?.value}
          code_challenge_method={options?.code_challenge_method?.value}
          scopes={options?.scopes?.value}
          username={options?.username?.value}
          password={options?.password?.value}
          grpc_apiKey_key={options?.grpc_apikey_key?.value}
          grpc_apiKey_value={options?.grpc_apikey_value?.value}
          bearer_token={options?.bearer_token?.value}
          auth_url={options?.auth_url?.value}
          auth_key={options?.auth_key?.value}
          audience={options?.audience?.value}
          custom_auth_params={options?.custom_auth_params?.value}
          custom_query_params={options?.custom_query_params?.value}
          multiple_auth_enabled={options?.multiple_auth_enabled?.value}
          optionchanged={optionchanged}
          workspaceConstants={workspaceConstants}
          isDisabled={isFieldsDisabled}
          options={options}
          optionsChanged={optionsChanged}
          selectedDataSource={selectedDataSource}
          oauth_configs={oauth_configs}
        />
      </div>
      {oauth_configs?.allowed_scope_field && (
        <div>
          <label className="form-label mt-3">Scope(s)</label>
          <Input
            type="text"
            className="form-control"
            onChange={(e) => optionchanged('scopes', e.target.value)}
            value={scopes}
            workspaceConstants={workspaceConstants}
          />
          {oauth_configs?.scopeHelperText?.length > 0 && (
            <span className="text-muted" style={{ fontSize: '12px' }}>
              {oauth_configs.scopeHelperText}
            </span>
          )}
        </div>
      )}
      <div>
        <label className="form-label mt-3">Redirect URI</label>
        <Input
          value={redirectUri}
          helpText="Save this URL as callback or redirect URL in your OAuth app."
          type="copyToClipboard"
          disabled={true}
          className="form-control"
        />
      </div>
      {options?.auth_type?.value === 'oauth2' && isAuthorizationCodeGrant && (
        <div>
          <label className="form-check form-switch mt-3">
            <input
              className="form-check-input"
              type="checkbox"
              checked={multiple_auth_enabled}
              onChange={() => optionchanged('multiple_auth_enabled', !multiple_auth_enabled)}
              disabled={isFieldsDisabled}
            />
            <div>
              <span className="form-check-label">Authentication required for all users</span>
              <span className="text-muted" style={{ fontSize: '12px' }}>
                Other users will be redirected to OAuth flow once first query of this data source is run in an app.
              </span>
            </div>
          </label>
        </div>
      )}
      {oauth_configs?.allowed_dynamic_params_field && (
        <div>
          <label className="form-check form-switch mt-3">
            <input
              className="form-check-input"
              type="checkbox"
              checked={options?.[oauth_configs.allowed_dynamic_params_field.key]?.value || false}
              onChange={() =>
                optionchanged(
                  oauth_configs.allowed_dynamic_params_field.key,
                  !options?.[oauth_configs.allowed_dynamic_params_field.key]?.value
                )
              }
            />
            <div>
              <span className="form-check-label">{oauth_configs.allowed_dynamic_params_field.label}</span>
              {oauth_configs.allowed_dynamic_params_field.help_text && (
                <span className="text-muted" style={{ fontSize: '12px' }}>
                  {oauth_configs.allowed_dynamic_params_field.help_text}
                </span>
              )}
            </div>
          </label>
        </div>
      )}
      {needConnectionButton && (
        <Modal.Footer
          style={{
            marginTop: '32px',
            borderTop: '1px solid var(--border-weak)',
            marginLeft: '-24px',
            marginRight: '-24px',
            paddingLeft: '24px',
            paddingRight: '24px',
            paddingTop: '6px',
            paddingBottom: 0,
          }}
        >
          <>
            <div className="col">
              <SolidIcon name="logs" fill="#3E63DD" width="20" style={{ marginRight: '8px' }} />
              <a
                className="color-primary tj-docs-link tj-text-sm"
                data-cy="link-read-documentation"
                href={docLink}
                target="_blank"
                rel="noreferrer"
              >
                {t('globals.readDocumentation', 'Read documentation')}
              </a>
            </div>
            <div className="col-auto d-flex gap-2">
              {selectedDataSource?.kind === 'googlesheetsv2' ? (
                <>
                  <ButtonSolid
                    className={`m2 googlesheetsv2-save-btn${isSaving ? ' btn-loading' : ''}`}
                    isLoading={isSaving}
                    disabled={isSaving || isDisabled || !hasFieldsChanged()}
                    onClick={() => saveDataSource()}
                    variant="tertiary"
                  >
                    {t('globals.save', 'Save')}
                  </ButtonSolid>
                  {(!authStatus || authStatus === 'waiting_for_url') && (
                    <ButtonSolid
                      className={cx('m2', { 'btn-loading': authStatus === 'waiting_for_url' })}
                      isLoading={authStatus === 'waiting_for_url'}
                      disabled={isSaving || isDisabled || !hasFieldsChanged()}
                      onClick={() => authorizeWithProvider()}
                      variant="primary"
                    >
                      {t(`${selectedDataSource.kind}.saveAndConnect${dataSourceNameCapitalize}`, 'Save and Connect')}
                    </ButtonSolid>
                  )}
                </>
              ) : (
                <>
                  {authStatus === 'waiting_for_token' && (
                    <Button
                      className={`m2 ${isSaving ? ' loading' : ''}`}
                      disabled={isSaving}
                      onClick={() => saveDataSource()}
                    >
                      {isSaving ? t('globals.saving', 'Saving...') : t('globals.saveDatasource', 'Save data source')}
                    </Button>
                  )}

                  {(!authStatus || authStatus === 'waiting_for_url') && (
                    <Button
                      className={cx('m2', { 'btn-loading': authStatus === 'waiting_for_url' })}
                      disabled={isSaving}
                      onClick={() => authorizeWithProvider()}
                    >
                      {t(
                        `${selectedDataSource.kind}.connect${dataSourceNameCapitalize}`,
                        `Connect to ${dataSourceNameCapitalize}`
                      )}
                    </Button>
                  )}
                </>
              )}
            </div>
          </>
        </Modal.Footer>
      )}
    </div>
  );
};

export default OAuthWrapper;
