              rel="noreferrer"
              data-cy="link-read-documentation"
            >
              {t('globals.readDocumentation', 'Read documentation')}
            </a>
          </div>
        </div>
        <div className="col-auto">
          {authStatus === 'waiting_for_token' && (
            <Button
