export function ToolTip({
  message,
  children,
  placement = 'top',
  trigger = ['hover', 'focus'],
  delay = { show: 50, hide: 100 },
  show = true,
  tooltipClassName = '',
  ...rest
}) {
  if (!show) {
    return children;
  }
  return (
    <OverlayTrigger
      trigger={trigger}
      placement={placement}
      delay={delay}
      popperConfig={rest?.popperConfig}
      overlay={
        <Tooltip
          className={tooltipClassName}
          style={{ width: rest?.width ?? 'auto', maxWidth: rest?.maxWidth ?? undefined }}
        >
          {message}
        </Tooltip>
      }
    >
      {children}
    </OverlayTrigger>
  );
}
