    return fieldKey === 'connection_format';
  },
};
export const validatePostgresConnectionString = (connectionString) => {
  if (!connectionString || connectionString.trim() === '') {
    return { valid: false, error: 'Connection string is required' };
  }

  const trimmed = connectionString.trim();

  if (!trimmed.startsWith('postgres://') && !trimmed.startsWith('postgresql://')) {
    return {
      valid: false,
      error: "Invalid protocol. Connection string must start with 'postgres://' or 'postgresql://'",
    };
  }

  try {
    const url = new URL(trimmed);

    if (!url.hostname) {
      return { valid: false, error: 'Missing host in connection string' };
    }

    if (url.port) {
      const port = parseInt(url.port);
      if (isNaN(port) || port < 1 || port > 65535) {
        return {
          valid: false,
          error: 'Invalid port number. Must be between 1 and 65535',
        };
      }
    }

    try {
      if (url.username) decodeURIComponent(url.username);
      if (url.password) decodeURIComponent(url.password);
      if (url.pathname) decodeURIComponent(url.pathname.replace(/^\//, ''));
    } catch {
      return {
        valid: false,
        error: 'Invalid URL encoding in connection string credentials',
      };
    }

    return { valid: true, error: '' };
  } catch {
    return { valid: false, error: 'Malformed PostgreSQL connection string' };
  }
};

export const parsePostgresConnectionString = (connectionString) => {
  if (!connectionString || connectionString.trim() === '') {
    return null;
  }

  try {
    const url = new URL(connectionString.trim());

    const sslmode = url.searchParams.get('sslmode');
    const ssl = url.searchParams.get('ssl'); // for ORM-generated strings

    const isSslOn =
      sslmode === 'require' ||
      sslmode === 'verify-full' ||
      sslmode === 'verify-ca' ||
      sslmode === 'prefer' ||
      sslmode === 'allow' ||
      sslmode === 'on' ||
      sslmode === 'yes' ||
      ssl === 'true' ||
      ssl === 'on' ||
      ssl === 'yes' ||
      ssl === '1';

    const isSslOff =
      sslmode === 'disable' ||
      sslmode === 'off' ||
      sslmode === 'no' ||
      ssl === 'false' ||
      ssl === 'off' ||
      ssl === 'no' ||
      ssl === '0';

    return {
      host: url.hostname || '',
      port: url.port || '5432',
      username: decodeURIComponent(url.username || ''),
      password: decodeURIComponent(url.password || ''),
      database: decodeURIComponent(url.pathname.replace(/^\//, '') || ''),
      ssl_enabled: isSslOn ? true : isSslOff ? false : undefined,
      query_params: url.search || '',
      protocol: url.protocol.replace(':', ''),
    };
  } catch {
    return null;
  }
};

