const infoIcon = createElement(Info, { size: 18, fill: '#3E63DD', color: 'white' });

const toastStyle = {
  maxWidth: '100vw',
  width: 'fit-content',
  padding: '14px 16px',
  borderRadius: 8,
  background: '#fff',
  border: '1px solid var(--border-default, #E6E8EB)',
  boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
  fontSize: 14,
  whiteSpace: 'nowrap',
  color: 'var(--text-default, #11181C)',
