    if (parsed[field] !== undefined && !manuallyEditedFieldsRef.current.has(field)) {
      updatedOptions[field] = { value: parsed[field] };
      hasChanges = true;
    }
  }

  if (hasChanges) {
    optionsChanged(updatedOptions);
  }
