          if (added && withToast) {
            const action = detailAction(n);
            showNotificationToast(n, action ? { onViewDetails: (notif) => get().actions.openDetail(notif) } : {});
          }
          if (added) {
            liveSubscribers.forEach((cb) => {
              try {
                cb(n);
              } catch (err) {
                console.error('notification effect failed:', err);
              }
            });
          }
        },
      },
    }),
    { name: 'Notifications' }
  )
);

