        ...provided,
        minHeight: 32,
        height: 'auto',
        border: '1px solid var(--slate7)',
        boxShadow: 'none',
        backgroundColor: state.isDisabled
          ? darkMode
            ? '#1f2936'
            : '#f4f6fa'
