              ? '#F1F3F5'
              : '#fff',
        cursor: 'pointer',
        '&:hover': {
          backgroundColor: darkMode ? '' : '#F8F9FA',
          border: '1px solid hsl(0, 0%, 80%)',
        },
      }),
      valueContainer: (provided) => ({
        ...provided,
        padding: '2px 8px',
        flexWrap: 'wrap',
      }),
      indicatorSeparator: () => ({ display: 'none' }),
      input: (provided) => ({
        ...provided,
        color: darkMode ? '#fff' : '#232e3c',
        margin: 0,
        padding: '2px 0',
