export default OAuth;
import React, { useEffect } from 'react';
import Input from '@/_ui/Input';
import OAuthWrapper from '@/_components/OAuthWrapper';

const OpenapiAuth = ({
  username,
  password,
  bearer_token,
  optionchanged,
  authObject,
  api_keys,
  access_token_url,
  client_id,
  client_secret,
  client_auth,
  custom_auth_params,
  custom_query_params,
  add_token_to,
  header_prefix,
  grant_type,
  scopes,
  auth_url,
  auth_type,
  access_token_custom_headers,
  multiple_auth_enabled,
  currentAppEnvironmentId,
  selectedDataSource,
  workspaceConstants,
  isDisabled,
  isSaving,
  optionsChanged,
  securities,
  audience,
}) => {
  const apiKeyChanges = (key, value) => {
    const apiKeys = api_keys ?? [];
    const updatedKeys = apiKeys.map((item) => {
      if (Array.isArray(authObject)) {
        if (item.parentKey === authObject[0].key) {
          item.fields.map((field) => {
            if (field.key === key) {
              field.value = value;
            }
            return field;
          });
        }
      } else {
        if (item.key === key) {
          item.value = value;
        }
      }
      return item;
    });
    optionchanged('api_keys', updatedKeys);
  };

  const getCurrentKey = (key) => {
    let currentValue;
    if (!api_keys) return '';
    api_keys.map((item) => {
      if (Array.isArray(authObject) && item.parentKey === authObject[0].key) {
        item.fields.map((field) => {
          if (field.key === key) {
            currentValue = field.value;
            return;
          }
        });
        if (currentValue) return;
      }
      if (item.key === key) {
        currentValue = item.value;
        return;
      }
    });
    return currentValue;
  };

  /* To populate the fields from the spec */
  useEffect(() => {
    if (authObject && authObject.type === 'oauth2') {
      if (authObject?.flows?.authorizationCode) {
        const { flows, general_scopes } = authObject;
        const { authorizationUrl, tokenUrl } = flows['authorizationCode'];
        optionchanged('access_token_url', tokenUrl);
        setTimeout(() => {
          optionchanged('auth_url', authorizationUrl);
          if (!scopes || scopes.trim === '') {
            optionchanged('scopes', convertScopesToString(general_scopes));
          }
        }, 500);
      } else if (authObject?.flows?.clientCredentials) {
        // Handle clientCredentials flow
        const { tokenUrl, scopes: flowScopes } = authObject.flows.clientCredentials;
        setTimeout(() => {
          optionchanged('access_token_url', tokenUrl);
          optionchanged('grant_type', 'client_credentials');
          if (!scopes && flowScopes) {
            optionchanged('scopes', Object.keys(flowScopes).join(' '));
          }
        }, 100);
      }
    }
  }, [authObject, grant_type, optionchanged, scopes]);

  const convertScopesToString = (scopes) => {
    let scopes_str = '';
    scopes.map((scope) => {
      scopes_str += scope + ' ';
    });
    return scopes_str;
  };

  if (
    authObject &&
    authObject.type === 'oauth2' &&
    !authObject?.flows?.authorizationCode &&
    !authObject?.flows?.clientCredentials
  ) {
    return null;
  }

  // Function to extract available auth types from the spec
  const extractAuthTypesFromSpec = (securities) => {
    const authTypes = new Set(['none']);

    if (!securities || !Array.isArray(securities)) return Array.from(authTypes);

    securities.forEach((security) => {
      if (Array.isArray(security)) {
        // Multiple auth schemes
        security.forEach((scheme) => {
          if (scheme.type === 'http') {
            if (scheme.scheme === 'basic') authTypes.add('basic');
            if (scheme.scheme === 'bearer') authTypes.add('bearer');
          } else if (scheme.type === 'oauth2') {
            authTypes.add('oauth2');
          }
        });
      } else {
        // Single auth scheme
        if (security.type === 'http') {
          if (security.scheme === 'basic') authTypes.add('basic');
          if (security.scheme === 'bearer') authTypes.add('bearer');
        } else if (security.type === 'oauth2') {
          authTypes.add('oauth2');
        }
      }
    });

    return Array.from(authTypes);
  };

  // Function to extract available OAuth grant types from the spec
  const extractGrantTypesFromSpec = (securities) => {
    const grantTypes = new Set();

    if (!securities || !Array.isArray(securities)) return Array.from(grantTypes);

    securities.forEach((security) => {
      const schemes = Array.isArray(security) ? security : [security];
      schemes.forEach((scheme) => {
        if (scheme.type === 'oauth2' && scheme.flows) {
          Object.keys(scheme.flows).forEach((flowType) => {
            if (flowType === 'authorizationCode') grantTypes.add('authorization_code');
            if (flowType === 'clientCredentials') grantTypes.add('client_credentials');
          });
        }
      });
    });

    return Array.from(grantTypes);
  };

  // Generate dynamic oauth_configs based on the spec
  const generateOAuthConfigs = () => {
    const allowedAuthTypes = extractAuthTypesFromSpec(securities);
    const allowedGrantTypes = extractGrantTypesFromSpec(securities);

    return {
      allowed_scope_field: true,
      allowed_auth_types: allowedAuthTypes,
      allowed_grant_types: allowedGrantTypes,
      allowed_field_groups: {
        authorization_code: [
          'client_id',
          'client_secret',
          'auth_url',
          'access_token_url',
          'client_auth',
          'access_token_custom_headers',
          'custom_query_params',
          'custom_auth_params',
          'add_token_to',
          'header_prefix',
        ],
        client_credentials: [
          'client_id',
          'client_secret',
          'access_token_url',
          'access_token_custom_headers',
          'audience',
        ],
        basic: ['username', 'password'],
        bearer: ['bearer_token'],
      },
    };
  };

  const renderApiKeyField = (auth, index) => {
    if (auth) {
      const value = getCurrentKey(auth.key);
      return (
        <div className="col-md-12" key={index ?? auth.key}>
          <label className="form-label text-muted mt-3">{auth.key}</label>
          <Input
            type="text"
            className="form-control"
            onChange={(e) => apiKeyChanges(auth.key, e.target.value)}
            value={value}
            workspaceConstants={workspaceConstants}
          />
        </div>
      );
    } else return null;
  };

  switch (auth_type) {
    case 'apiKey': {
      if (Array.isArray(authObject)) {
        return (
          <div>
            {authObject.map((auth, index) => {
              return renderApiKeyField(auth, index);
            })}
          </div>
        );
      } else {
        return renderApiKeyField(authObject);
      }
    }
    case 'oauth2':
    case 'bearer':
    case 'basic': {
      const dynamicOAuthConfigs = generateOAuthConfigs();
      return (
        <>
          <OAuthWrapper
            optionchanged={optionchanged}
            options={{
              auth_type: { value: auth_type },
              grant_type: { value: grant_type },
              add_token_to: { value: add_token_to },
              header_prefix: { value: header_prefix },
              access_token_url: { value: access_token_url },
              access_token_custom_headers: { value: access_token_custom_headers },
              client_id: { value: client_id },
              client_secret: { value: client_secret },
              client_auth: { value: client_auth },
              username: { value: username },
              password: { value: password },
              bearer_token: { value: bearer_token },
              auth_url: { value: auth_url },
              custom_auth_params: { value: custom_auth_params },
              custom_query_params: { value: custom_query_params },
              scopes: { value: scopes },
              audience: { value: audience },
            }}
            isSaving={isSaving}
            selectedDataSource={selectedDataSource}
            workspaceConstants={workspaceConstants}
            isDisabled={isDisabled}
            multiple_auth_enabled={multiple_auth_enabled}
            scopes={scopes}
            currentAppEnvironmentId={currentAppEnvironmentId}
            oauth_configs={dynamicOAuthConfigs}
            optionsChanged={optionsChanged}
          />
        </>
      );
    }
    default:
      return null;
  }
};

export default OpenapiAuth;
import React, { useEffect, useState } from 'react';
import Select from '@/_ui/Select';
import Textarea from '@/_ui/Textarea';
import { openapiService } from '@/_services';
import OpenapiAuth from './OpenapiAuth';

const OpenApi = ({
  optionchanged,
  format,
  definition,
  auth_type,
  auth_key,
  bearer_token,
  username,
  password,
  api_keys,
  access_token_url,
  client_id,
  client_secret,
  client_auth,
  custom_auth_params,
  custom_query_params,
  add_token_to,
  header_prefix,
  grant_type,
  scopes,
  auth_url,
  access_token_custom_headers,
  spec,
  workspaceConstants,
  isDisabled,
  multiple_auth_enabled,
  currentAppEnvironmentId,
  selectedDataSource,
  isSaving,
  optionsChanged,
  audience,
}) => {
  const [securities, setSecurities] = useState([]);
  const [loadingSpec, setLoadingSpec] = useState(false);
  const [selectedAuth, setSelectedAuth] = useState();
  const [validationError, setValidationError] = useState();

  useEffect(() => {
    validateDef();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [definition, format]);

  useEffect(() => {
    auth_key && getSelectedAuth();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [auth_key, securities]);

  useEffect(() => {
    spec && setSecurities(resolveSecurities(spec));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [spec]);

  const validateDef = () => {
    if (definition) {
      setLoadingSpec(true);
      setValidationError(null);
      openapiService
        .parseOpenapiSpec(definition, format)
        .then((result) => {
          optionchanged('spec', result);
          setLoadingSpec(false);
        })
        .catch((err) => {
          setValidationError(err?.message ?? 'Enter valid definition');
          setLoadingSpec(false);
          console.log(err);
        });
    }
  };

  const getCurrentKey = (key, parentKey) => {
    let currentValue;
    if (!api_keys) return '';
    api_keys.map((item) => {
      const itemKey = item['parent_key'] ?? item.parentKey;
      if (parentKey && itemKey === parentKey) {
        item.fields.map((field) => {
          if (field.key === key) {
            currentValue = field.value;
            return;
          }
        });
        if (currentValue) return;
      }
      if (item.key === key) {
        currentValue = item.value;
        return;
      }
    });
    return currentValue;
  };

  const resolveSecurities = (spec) => {
    const authArray = [];
    const ApiKeys = [];
    const securities = spec['security'];
    if (securities) {
      const scheme = spec?.components?.securitySchemes;
      securities.map((security) => {
        const authNames = Object.keys(security);
        if (authNames.length > 1) {
          const authObject = [];
          const multipleKeys = { parentKey: authNames[0], fields: [] };
          authNames.map((authName, index) => {
            const auth = scheme[authName];
            if (auth) {
              auth['key'] = authName;
              authObject.push(auth);
              if (auth.type === 'apiKey') {
                multipleKeys.fields.push({ ...auth, value: getCurrentKey(auth.key, authNames[0]) });
                if (authNames.length == index + 1) ApiKeys.push(multipleKeys);
              }
            }
          });
          authObject.length > 0 && authArray.push(authObject);
        } else {
          const authName = authNames[0];
          const auth = scheme[authName];
          if (auth) {
            auth['key'] = authName;
            if (auth.type === 'apiKey') {
              const apiKeyObj = { ...auth, value: getCurrentKey(auth.key) };
              ApiKeys.push(apiKeyObj);
            } else if (auth.type === 'oauth2') {
              const scopes = security[authName];
              auth['general_scopes'] = scopes;
            }
            authArray.push(auth);
          }
        }
      });
    }
    optionchanged('api_keys', ApiKeys);
    return authArray;
  };

  const resolveAuthTypes = (auth) => {
    switch (auth.type) {
      case 'http':
        return {
          name: `${auth.key} (${auth?.scheme?.charAt(0).toUpperCase() + auth?.scheme?.slice(1)})`,
          value: auth.key,
        };
      case 'apiKey':
        return { name: `${auth.key} (API Key)`, value: auth.key };
      case 'oauth2':
        return { name: `${auth.key} (Oauth2)`, value: auth.key };
    }
  };

  const computeAuthOptions = () => {
    const options = [];
    securities.map((auth) => {
      if (Array.isArray(auth)) {
        const resolved = resolveAuthTypes(auth[0]);
        resolved && options.push(resolved);
      } else {
        const resolved = resolveAuthTypes(auth);
        resolved && options.push(resolved);
      }
    });
    return options;
  };

  const getSelectedAuth = () => {
    securities.map((security) => {
      if (Array.isArray(security)) {
        if (security[0].key === auth_key) {
          optionchanged('auth_type', security[0].scheme ?? security[0].type);
          setSelectedAuth(security);
        }
      } else {
        if (security.key === auth_key) {
          setSelectedAuth(security);
          optionchanged('auth_type', security.scheme ?? security.type);
        }
      }
    });
  };

  return (
    <>
      <Select
        options={[
          { name: 'JSON', value: 'json' },
          { name: 'YAML', value: 'yaml' },
        ]}
        value={format}
        onChange={(value) => optionchanged('format', value)}
        width={'100%'}
        useMenuPortal={false}
        isDisabled={isDisabled}
      />
      <div className="col-md-12" data-cy="definition-section">
        <label className="form-label text-muted mt-3" data-cy="label-definition">
          Definition
        </label>
        <Textarea
          data-cy="definition-input-field"
          placehlder="Enter spec definition"
          className="form-control"
          rows="14"
          value={definition}
          onChange={(e) => optionchanged('definition', e.target.value)}
          workspaceConstants={workspaceConstants}
          disabled={isDisabled}
        />
      </div>

      {loadingSpec && (
        <div className="p-3">
          {!validationError ? (
            <>
              <div className="spinner-border spinner-border-sm text-azure mx-2" role="status"></div>
              Please wait while we are validating the OpenAPI specification.
            </>
          ) : (
            <span style={{ color: 'red' }}>{validationError}</span>
          )}
        </div>
      )}

      {!loadingSpec && Array.isArray(securities) && securities.length > 0 && (
        <>
          <div className="col-md-12 mb-3">
            <label className="form-label text-muted mt-3">Authentication</label>
            <Select
              options={computeAuthOptions()}
              value={auth_key}
              onChange={(value) => optionchanged('auth_key', value)}
              width={'100%'}
              useMenuPortal={false}
              isDisabled={isDisabled}
            />
          </div>

          <OpenapiAuth
            username={username}
            password={password}
            optionchanged={optionchanged}
            bearer_token={bearer_token}
            authObject={selectedAuth}
            api_keys={api_keys}
            add_token_to={add_token_to}
            header_prefix={header_prefix}
            access_token_url={access_token_url}
            grant_type={grant_type}
            custom_auth_params={custom_auth_params}
            custom_query_params={custom_query_params}
            access_token_custom_headers={access_token_custom_headers}
            client_id={client_id}
            client_secret={client_secret}
            client_auth={client_auth}
            scopes={scopes}
            auth_url={auth_url}
            auth_type={auth_type}
            multiple_auth_enabled={multiple_auth_enabled}
            currentAppEnvironmentId={currentAppEnvironmentId}
            selectedDataSource={selectedDataSource}
            isDisabled={isDisabled}
            isSaving={isSaving}
            optionsChanged={optionsChanged}
            securities={securities}
            audience={audience}
            workspaceConstants={workspaceConstants}
          />
        </>
      )}
    </>
  );
};

