import React, { useState } from 'react';
import { SketchPicker } from 'react-color';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Popover from 'react-bootstrap/Popover';
import classNames from 'classnames';
import { computeColor } from '@/_helpers/utils';
import { Tooltip } from 'react-bootstrap';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import useStore from '@/AppBuilder/_stores/store';

const coerceColorString = (v) => (typeof v === 'string' ? v : '');

const BaseColorSwatches = ({
  value,
  onChange,
  pickerStyle = {},
  colorMap = {},
  cyLabel,
  asBoxShadowPopover = true,
  meta,
  outerWidth = '142px',
  component,
  styleDefinition,
  componentType = 'color',
  componentId,
  CustomOptionList = () => {},
  SwatchesToggle = () => {},
  onReset,
}) => {
  const computeColorForPopoverMenu = useStore((state) => state.computeColorForPopoverMenu);
  const darkMode = localStorage.getItem('darkMode') === 'true';
  value = coerceColorString(value);
  if (component == 'PopoverMenu') {
    value = computeColorForPopoverMenu(value, meta, componentId);
  } else if (component == 'Button' || component == 'FileButton') {
    value = computeColor(styleDefinition, value, meta, component);
  } else if (component == 'Html' && !value) {
    // Empty string is the "unset" sentinel (backward compatibility for pre-existing widgets);
    // show the mode-appropriate backdrop Html.jsx actually falls back to, not a blank swatch.
    value = darkMode ? '#47505D' : '#ffffff';
  }
  value = coerceColorString(value);
  const [showPicker, setShowPicker] = useState(false);
  const colorPickerPosition = meta?.colorPickerPosition ?? '';
  const coverStyles = {
    position: 'fixed',
    top: '0px',
    right: '0px',
    bottom: '0px',
    left: '0px',
  };
  const outerStyles = {
    width: outerWidth,
    height: '32px',
    borderRadius: ' 6px',
    border: 'none',
    display: 'flex',
    paddingLeft: '4px',
    alignItems: 'center',
    gap: '4px',
    background: showPicker && 'var(--indigo2)',
    outline: showPicker && '1px solid var(--indigo9)',
    boxShadow: showPicker && '0px 0px 0px 1px #C6D4F9',
  };

  const decimalToHex = (alpha) => {
    let aHex = Math.round(255 * alpha).toString(16);
    return alpha === 0 ? '00' : aHex.length < 2 ? `0${aHex}` : aHex;
  };

  const handleColorChange = (color) => {
    const { r, g, b, a } = color.rgb;
    const toHex = (n) => n.toString(16).padStart(2, '0');
    const hexCode = `#${toHex(r)}${toHex(g)}${toHex(b)}${decimalToHex(a ?? 1.0)}`;
    onChange(hexCode);
  };

  const eventPopover = () => {
    return (
      <Popover
        className={classNames(
          'codebuilder-color-swatches-popover',
          { 'dark-theme': darkMode },
          { 'inspector-color-input-popover': colorPickerPosition === 'top' }
        )}
        style={{ zIndex: 999999 }}
      >
        <Popover.Body
          className={!asBoxShadowPopover && 'boxshadow-picker'}
          style={{
            padding: '0px',
            marginLeft: '-16px',
          }}
        >
          <>{ColorPicker()}</>
        </Popover.Body>
      </Popover>
    );
  };

  const ColorPicker = () => {
    return (
      <div className="codebuilder-color-picker">
        {SwatchesToggle()}
        {showPicker && componentType === 'swatches' && (
          <div
            style={{
              maxHeight: '200px',
              overflowY: 'auto',
              padding: '8px',
              paddingTop: '0px',
              '&::-webkit-scrollbar': {
                display: 'none',
              },
              msOverflowStyle: 'none',
              scrollbarWidth: 'none',
            }}
          >
            {CustomOptionList()}
          </div>
        )}
        {showPicker && componentType === 'color' && (
          <div>
            {/* <div style={coverStyles} onClick={() => setShowPicker(false)} /> */}
            <div style={pickerStyle}>
              <SketchPicker
                onFocus={() => setShowPicker(true)}
                color={value}
                onChangeComplete={handleColorChange}
                style={{ bottom: 0 }}
              />
            </div>
          </div>
        )}
      </div>
    );
  };
  const ColorPickerInputBox = () => {
    return (
      <div
        className="row mx-0 color-picker-input d-flex"
        onClick={() => setShowPicker(true)}
        data-cy={`${String(cyLabel)}-picker`}
        style={outerStyles}
      >
        <div className="color-icon" style={{ backgroundColor: value, marginLeft: '4px' }} />

        <div
          className="col tj-text-xsm p-0 color-slate12"
          data-cy={`${String(cyLabel)}-value`}
          style={{
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}
        >
          {colorMap?.[value]
            ? colorMap[value]
                .split('/')
                .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
                .join('/')
            : value}
        </div>
        {typeof onReset === 'function' && (
          <div className="col-auto p-0">
            <OverlayTrigger placement="left" overlay={<Tooltip id="reset-default-color">Reset to default</Tooltip>}>
              <div onClick={onReset} className="color-reset">
                <SolidIcon name="reset" />
              </div>
            </OverlayTrigger>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="row fx-container" data-cy="color-picker-parent">
      <div className="col">
        <div className="field">
          {!asBoxShadowPopover ? (
            <>
              {ColorPicker()}
              {ColorPickerInputBox()}
            </>
          ) : (
            <OverlayTrigger
              onToggle={(showPicker) => {
                setShowPicker(showPicker);
              }}
              show={showPicker}
              trigger="click"
              placement={!colorPickerPosition ? 'bottom' : colorPickerPosition}
              flip={true}
              fallbackPlacements={['top', 'left']}
              rootClose={true}
              overlay={eventPopover()}
              rootCloseEvent="mousedown" // close picker when mousedown anywhere on screen
            >
              {ColorPickerInputBox()}
            </OverlayTrigger>
          )}
        </div>
      </div>
    </div>
  );
};

