import React, { useState } from 'react';
import cx from 'classnames';
import { appsService } from '@/_services';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import ReleaseConfirmation from '@/AppBuilder/Header/ReleaseConfirmation';
import { shallow } from 'zustand/shallow';
import '@/_styles/versions.scss';

import { Globe } from 'lucide-react';
import { Button } from '@/components/ui/Button/Button';
import useStore from '@/AppBuilder/_stores/store';
import { ToolTip } from '@/_components/ToolTip';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';

const ReleaseVersionButton = function DeployVersionButton({ version = null, variant = 'default', darkMode = false }) {
  const { moduleId } = useModuleContext();
  const [isReleasing, setIsReleasing] = useState(false);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const getCanPromoteAndRelease = useStore((state) => state.getCanPromoteAndRelease);
  const { isReleaseVersionEnabled } = getCanPromoteAndRelease();
  const { isVersionReleased, updateReleasedVersionId, appId, versionToBeReleased, name } = useStore(
    (state) => ({
      isVersionReleased: version
        ? state.releasedVersionId === version.id
        : state.releasedVersionId === state.selectedVersion?.id,
      name: version?.name || state?.selectedVersion?.name,
      isEditorFreezed: state.isEditorFreezed,
      updateReleasedVersionId: state.updateReleasedVersionId,
      appId: state.appStore.modules[moduleId]?.app?.appId ?? state.appId,
      versionToBeReleased: version?.id || state.currentVersionId,
      // selectedVersionId: state.selectedVersion.id,
    }),
    shallow
  );
  const { t } = useTranslation();

  const releaseVersion = () => {
    setIsReleasing(true);
    appsService
      .releaseVersion(appId, versionToBeReleased)
      .then(() => {
        toast(`Version ${name} released`, {
          icon: '🚀',
        });

        updateReleasedVersionId(versionToBeReleased);

        setIsReleasing(false);
        setShowConfirmation(false);
      })
      .catch((error) => {
        const rawError = error?.error || error?.message;
        const errorMessage =
          typeof rawError === 'object'
            ? rawError.error
            : rawError || `${name} could not be released. Please try again!`;
        const errorDetails = typeof rawError === 'object' ? rawError.details : errorMessage;
        toast.error(errorMessage);
        setIsReleasing(false);
        setShowConfirmation(false);
        try {
          useStore.getState().debugger.log({
            logLevel: 'error',
            type: 'component',
            key: 'Release Failed',
            message: errorMessage,
            description: errorDetails || errorMessage,
            error: { message: errorMessage, description: errorDetails || errorMessage },
            errorTarget: 'Version',
            timestamp: new Date().toISOString(),
          });
        } catch (_) {
          // debugger may not be available
        }
      });
  };

  const onReleaseButtonClick = (e) => {
    if (e) e.stopPropagation();
    setShowConfirmation(true);
  };

  const onReleaseConfirm = () => {
    releaseVersion();
  };

  // Inline variant for dropdown
  if (variant === 'inline') {
    return (
      <>
        <ReleaseConfirmation
          show={showConfirmation}
          onClose={() => setShowConfirmation(false)}
          onConfirm={onReleaseConfirm}
        />
        <ToolTip
          message={
            !isReleaseVersionEnabled
              ? "You don't have access to release application. Contact admin to know more."
              : 'Release this version'
          }
          placement="left"
          width="280px"
        >
          <span>
            <button
              className={cx('btn btn-sm version-action-btn', { 'dark-theme theme-dark': darkMode })}
              disabled={isVersionReleased || !isReleaseVersionEnabled || isReleasing}
              onClick={onReleaseButtonClick}
              data-cy="release-version-button"
            >
              {isReleasing ? 'Releasing...' : 'Release'}
            </button>
          </span>
        </ToolTip>
      </>
    );
  }

  // Default variant (header button)
  return (
    <>
      <ReleaseConfirmation
        show={showConfirmation}
        onClose={() => setShowConfirmation(false)}
        onConfirm={onReleaseConfirm}
      />
      <div>
        <ToolTip
          message="You don't have access to release application. Contact admin to know more."
          placement="bottom"
          show={!isReleaseVersionEnabled}
          width="280px"
        >
          <Button
            variant="secondary"
            data-cy={`button-release`}
            className={cx('tw-text-text-default', {
              'released-button': isVersionReleased,
            })}
            isLoading={isReleasing}
            disabled={isVersionReleased || !isReleaseVersionEnabled}
            onClick={onReleaseButtonClick}
          >
            <Globe width="16" height="16" className="tw-text-icon-accent" />
            {isVersionReleased ? 'Released' : <>{t('editor.release', 'Release')}</>}
          </Button>
        </ToolTip>
      </div>
    </>
  );
};

export default ReleaseVersionButton;
import React, { useState, useMemo } from 'react';
import cx from 'classnames';
import { Link } from 'react-router-dom';
import { authenticationService, appService, sessionService } from '@/_services';
import { teardownFrontendMetrics } from '@/_services/frontend-metrics.service';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import { useTranslation } from 'react-i18next';
import { getPrivateRoute } from '@/_helpers/routes';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import { useAppDataStore } from '@/_stores/appDataStore';
import { shallow } from 'zustand/shallow';
import { checkIfToolJetCloud } from '@/_helpers/utils';
import { fetchEdition } from '@/modules/common/helpers/utils';

function BaseSettingsMenu({
  darkMode,
  checkForUnsavedChanges,
  featureAccess,
  getPreWorkspaceItems = () => null,
  getMidMenuItems = () => null,
  options = {
    hideMarketPlaceMenuItem: false,
  },
}) {
  const edition = fetchEdition();
  const isEEorCloud = edition === 'ee' || edition === 'cloud';
  const [showOverlay, setShowOverlay] = useState(false);
  const { tooljetVersion } = useAppDataStore(
    (state) => ({
      tooljetVersion: state?.metadata?.installed_version,
    }),
    shallow
  );
  const { t } = useTranslation();

  // Get common user values
  const currentUserValue = authenticationService.currentSessionValue;
  const admin = currentUserValue?.admin;
  const superAdmin = currentUserValue?.super_admin;
  const isBuilder = !!currentUserValue?.user_permissions?.is_builder;
  const isCloudEdition = edition === 'cloud' || (!!tooljetVersion && checkIfToolJetCloud(tooljetVersion));
  const marketplaceEnabled = !options.hideMarketPlaceMenuItem && !isCloudEdition && (admin || superAdmin || isBuilder);
  const isValidUrl = (url) => {
    try {
      new URL(url);
      return true;
    } catch {
      return false;
    }
  };
  async function handleLogout() {
    teardownFrontendMetrics();
    // Get latest config first to ensure we have the most up-to-date custom logout url
    await appService
      .getConfig()
      .then((config) => {
        window.public_config = config;
        const customLogoutUrl = window.public_config?.CUSTOM_LOGOUT_URL;
        if (customLogoutUrl && isValidUrl(customLogoutUrl)) {
          sessionService.logout().then(() => {
            window.location.href = customLogoutUrl;
          });
          return;
        }
        sessionService.logout();
      })
      .catch(() => {
        sessionService.logout();
      });
  }
  const hasCustomGroupsLicense = useMemo(() => {
    if (!featureAccess) return false;
    return featureAccess.customGroups === true && featureAccess.licenseStatus?.isLicenseValid !== false;
  }, [featureAccess]);

  const isGroupAdmin = !!currentUserValue?.is_group_admin && hasCustomGroupsLicense;
  const canAccessWorkspaceSettings = !!admin || (isEEorCloud && isBuilder) || isGroupAdmin;

  const getWorkspaceSettingsRoute = () => {
    if (isGroupAdmin) {
      return getPrivateRoute('workspace_settings_groups');
    }
    if (isBuilder && isEEorCloud) {
      return getPrivateRoute('workspace_settings_builder');
    }
    return getPrivateRoute('workspace_settings');
  };
  // Closing the overlay used to happen incidentally whenever navigation remounted this whole
  // component tree. Now that the shared Layout/sidebar can persist across navigation, that implicit
  // reset no longer happens, so each item must close the overlay explicitly — but only when
  // navigation actually proceeds (checkForUnsavedChanges calls preventDefault() to block it when
  // there are unsaved changes, in which case the overlay should stay as-is).
  const closeOverlayIfNotPrevented = (event) => {
    if (!event.defaultPrevented) {
      setShowOverlay(false);
    }
  };

  const getOverlay = () => {
    // Get the extension items with the required context
    const preWorkspaceContent = getPreWorkspaceItems({
      admin,
      superAdmin,
      featureAccess,
      checkForUnsavedChanges,
      closeOverlay: closeOverlayIfNotPrevented,
    });
    const midMenuContent = getMidMenuItems({
      admin,
      superAdmin,
      featureAccess,
      checkForUnsavedChanges,
      closeOverlay: closeOverlayIfNotPrevented,
    });
    const currentVersion = localStorage.getItem('currentVersion');
    return (
      <div className={`settings-card tj-text card ${darkMode ? 'dark-theme' : ''}`}>
        <div className="tw-px-2.5 tw-py-2 tw-text-xs tw-font-light tw-text-text-placeholder" data-cy="version-label">
          <span>Version {currentVersion}</span>
        </div>
        <div className="divider" />
        {/* Marketplace section */}
        {marketplaceEnabled && tooljetVersion && !checkIfToolJetCloud(tooljetVersion) && (
          <Link
            onClick={(event) => {
              checkForUnsavedChanges('/integrations/marketplace', event);
              closeOverlayIfNotPrevented(event);
            }}
            to={'/integrations/marketplace'}
            className="dropdown-item tj-text-xsm"
            data-cy="marketplace-option"
          >
            <span>Marketplace</span>
          </Link>
        )}

        {/* Pre-workspace extension point (Audit logs) */}
        {preWorkspaceContent}

        {/* Add divider if either marketplace or pre-workspace items exist */}
        {(marketplaceEnabled || preWorkspaceContent) && <div className="divider"></div>}

        {/* Super Admin Settings */}
        {superAdmin && midMenuContent}

        {/* Specifically for Cloud Edition */}
        {edition === 'cloud' && admin && !superAdmin && midMenuContent}

        {/* Admin section - Workspace settings */}
        {/* Admin and builder both can access workspace setting.
            Builder can access for themes.  */}
        {canAccessWorkspaceSettings && (
          <Link
            onClick={(event) => {
              checkForUnsavedChanges(getWorkspaceSettingsRoute(), event);
              closeOverlayIfNotPrevented(event);
            }}
            to={getWorkspaceSettingsRoute()}
            className="dropdown-item tj-text-xsm"
            data-cy="workspace-settings"
          >
            <span>Workspace settings</span>
          </Link>
        )}

        {/* Profile settings */}
        <Link
          onClick={(event) => {
            checkForUnsavedChanges(getPrivateRoute('profile_settings'), event);
            closeOverlayIfNotPrevented(event);
          }}
          to={getPrivateRoute('profile_settings')}
          className="dropdown-item tj-text-xsm"
          data-cy="profile-settings"
        >
          <span>Profile settings</span>
        </Link>

        {/* Add divider before logout */}
        <div className="divider"></div>

        {/* Logout */}
        <Link
          data-testid="logoutBtn"
          to="#"
          onClick={handleLogout}
          className="dropdown-item text-danger tj-text-xsm"
          data-cy="logout-link"
        >
          <span>{t('header.logout', 'Logout')}</span>
        </Link>
      </div>
    );
  };

  return (
    <OverlayTrigger
      show={showOverlay}
      onToggle={setShowOverlay}
      rootClose={true}
