import React, { useState, useRef, useEffect } from 'react';
import { organizationService } from '@/_services';
import AlertDialog from '@/_ui/AlertDialog';
import { useTranslation } from 'react-i18next';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import { validateName, handleHttpErrorMessages } from '@/_helpers/utils';
import { appendWorkspaceId, getBaseHostURL, isCustomDomain } from '@/_helpers/routes';
import { useSessionTransferRedirect } from '@/_helpers/useSessionTransferRedirect';
import _ from 'lodash';
import { FormWrapper } from '@/_components/FormWrapper';
import { toast } from 'react-hot-toast';
import posthogHelper from '@/modules/common/helpers/posthogHelper';

export const CreateOrganization = ({ showCreateOrg, setShowCreateOrg }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [name, setName] = useState({ value: null, error: '' });
  const [slug, setSlug] = useState({ value: null, error: '' });
  const [slugProgress, setSlugProgress] = useState(false);
  const [workspaceNameProgress, setWorkspaceNameProgress] = useState(false);
  const [isNameDisabled, setNameDisabled] = useState(true);
  const [isSlugDisabled, setSlugDisabled] = useState(true);
  const darkMode = localStorage.getItem('darkMode') === 'true';
  const { t } = useTranslation();
  const isSlugSet = useRef(false); // Flag to track if slug has been initially set
  const sluginput = useRef('');
  const redirectWithSessionTransfer = useSessionTransferRedirect('createWorkspace');
  const createOrganization = () => {
    let emptyError = false;
    [name, slug].map((field, index) => {
      if (!field?.value?.trim()) {
        index === 0
          ? setName({
              ...name,
              error: {
                error: `Workspace name can't be empty`,
              },
            })
          : setSlug({ ...slug, error: `Workspace slug can't be empty` });
        emptyError = true;
      }
    });
    const errorFound = !_.isEmpty(name.error) || !_.isEmpty(slug.error);

    if (!emptyError && !errorFound) {
      const slugValue = slug.value;
      setIsCreating(true);
      organizationService.createOrganization({ name: name.value, slug: slugValue }).then(
        (data) => {
          posthogHelper.captureEvent('create_workspace', {
            workspace_id: data?.organization_id || data?.current_organization_id || data?.id,
          });
          // Added this to show the toast for some seconds before re-loading the page
          toast.success('Workspace created successfully', { duration: 900 });
          setIsCreating(false);
          closeModal();
          setTimeout(() => {
            const newPath = appendWorkspaceId(slugValue, location.pathname, true);
            if (isCustomDomain()) {
              redirectWithSessionTransfer(
                getBaseHostURL(),
                newPath,
                data?.organization_id || data?.current_organization_id
              );
            } else {
              window.history.replaceState(null, null, newPath);
              window.location.reload();
            }
          }, 950);
        },
        (error) => {
          setIsCreating(false);
          // added specific check here to inform user about
          if (error?.error && error.error.includes('reached your limit for number of builders')) {
            toast.error(
              `Creating a workspace makes you a builder which exceeds your limit. Contact super admin to know more`,
              {
                style: {
                  width: 'auto',
                  maxWidth: '385px',
                },
              }
            );
          } else if (error?.error && error.error.includes('reached the number of workspaces')) {
            closeModal();
          } else {
            handleHttpErrorMessages(error, 'workspace');
          }
        }
      );
    }
  };

  const handleInputChange = async (value, field) => {
    const trimmedValue = value?.trim();
    if (field === 'slug') {
      setSlug({
        ...slug,
        error: null,
      });
    }
    if (field === 'name') {
      setName({
        ...name,
        error: null,
      });
    }
    let error = validateName(
      value,
      `Workspace ${field}`,
      true,
      false,
      !(field === 'slug'),
      !(field === 'slug'),
      field === 'slug'
    );
    /* If the basic validation is passing. then check the uniqueness */
    if (error?.status === true) {
      try {
        await organizationService.checkWorkspaceUniqueness(
          field === 'name' ? trimmedValue : null,
          field === 'slug' ? value : null
        );
      } catch (errResponse) {
        error = {
          status: false,
          errorMsg: errResponse?.error,
        };
      }
    }
    const disabled = !error?.status;
    const updatedValue = {
      value,
      error: error?.errorMsg,
    };

    if (field === 'slug') {
      setSlug(updatedValue);
      setSlugDisabled(disabled);
      setSlugProgress(false);
    }
    if (field === 'name') {
      setName(updatedValue);
      setNameDisabled(disabled);
      setWorkspaceNameProgress(false);
    }
    return;
  };

  const handleKeyDown = (e) => {
    if (e.keyCode === 13) {
      e.preventDefault();
      createOrganization();
    }
  };

  const closeModal = () => {
    /* reseting states */
    setName({ value: null, error: '' });
    setSlug({ value: null, error: '' });
    setShowCreateOrg(false);
    setNameDisabled(true);
    setSlugDisabled(true);
    isSlugSet.current = false;
  };

  const delayedSlugChange = _.debounce(async (value) => {
    setSlugProgress(true);
    await handleInputChange(value, 'slug');
  }, 300);
  const delayedNameChange = _.debounce(async (value) => {
    setWorkspaceNameProgress(true);
    await handleInputChange(value, 'name');
  }, 300);
  useEffect(() => {
    if (!isSlugSet.current && name.value && !slugProgress && !workspaceNameProgress) {
      const defaultValue =
        name?.value
          .replace(/\s+/g, '')
          .toLowerCase()
          .replace(/[^a-z0-9-\s]/g, '') || '';
      setSlug({ value: defaultValue, error: '' });

      const checkWorkspaceUniqueness = async () => {
        sluginput.current.value = defaultValue;
        try {
          await organizationService.checkWorkspaceUniqueness(null, defaultValue);
        } catch (errResponse) {
          let error = {
            status: false,
            errorMsg: errResponse?.error,
          };
          setSlug({ value: defaultValue, error: error?.errorMsg });
        }
      };
      checkWorkspaceUniqueness();
      setSlugDisabled(false);
      setSlugProgress(false);
    }
    if (slugProgress && !isSlugSet.current) {
      // this is to denote that the user has tried editing the slug -- so now slug and name are independent of each other
      isSlugSet.current = true;
    }
  }, [name.value, slugProgress, workspaceNameProgress, isSlugSet]);

  const isDisabled =
    isCreating ||
    isNameDisabled ||
    isSlugDisabled ||
    slugProgress ||
    workspaceNameProgress ||
    slug?.error ||
    name?.error;

  return (
    <AlertDialog
      show={showCreateOrg}
      closeModal={closeModal}
      title={t('header.organization.createWorkspace', 'Create workspace')}
    >
      <FormWrapper callback={createOrganization}>
        <div className="workspace-folder-modal">
          <div className="row">
            <div className="tj-app-input">
              <label data-cy="workspace-name-label">Workspace name</label>
              <input
                type="text"
                onChange={async (e) => {
                  e.persist();
                  await delayedNameChange(e.target.value);
                }}
                className={`form-control ${name?.error ? 'is-invalid' : 'is-valid'}`}
                placeholder={t('header.organization.workspaceName', 'Workspace name')}
                disabled={isCreating}
                maxLength={50}
                data-cy="workspace-name-input-field"
                autoFocus
              />
              {name?.error ? (
                <label className="label tj-input-error mt-1" data-cy="workspace-error-label">
                  {name?.error || ''}
                </label>
              ) : name.value && !workspaceNameProgress ? (
                <label className="label label-success" data-cy="slug-sucess-label">{`Workspace name accepted!`}</label>
              ) : (
                <label className="label label-info mt-1" data-cy="workspace-name-info-label">
                  Name must be unique and max 50 characters
                </label>
              )}
            </div>
          </div>
          <div className="row">
            <div className="tj-app-input input-with-icon">
              <label data-cy="slug-input-label">Unique workspace slug</label>
              <input
                type="text"
                className={`form-control ${slug?.error ? 'is-invalid' : 'is-valid'}`}
                placeholder={t('header.organization.workspaceSlug', 'Unique workspace slug')}
                disabled={isCreating}
                ref={sluginput}
                maxLength={50}
                defaultValue={slug.value || ''}
                onChange={async (e) => {
                  e.persist();
                  await delayedSlugChange(e.target.value);
                }}
                data-cy="workspace-slug-input-field"
                autoFocusfields
              />
              {!slugProgress && slug.value !== null && !slug.error && (
                <div className="icon-container">
                  <svg width="15" height="10" viewBox="0 0 15 10" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path
                      fillRule="evenodd"
                      clipRule="evenodd"
                      d="M14.256 0.244078C14.5814 0.569515 14.5814 1.09715 14.256 1.42259L5.92263 9.75592C5.59719 10.0814 5.06956 10.0814 4.74412 9.75592L0.577452 5.58926C0.252015 5.26382 0.252015 4.73618 0.577452 4.41074C0.902889 4.08531 1.43053 4.08531 1.75596 4.41074L5.33337 7.98816L13.0775 0.244078C13.4029 -0.0813592 13.9305 -0.0813592 14.256 0.244078Z"
                      fill="#46A758"
                    />
                  </svg>
                </div>
              )}

              {slug?.error ? (
                <label className="label tj-input-error mt-1" data-cy="input-label-error">
                  {slug?.error || ''}
                </label>
              ) : slug.value && !slugProgress ? (
                <label className="label label-success mt-1" data-cy="slug-sucess-label">{`Slug accepted!`}</label>
              ) : (
                <label
                  className="label label-info mt-1"
                  data-cy="slug-info-label"
                >{`URL-friendly 'slug' consists of lowercase letters, numbers, and hyphens`}</label>
              )}
            </div>
          </div>
          <div className="row mb-3">
            <div className="col modal-main tj-app-input">
              <label data-cy="workspace-link-label">Workspace link</label>
              <div className={`tj-text-input break-all ${darkMode ? 'dark' : ''}`} data-cy="slug-field">
                {!slugProgress ? (
                  `${getBaseHostURL()}/${slug?.value || '<workspace-slug>'}`
                ) : (
                  <div className="d-flex gap-2">
                    <div class="spinner-border text-secondary workspace-spinner" role="status">
                      <span class="visually-hidden">Loading...</span>
                    </div>
                    {`Updating link`}
                  </div>
                )}
              </div>
              <label className="label label-success label-updated" data-cy="slug-error-label">
                {slug.value && !slug.error && !slugProgress ? `Link updated successfully!` : ''}
              </label>
            </div>
          </div>
          <div className="row">
            <div className="col d-flex justify-content-end gap-2">
              <ButtonSolid variant="secondary" onClick={closeModal} data-cy="cancel-button" className="cancel-btn">
                {t('globals.cancel', 'Cancel')}
              </ButtonSolid>
              <ButtonSolid
                type="submit"
                disabled={isDisabled}
                onClick={createOrganization}
                data-cy="create-workspace-button"
                isLoading={isCreating}
