// A single data-source folder row: expand/collapse header + (when expanded) its data-source rows.
// Folder icon states mirror the design: `folder-dot` when it has items, `folder` when empty, and
// `folder-open` while expanded. Expanding is inline/accordion — it never touches the right pane.
export const DataSourceFolder = ({
  folder,
  contents,
  isExpanded,
  onToggle,
  onRename,
  onDelete,
  onDeleteDataSource,
  onMoveDataSource,
  updateSelectedDatasource,
  canRename,
  canDelete,
  darkMode,
}) => {
  const { selectedDataSource } = useContext(GlobalDataSourcesContext);
  const canManageFolder = canRename || canDelete;
  const [showMenu, setShowMenu] = useState(false);
  const menuBtnRef = useRef(null);

  // The whole folder (header + contents) is a drop target, so a data source can be dropped
  // anywhere on it. `folderId` in the drop data tells the drag-end handler where it landed.
  const { setNodeRef, isOver } = useDroppable({
    id: `folder-drop:${folder.id}`,
    data: { folderId: folder.id },
  });

  const hasItems = contents.length > 0;
  const folderIcon = isExpanded ? 'folder-open' : hasItems ? 'folder-dot' : 'folder';

  const handleMenuAction = (action) => {
    setShowMenu(false);
    if (action === 'rename') onRename(folder);
    if (action === 'delete') onDelete(folder);
  };

  return (
    <div ref={setNodeRef} className={cx('datasource-folder', { 'is-drop-over': isOver })}>
      <div
        className="datasource-folder-row"
        role="button"
        onClick={onToggle}
        data-cy={`datasource-folder-${String(folder.name).toLowerCase().replace(/\s+/g, '-')}`}
      >
        <div className="datasource-folder-leading">
          <DynamicIcon name={folderIcon} size={16} style={{ color: 'var(--icon-default, #6a727c)', flexShrink: 0 }} />
          <span className="datasource-folder-name text-truncate" title={folder.name}>
            {folder.name}
          </span>
        </div>

        {canManageFolder && (
          <div
            className={`datasource-folder-menu-trigger ${showMenu ? 'is-open' : ''}`}
            onClick={(e) => e.stopPropagation()}
          >
            <Button
              ref={menuBtnRef}
              iconOnly
              onClick={(e) => {
                e.stopPropagation();
                setShowMenu((v) => !v);
              }}
              size="small"
              variant="outline"
              data-cy={`datasource-folder-menu-btn-${folder.id}`}
            >
              <EllipsisVerticalIcon color="var(--icon-strong)" size={12} />
            </Button>
          </div>
        )}
      </div>

      <Overlay
        show={showMenu}
        target={menuBtnRef.current}
        placement="bottom-start"
        rootClose
        transition={false}
        onHide={() => setShowMenu(false)}
        popperConfig={{ modifiers: [{ name: 'offset', options: { offset: [0, 4] } }] }}
      >
        {(overlayProps) => (
          <Popover
            {...overlayProps}
            id={`datasource-folder-menu-${folder.id}`}
            className={`transparent-popover ${darkMode ? 'dark-theme' : ''}`}
            onClick={(e) => e.stopPropagation()}
          >
            <div className={`datasource-folder-context-menu ${darkMode ? 'dark-theme' : ''}`}>
              {canRename && (
                <button
                  className="datasource-folder-menu-item"
                  onClick={() => handleMenuAction('rename')}
                  data-cy={`datasource-folder-rename-btn-${folder.id}`}
                >
                  <DynamicIcon name="square-pen" size={16} style={{ color: 'var(--icon-default, #6a727c)' }} />
                  Rename
                </button>
              )}
              {canDelete && (
                <button
                  className="datasource-folder-menu-item datasource-folder-menu-item--delete"
                  onClick={() => handleMenuAction('delete')}
                  data-cy={`datasource-folder-delete-btn-${folder.id}`}
                >
                  <DynamicIcon name="trash-2" size={16} style={{ color: 'var(--tomato9, #e54d2e)' }} />
                  Delete
                </button>
              )}
            </div>
          </Popover>
        )}
      </Overlay>

      {isExpanded && (
        <div className="datasource-folder-contents">
          {hasItems ? (
            contents.map((source) => (
              <DraggableDataSource key={source.id} dataSource={source} sourceFolderId={folder.id}>
                <ListItem
                  dataSource={source}
                  active={selectedDataSource?.id === source?.id}
                  onDelete={onDeleteDataSource}
                  updateSelectedDatasource={updateSelectedDatasource}
                  menuOptions={[
                    { label: 'Move folder', icon: 'folder-input', onClick: onMoveDataSource },
                    { label: 'Delete', icon: 'trash-2', danger: true, onClick: onDeleteDataSource },
                  ]}
                />
              </DraggableDataSource>
            ))
          ) : (
            <div className="datasource-folder-empty" data-cy={`datasource-folder-empty-${folder.id}`}>
              This folder is empty
            </div>
          )}
        </div>
      )}
    </div>
  );
};
import React, { useEffect, useState } from 'react';
import { toast } from 'react-hot-toast';
import Modal from '@/HomePage/Modal';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import { validateName, handleHttpErrorMessages } from '@/_helpers/utils';

// Shared create/rename modal for data-source folders. `mode` is 'create' | 'rename'.
// - Create: primary disabled while the name is empty.
// - Rename: pre-filled, primary disabled while empty OR unchanged.
// Both show a loading state on the primary button and a success toast (copy per the design).
export const FolderFormModal = ({ show, mode, folder, onClose, onCreate, onRename }) => {
  const isRename = mode === 'rename';
  const [name, setName] = useState('');
  const [errorText, setErrorText] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (show) {
      setName(isRename ? (folder?.name ?? '') : '');
      setErrorText('');
      setIsSubmitting(false);
    }
  }, [show, isRename, folder]);

  const handleChange = (e) => {
    const value = e.target.value;
    setName(value);
    // allowSpecialChars=false, allowSpaces=true, allowAllCases=true — mirrors the backend folder
    // name DTO (alphanumeric + space/hyphen, no path separators).
    const validation = validateName(value, 'Folder name', true, false, false, true, false, true);
    setErrorText(validation.status ? '' : validation.errorMsg);
  };

  const trimmedName = name.trim().replace(/\s+/g, ' ');
  const isUnchanged = isRename && trimmedName === folder?.name;
  const isDisabled = !!errorText || !trimmedName || isUnchanged || isSubmitting;

  const handleSubmit = () => {
    if (isDisabled) return;
    setIsSubmitting(true);
    const request = isRename ? onRename(trimmedName, folder.id) : onCreate(trimmedName);
    request
      .then(() => {
        toast.success(isRename ? 'Folder renamed successfully!' : 'Folder created successfully!');
        onClose();
      })
      .catch((error) => {
        handleHttpErrorMessages(error, 'folder');
        setIsSubmitting(false);
      });
  };

  const handleKeyPress = (event) => {
    if (event.key === 'Enter') handleSubmit();
  };

  return (
    <Modal show={show} closeModal={onClose} title={isRename ? 'Rename folder' : 'Create folder'}>
      <div className="row workspace-folder-modal">
        <div className="col modal-main tj-app-input">
          <label className="tw-mb-1 tj-text-xsm font-weight-500">Folder name</label>
          <input
            type="text"
            onChange={handleChange}
            className="form-control"
            placeholder="Enter folder name.."
            disabled={isSubmitting}
            value={name}
            maxLength={50}
            data-cy="datasource-folder-name-input"
            onKeyPress={handleKeyPress}
            autoFocus
          />
          <label className="tj-input-error">{errorText || ''}</label>
        </div>
      </div>
      <div className="row">
        <div className="col d-flex modal-footer-btn justify-content-end">
          <ButtonSolid variant="tertiary" onClick={onClose} data-cy="cancel-button">
            Cancel
          </ButtonSolid>
          <ButtonSolid
            onClick={handleSubmit}
            data-cy={`${isRename ? 'rename' : 'create'}-datasource-folder-button`}
            isLoading={isSubmitting}
            disabled={isDisabled}
          >
            {isRename ? 'Rename folder' : 'Create folder'}
          </ButtonSolid>
        </div>
      </div>
    </Modal>
  );
};
import React, { useEffect, useMemo, useState } from 'react';
import Select from 'react-select';
import { toast } from 'react-hot-toast';
import Modal from '@/HomePage/Modal';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import { decodeEntities } from '@/_helpers/utils';
import './dataSourceFolders.scss';

// Hide react-select's indicator separator for a cleaner single-caret look (matches the design).
const selectComponentOverrides = { IndicatorSeparator: () => null };

const getSelectClassNames = (darkMode) => ({ menuPortal: () => (darkMode ? 'dark-theme' : '') });

// "Update folder" modal (design Img 24): move one or more data sources into a target folder.
// Opened from a data source's "Move folder" menu, pre-filled with that data source; more can be
// added via the multi-select. Submitting bulk-adds/moves them (the backend auto-moves any that
// already belong to another folder).
export const MoveDataSourceModal = ({ show, initialDataSource, dataSources, folders, darkMode, onClose, onSubmit }) => {
  const [selectedDataSources, setSelectedDataSources] = useState([]);
  const [targetFolder, setTargetFolder] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dataSourceOptions = useMemo(
    () => (dataSources ?? []).map((ds) => ({ value: ds.id, label: decodeEntities(ds.name) })),
    [dataSources]
  );

  // Target folders exclude any folder that already contains ALL currently-selected data sources —
  // moving there would be a no-op, so the folder a data source already belongs to is hidden.
  const folderOptions = useMemo(() => {
    const selectedIds = selectedDataSources.map((option) => option.value);
    return (folders ?? [])
      .filter((folder) => {
        if (selectedIds.length === 0) return true;
        const memberIds = new Set((folder.folder_data_sources ?? []).map((m) => m.data_source_id));
        return !selectedIds.every((id) => memberIds.has(id));
      })
      .map((folder) => ({ value: folder.id, label: folder.name }));
  }, [folders, selectedDataSources]);

  useEffect(() => {
    if (show) {
      setSelectedDataSources(
        initialDataSource ? [{ value: initialDataSource.id, label: decodeEntities(initialDataSource.name) }] : []
      );
      setTargetFolder(null);
      setIsSubmitting(false);
    }
  }, [show, initialDataSource]);

  // If the selection changes so the chosen target is no longer a valid destination, clear it.
  useEffect(() => {
    if (targetFolder && !folderOptions.some((option) => option.value === targetFolder.value)) {
      setTargetFolder(null);
    }
  }, [folderOptions, targetFolder]);

  const isDisabled = selectedDataSources.length === 0 || !targetFolder || isSubmitting;

  const handleSubmit = () => {
    if (isDisabled) return;
    setIsSubmitting(true);
    onSubmit(
      selectedDataSources.map((option) => option.value),
      targetFolder.value
    )
      .then(() => {
        toast.success('Data sources moved successfully!');
        onClose();
      })
      .catch(({ error }) => {
        toast.error(error || 'Could not move data sources');
        setIsSubmitting(false);
      });
  };

  return (
    <Modal show={show} closeModal={onClose} title="Update folder" customClassName="move-datasource-modal">
      <div className="move-datasource-modal-body">
        <div className="move-ds-field">
          <label className="move-ds-label">Move selected data sources</label>
          <Select
            isMulti
            isClearable={false}
            classNamePrefix="move-ds-select"
            className="move-ds-select"
            components={selectComponentOverrides}
            classNames={getSelectClassNames(darkMode)}
            options={dataSourceOptions}
            value={selectedDataSources}
            onChange={(value) => setSelectedDataSources(value ?? [])}
            isDisabled={isSubmitting}
            placeholder="Select data sources.."
            menuPortalTarget={document.body}
            styles={{ menuPortal: (base) => ({ ...base, zIndex: 9999 }) }}
          />
        </div>
        <div className="move-ds-to">to</div>
        <div className="move-ds-field">
          <label className="move-ds-label">Folder name</label>
          <Select
            isClearable={false}
            classNamePrefix="move-ds-select"
            className="move-ds-select"
            components={selectComponentOverrides}
            classNames={getSelectClassNames(darkMode)}
            options={folderOptions}
            value={targetFolder}
            onChange={setTargetFolder}
            isDisabled={isSubmitting}
            placeholder="Select folder"
            menuPortalTarget={document.body}
            styles={{ menuPortal: (base) => ({ ...base, zIndex: 9999 }) }}
          />
        </div>
      </div>
      <div className="move-datasource-modal-footer">
        <ButtonSolid variant="tertiary" onClick={onClose} data-cy="cancel-button">
          Cancel
        </ButtonSolid>
        <ButtonSolid
          onClick={handleSubmit}
          data-cy="move-datasource-to-folder-button"
          isLoading={isSubmitting}
          disabled={isDisabled}
        >
          Add to folder
        </ButtonSolid>
      </div>
    </Modal>
  );
};
import React, { useContext } from 'react';
import cx from 'classnames';
import { useDraggable, useDroppable } from '@dnd-kit/core';
import { GlobalDataSourcesContext } from '../../pages/GlobalDataSourcesPage';

// Wraps a data-source row so it can be dragged into a folder (or out to the stray zone). The
// CustomPointerSensor only starts a drag from an element carrying data-draggable="true", so a
// plain click (open / delete) still works — drag only kicks in past the activation distance.
//
// Selection: shift / ⌘ / ctrl + click toggles the row in the multi-select set (for dragging many
// data sources at once) without opening it; a plain click clears the selection and opens the row.
export const DraggableDataSource = ({ dataSource, sourceFolderId = null, children }) => {
  const { selectedDataSourceIds, setSelectedDataSourceIds } = useContext(GlobalDataSourcesContext);
  const isSelected = selectedDataSourceIds.includes(dataSource.id);

  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `ds:${dataSource.id}`,
    data: { dataSource, sourceFolderId },
  });

  const handleClickCapture = (e) => {
    if (e.shiftKey || e.metaKey || e.ctrlKey) {
      // Swallow the click so the row doesn't open, and toggle selection membership.
      e.preventDefault();
      e.stopPropagation();
      setSelectedDataSourceIds((prev) =>
        prev.includes(dataSource.id) ? prev.filter((id) => id !== dataSource.id) : [...prev, dataSource.id]
      );
    } else if (selectedDataSourceIds.length) {
      // Plain click on any row drops the current selection (then the click opens the row).
      setSelectedDataSourceIds([]);
    }
  };

  return (
    <div
      ref={setNodeRef}
