// Decides which data-source folders the sidebar shows, and what each one contains, for a given
// search term. Same semantics as the query panel's folder grouping
// (AppBuilder/QueryManager/Components/dataSourceFolderGrouping.js), kept in step deliberately:
//
//   - no search term  → every folder, empty ones included, with all of its data sources;
//   - search term     → a folder survives when its own name matches OR it holds a matching data
//                       source. A name-matched folder shows all of its data sources; one that
//                       survives only on its contents shows just the matching ones. Folders left
//                       with nothing to show are dropped rather than rendered empty.
//
// `visibleDataSources` is the already search-filtered list; `dataSources` is the unfiltered one,
// needed to fill a folder that matched by name. Folders and their contents are alphabetical.
export function buildVisibleFolders({ folders, dataSources, visibleDataSources, searchValue }) {
  const term = (searchValue ?? '').toLowerCase().trim();
  const allById = new Map((dataSources ?? []).map((dataSource) => [dataSource.id, dataSource]));
  const matchingById = new Map((visibleDataSources ?? []).map((dataSource) => [dataSource.id, dataSource]));

  return (folders ?? [])
    .map((folder) => {
      const folderNameMatches = !!term && (folder.name ?? '').toLowerCase().includes(term);
      const lookup = folderNameMatches ? allById : matchingById;
      const contents = (folder.folder_data_sources ?? [])
        .map((membership) => lookup.get(membership.data_source_id))
        .filter(Boolean)
        .sort((a, b) => a.name.localeCompare(b.name));
      return { folder, contents, folderNameMatches };
    })
    .filter(({ contents, folderNameMatches }) => !term || folderNameMatches || contents.length > 0)
    .sort((a, b) => a.folder.name.localeCompare(b.folder.name));
}
import React, { useContext, useMemo } from 'react';
import { GlobalDataSourcesContext } from '../../pages/GlobalDataSourcesPage';
import { DataSourceFolder } from './DataSourceFolder';
import { buildVisibleFolders } from './folderSearch';
import './dataSourceFolders.scss';

// Renders the data-source folder rows above the stray data-source list. Pure presentation of the
// folder state held in GlobalDataSourcesContext — create/rename/delete modals live in the parent
// (List) alongside the "+" header button, and reach back via the onRename/onDelete callbacks.
export const DataSourceFolders = ({
  dataSources,
  visibleDataSources,
  searchValue,
  onDeleteDataSource,
  onMoveDataSource,
  updateSelectedDatasource,
  onRenameFolder,
  onDeleteFolder,
  darkMode,
}) => {
  const { folders, expandedFolderIds, toggleFolderExpanded, canUpdateDataSourceFolder, canDeleteDataSourceFolder } =
    useContext(GlobalDataSourcesContext);

  // Delete rides a workspace-wide flag, but a granular "Edit folder" grant can be scoped to
  // individual folders — so rename is asked per folder, at the point of render.
  const canDelete = canDeleteDataSourceFolder();

  const searchActive = (searchValue ?? '').trim().length > 0;

  // Resolve each folder's membership rows to the actual data-source objects (so a folder shows the
  // same icon/name/git-sync affordances as a stray row), and drop the folders a search has emptied.
  const foldersWithContents = useMemo(
    () => buildVisibleFolders({ folders, dataSources, visibleDataSources, searchValue }),
    [folders, dataSources, visibleDataSources, searchValue]
  );

  if (foldersWithContents.length === 0) return null;

  return (
    <div className="datasource-folders-list">
      {foldersWithContents.map(({ folder, contents }) => {
        // Auto-expand while searching so matching contents surface without a manual click.
        const isExpanded = expandedFolderIds.includes(folder.id) || (searchActive && contents.length > 0);
        return (
          <DataSourceFolder
            key={folder.id}
            folder={folder}
            contents={contents}
            isExpanded={isExpanded}
            onToggle={() => toggleFolderExpanded(folder.id)}
            onRename={onRenameFolder}
            onDelete={onDeleteFolder}
            onDeleteDataSource={onDeleteDataSource}
            onMoveDataSource={onMoveDataSource}
            updateSelectedDatasource={updateSelectedDatasource}
            canRename={canUpdateDataSourceFolder(folder)}
            canDelete={canDelete}
            darkMode={darkMode}
          />
        );
      })}
    </div>
  );
};
