                        src="assets/images/icons/back.svg"
                        width="30"
                        height="30"
                      />
                    </div>
                  )}
                  <Modal.Title className={cn('mt-3', classes?.modalTitleContainer)}>
                    {selectedDataSource && !isSampleDb ? (
