export const GlobalDataSources = ({ darkMode = false, updateSelectedDatasource }) => {
  const containerRef = useRef(null);
  const [plugins, setPlugins] = useState([]);
  const [marketplacePlugins, setMarketplacePlugins] = useState([]);
  const [filteredDataSources, setFilteredDataSources] = useState([]);
  const [queryString, setQueryString] = useState('');
  const [addingDataSource, setAddingDataSource] = useState(false);
  const [suggestingDataSource, setSuggestingDataSource] = useState(false);
  const [showSwitchBranchModal, setShowSwitchBranchModal] = useState(false);
  const [pendingAddDataSource, setPendingAddDataSource] = useState(null);
  const [pendingCreateDS, setPendingCreateDS] = useState(null);
  const loadingSeenRef = useRef(false);
  const { t } = useTranslation();
  const currentUserValue = authenticationService.currentSessionValue;
  const admin = currentUserValue?.admin;
  const superAdmin = currentUserValue?.super_admin;
  const isBuilder = !!currentUserValue?.user_permissions?.is_builder;
  const edition = String(fetchEdition() || '').toLowerCase();
  const { tooljetVersion } = useAppDataStore(
    (state) => ({
      tooljetVersion: state?.metadata?.installed_version,
    }),
    shallow
  );
  const isCloudEdition = edition === 'cloud' || checkIfToolJetCloud(tooljetVersion);
  const marketplaceEnabled = !isCloudEdition && (admin || superAdmin || isBuilder);
  const [modalProps, setModalProps] = useState({
    backdrop: false,
    dialogClassName: `datasource-edit-modal`,
    enforceFocus: false,
  });

  const {
    dataSources,
    setSelectedDataSource,
    selectedDataSource,
    fetchDataSources,
    showDataSourceManagerModal,
    toggleDataSourceManagerModal,
    handleModalVisibility,
    isEditing,
    setEditing,
    currentEnvironment,
    environments,
    featureAccess,
    setCurrentEnvironment,
    fetchDataSourceByEnvironment,
    activeDatasourceList,
    setActiveDatasourceList,
    isLoading,
    environmentLoading,
  } = useContext(GlobalDataSourcesContext);

  const { updateSidebarNAV } = useContext(BreadCrumbContext);
  const showMarketplaceBanner = marketplaceEnabled && tooljetVersion && !checkIfToolJetCloud(tooljetVersion);

  useEffect(() => {
    pluginsService
      .findAll()
      .then(({ data = [] }) => {
        setPlugins([...data].sort((a, b) => a.name.localeCompare(b.name)));
      })
      .catch((error) => {
        toast.error(error?.message || 'Failed to fetch plugins');
      });

    marketplaceService
      .findAll()
      .then(({ data = [] }) => setMarketplacePlugins([...data]))
      .catch((error) => {
        toast.error(error?.message || 'Failed to fetch plugins');
      });
  }, []);

  useEffect(() => {
    fetchAndSetWindowTitle({ page: `${selectedDataSource?.name || pageTitles.DATA_SOURCES}` });
    if (selectedDataSource) {
      setModalProps({ ...modalProps, backdrop: false });
    }

    if (!isEditing) {
      setModalProps({ ...modalProps, backdrop: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDataSource, isEditing]);

  // After branch switch + refetch, trigger the deferred add
  useEffect(() => {
    if (!pendingCreateDS) return;
    if (isLoading) {
      loadingSeenRef.current = true;
    }
    if (!isLoading && loadingSeenRef.current) {
      const ds = pendingCreateDS;
      loadingSeenRef.current = false;
      setPendingCreateDS(null);
      createDataSource(ds);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dataSources, isLoading, pendingCreateDS]);

  const handleHideModal = (ds) => {
    if (dataSources?.length) {
      if (!isEditing) {
        setEditing(true);
        setSelectedDataSource(dataSources[0]);
        updateSelectedDatasource(dataSources[0]?.name);
      } else {
        toggleDataSourceManagerModal(false);
        setEditing(true);
        setSelectedDataSource(ds);
        fetchDataSources(false, ds);
      }
    } else {
      handleModalVisibility();
      setEditing(true);
    }
  };

  const environmentChanged = (env, dataSourceId) => {
    setCurrentEnvironment(env);
    dataSourceId && fetchDataSourceByEnvironment(dataSourceId, env?.id);
  };

  const dataSourcesChanged = (resetSelection, dataSource) => {
    fetchDataSources(resetSelection, dataSource);
  };

  const handleSearch = (e) => setQueryString(e.target.value);

  const filterDataSources = (searchQuery) => {
    let arr = [];

    const filtered = datasourcesGroups().map((datasourceGroup) => {
      if (datasourceGroup.type === 'Commonly used') {
        return {
          ...datasourceGroup,
          list: [],
          renderDatasources: () => renderCardGroup([], datasourceGroup.type),
        };
      }

      datasourceGroup.list.map((dataSource) => {
        if (dataSource.name.toLowerCase().includes(searchQuery.toLowerCase())) {
          arr.push({ ...dataSource, type: datasourceGroup.type });
        }
      });
      datasourceGroup.list = [...arr];
      ((datasourceGroup.renderDatasources = () => renderCardGroup(datasourceGroup.list, datasourceGroup.type)),
        (arr = []));
      return datasourceGroup;
    });
    const filteredDsList = filtered.reduce((acc, filteredGroup) => [...acc, ...filteredGroup.list], []);
    filteredDsList.length >= 1 ? setSuggestingDataSource(false) : setSuggestingDataSource(true);
    setFilteredDataSources([...filtered]);
  };

  // Reapply URL searches on navigation, and refresh results as installed plugins arrive.
  const [searchParams] = useSearchParams();
  const urlSearch = searchParams.get('search') ?? '';
  useEffect(() => {
    setQueryString(urlSearch);
  }, [urlSearch]);

  useEffect(() => {
    filterDataSources(queryString);
    // Filtering depends on the catalogue as well as the user's current search.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [queryString, plugins, isCloudEdition]);

  const createDataSource = async (dataSource) => {
    const { currentBranch, actions } = useWorkspaceBranchesStore.getState();
    if (currentBranch) {
      try {
        const exists = await actions.checkBranchExistsOnRemote(currentBranch.name);
        if (!exists) {
          toast.error(
            'Branch does not exist in git. Delete this branch and create a new one to continue to make changes.'
          );
          return;
        }
      } catch (_err) {
        /* allow on network error */
      }
    }

    const { id } = dataSource;
    const selectedDataSource =
      dataSource.manifestFile?.data?.['tj:source'] ?? dataSource.manifestFile?.data?.source ?? dataSource;
    const name =
      dataSource.manifestFile?.data?.['tj:source']?.kind ??
      dataSource.manifestFile?.data?.source?.kind ??
      dataSource.kind;
    const options =
      dataSource?.defaults ??
      dataSource?.options ??
      dataSource?.manifestFile?.data?.defaults ??
      dataSource?.manifestFile?.data?.source?.options ??
      {};
    const pluginId = id;
    const kind = selectedDataSource?.kind;
    const scope = 'global';

    const encryptedSet = new Set(dataSource?.manifestFile?.data?.['tj:encrypted'] ?? []);
    const parsedOptions = Object.keys(options).map((key) => {
      const keyMeta = selectedDataSource?.options?.[key];
      const isEncrypted = keyMeta ? keyMeta.encrypted : encryptedSet.has(key);
      return {
        key,
        value: options[key]?.value,
        encrypted: isEncrypted,
        ...(!options[key]?.value && { credential_id: options[key]?.credential_id }),
      };
    });
    if (name.trim() !== '') {
      setAddingDataSource(true);
      globalDatasourceService
        .create({
          plugin_id: pluginId,
          name,
          kind,
          options: parsedOptions,
          scope,
        })
        .then((data) => {
          setActiveDatasourceList('');
          setAddingDataSource(false);
          toast.success(t('editor.queryManager.dataSourceManager.toast.success.dataSourceAdded', 'Data Source Added'), {
            position: 'top-center',
          });

          dataSourcesChanged(false, data);
          setAddingDataSource(false);
        })
        .catch(({ error }) => {
          setAddingDataSource(false);
          error && toast.error(error, { position: 'top-center' });
        });
    } else {
      toast.error(
        t(
          'editor.queryManager.dataSourceManager.toast.error.noEmptyDsName',
          'The name of datasource should not be empty'
        ),
        { position: 'top-center' }
      );
    }
  };

  const loadingState = () => {
    return (
      <div className="datasource-list-container">
        <div className="datasource-list">
          <div className="mb-2">
            <HeaderSkeleton />
          </div>
          <Skeleton count={1} height={20} width={120} className="mb-2" />
          {Array.from(Array(2)).map((_, rowIndex) => (
            <div className="row skeleton-container mb-3 mt-3" key={rowIndex}>
              {Array.from(Array(6)).map((_, index) => (
                <div className="col" key={rowIndex * 3 + index}>
                  {rowIndex === 1 && index > 2 ? (
                    <></>
                  ) : (
                    <Skeleton count={1} height={104} width={128} className="mb-1" />
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    );
  };

  const segregateDataSources = () => {
    const datasources = queryString && queryString.length > 0 ? filteredDataSources : datasourcesGroups();

    return (
      <div className="datasource-list-container" id="datasource-list-container">
        <div className="datasource-list">
          <div className="datasource-marketplace-banner-holder">
            <MarketplaceBanner marketplaceEnabled={marketplaceEnabled} showBanner={showMarketplaceBanner} />
          </div>
          <div className="datasource-search-holder">
            <SearchBox
              dataCy={`home-page`}
              className="border-0"
              darkMode={darkMode}
              placeholder={`Search data sources`}
              initialValue={queryString}
              width={'100%'}
              callBack={handleSearch}
              onClearCallback={() => {
                setQueryString('');
                setSuggestingDataSource(false);
              }}
            />
          </div>
          {suggestingDataSource ? (
            <center className="empty-ds-container">
              <div>
                <p className="mt-2 tj-text-lg font-weight-500 tj-text">{`No results for "${queryString}"`}</p>
              </div>
              <img src="assets/images/icons/no-results.svg" width="200" height="200" />
            </center>
          ) : (
            datasources.map((dataSource) => {
              {
                return (
                  (dataSource.list.length > 0 || (!queryString && dataSource.type === 'Plugins')) && (
                    <>
                      <div id={dataSource.key} className="tj-text-md font-weight-500 tj-text">
                        {dataSource.type}
                      </div>
                      {dataSource.renderDatasources()}
                    </>
                  )
                );
              }
            })
          )}
        </div>
      </div>
    );
  };

  const renderSidebarList = () => {
    const dataSourceList = datasourcesGroups().splice(0, 5);
    const handleOnSelect = (activekey, type) => {
      setQueryString('');
      setSuggestingDataSource(false);
      toggleDataSourceManagerModal(false);
      setActiveDatasourceList(activekey);
      updateSidebarNAV(type);
      setSelectedDataSource(null);
      setTimeout(() => {
        const container = document.getElementById('datasource-list-container'); //container to scroll
        const element = document.getElementById(activekey);

        if (container && element) {
          const offsetTop = element.offsetTop - container.offsetTop;
          container.scrollTo({
            top: offsetTop,
            behavior: 'smooth',
          });
        }
      }, 100);
    };
    return (
      <div className="tw-pt-4">
        <SegregatedList
          handleOnSelect={handleOnSelect}
          activeDatasourceList={activeDatasourceList}
          dataSources={dataSourceList}
        />
      </div>
    );
  };

  const isGitSyncConfigured = useWorkspaceBranchesStore((state) => state.isGitSyncConfigured);
  const isBranchLockedOnDefault = useWorkspaceBranchesStore((state) => {
    if (!state.isInitialized || !state.orgGitConfig) return false;
    // orgGitConfig.is_branching_enabled is the stored flag and is license-unaware — on a license
    // downgrade it stays true even though the workspace is now single-branch. isMultiBranchingEnabled
    // (from the workspace-branches list endpoint) already folds in the multi-branch license, so gate
    // on it to keep the default branch editable (no lock) when multi-branch isn't licensed.
    const isBranchingEnabled =
      (state.orgGitConfig?.is_branching_enabled || state.orgGitConfig?.isBranchingEnabled) &&
      state.isMultiBranchingEnabled !== false;
    const isDefault = state.currentBranch?.is_default || state.currentBranch?.isDefault;
    return !!(isBranchingEnabled && isDefault);
  });
  // Read the license from the authoritative license store (the context's featureAccess can be
  // stale/empty here). Git configured + expired/invalid license → the whole workspace is read-only.
  const licenseFeatureAccess = useLicenseStore((state) => state.featureAccess);
  const isGitLicenseLocked = isGitSyncConfigured && isGitSyncLicenseInvalid(licenseFeatureAccess);
  const isWorkspaceBranchLocked = isBranchLockedOnDefault || isGitLicenseLocked;

  const renderCardGroup = (source, type) => {
    const hasCreatePermission = canCreateDataSource();
    const canAddDataSource = hasCreatePermission && !isWorkspaceBranchLocked;
    const addDataSourceBtn = (item) => (
      <ToolTip
        message={!hasCreatePermission ? 'You do not have permission to add a data source' : ''}
        show={!hasCreatePermission}
        placement="bottom"
      >
        <div>
          <ButtonSolid
            // Hard-disable when the git-sync license is expired/invalid — the workspace is read-only.
            disabled={addingDataSource || !hasCreatePermission || isGitLicenseLocked}
            isLoading={addingDataSource}
            variant="secondary"
            onClick={() => {
              if (isGitLicenseLocked) return;
              if (isWorkspaceBranchLocked) {
                setPendingAddDataSource(item);
                setShowSwitchBranchModal(true);
              } else {
                createDataSource(item);
              }
            }}
            data-cy={`${item.title.toLowerCase().replace(/\s+/g, '-')}-add-button`}
          >
            <SolidIcon name="plus" fill={darkMode ? '#3E63DD' : '#3E63DD'} width={18} viewBox="0 0 25 25" />
            <span className="ml-2">Add</span>
          </ButtonSolid>
        </div>
      </ToolTip>
    );

    const datasources = source.map((datasource) => {
      const src = datasource?.iconFile?.data
        ? `data:image/svg+xml;base64,${datasource.iconFile?.data}`
        : datasource.kind.toLowerCase();

      return {
        ...datasource,
        src,
        title: datasource.name,
      };
    });

    const pluginsWithTags = marketplacePlugins.reduce((acc, plugin) => {
      const isInDatasources = datasources.some((datasource) => {
        return datasource.kind === plugin.id || datasource.pluginId === plugin.id || datasource.plugin_id === plugin.id;
      });
      if (isInDatasources && plugin.tags) {
        acc[plugin.id] = plugin.tags;
      }
      return acc;
    }, {});

    return (
      <>
        <div className="row row-deck mt-3">
          {datasources.map((item) => {
            const marketplaceTags =
              pluginsWithTags[item.kind] || pluginsWithTags[item.pluginId] || pluginsWithTags[item.plugin_id] || [];
            const manifestTags = item?.tags || [];
            const tags = [...new Set([...marketplaceTags, ...manifestTags])];
            return (
              <Card
                key={item.key}
                darkMode={darkMode}
                title={item.title}
                src={item?.src}
                usePluginIcon={isEmpty(item?.iconFile?.data)}
                height={'35px'}
                width={'35px'}
                actionButton={addDataSourceBtn(item)}
                className="datasource-card"
                cardClassName="card--clickable"
                titleClassName={'datasource-card-title'}
                tags={tags}
              />
            );
          })}
          {type === 'Plugins' && tooljetVersion && !checkIfToolJetCloud(tooljetVersion) && (
            <div style={{ height: '122px', width: '164px' }} className={`col-md-2  mb-4 `}>
              <div
                className="card add-plugin-card"
                role="button"
                onClick={() => {
                  if (marketplaceEnabled) {
                    window.open('/integrations/marketplace', '_blank');
                  } else {
                    toast.error('Please enable marketplace to add plugins');
                  }
                }}
                data-cy={`data-source-add-plugin`}
              >
                <div className="card-body">
                  <center style={{ paddingTop: '5px', marginTop: '20px' }}>
                    <SolidIcon
                      name="plus"
                      fill={'var(--icon-default)'}
                      width={35}
                      height={35}
                      style={{ marginBottom: '8px' }}
                    />
                    <br></br>
                    <span className={`datasource-card-title add-plugin-card-title`}>Add plugin</span>
                  </center>
                </div>
              </div>
            </div>
          )}
        </div>
      </>
    );
  };

  const datasourcesGroups = () => {
    const allDataSourcesList = {
      common: getCommonlyUsedDataSources(plugins),
      databases: DataBaseSources,
      apis: ApiSources,
      cloudStorages: CloudStorageSources,
      ais: AiSources,
      plugins: plugins,
      filteredDatasources: filteredDataSources,
    };

    const pluginGroups = plugins.reduce((acc, plugin) => {
      const groupLabel = getDataSourceGroupLabel(plugin);
      if (!acc[groupLabel]) {
        acc[groupLabel] = [];
      }
      acc[groupLabel].push(plugin);
      return acc;
    }, {});

    const sortByName = (list) => [...list].sort((a, b) => (a.name || '').localeCompare(b.name || ''));

    const databasesList = sortByName([...allDataSourcesList.databases, ...(pluginGroups.Databases || [])]);
    const apisList = sortByName([...allDataSourcesList.apis, ...(pluginGroups.APIs || [])]);
    const cloudStoragesList = sortByName([
      ...allDataSourcesList.cloudStorages,
      ...(pluginGroups['Cloud Storages'] || []),
    ]);
    const aiList = sortByName([...allDataSourcesList.ais, ...(pluginGroups.AI || [])]);
    const pluginsList = sortByName(pluginGroups.Plugins || []);

    const dataSourceList = [
      {
        type: 'Commonly used',
        key: '#commonlyused',
        list: allDataSourcesList.common,
        renderDatasources: () => renderCardGroup(allDataSourcesList.common, 'Commonly used'),
      },
      {
        type: 'Databases',
        key: '#databases',
        list: databasesList,
        renderDatasources: () => renderCardGroup(databasesList, 'Databases'),
      },
      {
        type: 'APIs',
        key: '#apis',
        list: apisList,
        renderDatasources: () => renderCardGroup(apisList, 'APIs'),
      },
      {
        type: 'Cloud Storages',
        key: '#cloudstorage',
        list: cloudStoragesList,
        renderDatasources: () => renderCardGroup(cloudStoragesList, 'Cloud Storages'),
      },
      {
        type: 'AI',
        key: '#ai',
        list: aiList,
        renderDatasources: () => renderCardGroup(aiList, 'AI'),
      },
      ...(!isCloudEdition
        ? [
            {
              type: 'Plugins',
              key: '#plugins',
              list: pluginsList,
              renderDatasources: () => renderCardGroup(pluginsList, 'Plugins'),
            },
          ]
        : []),
    ];

    return dataSourceList;
  };

  return (
    <div className="row gx-0">
      <Sidebar renderSidebarList={renderSidebarList} updateSelectedDatasource={updateSelectedDatasource} />
      <div ref={containerRef} className={cx('col animation-fade datasource-modal-container', {})}>
        <WorkspaceLockedBanner pageContext="data sources" />
        {containerRef && containerRef?.current && selectedDataSource && (
          <DataSourceManager
            showBackButton={selectedDataSource ? false : true}
            showDataSourceManagerModal={showDataSourceManagerModal}
            darkMode={darkMode}
            hideModal={handleHideModal}
            scope="global"
            dataSourcesChanged={dataSourcesChanged}
            selectedDataSource={selectedDataSource}
            modalProps={modalProps}
            currentEnvironment={currentEnvironment}
            environments={environments}
            featureAccess={featureAccess}
            environmentChanged={environmentChanged}
            container={selectedDataSource ? containerRef?.current : null}
            isEditing={isEditing}
            updateSelectedDatasource={updateSelectedDatasource}
            showSaveBtn={canCreateDataSource() || canUpdateDataSource(selectedDataSource?.id) || canDeleteDataSource()}
            isWorkspaceBranchLocked={isWorkspaceBranchLocked}
            environmentLoading={environmentLoading}
          />
        )}
        {isLoading && loadingState()}
        {!selectedDataSource && activeDatasourceList && !isLoading && segregateDataSources()}
      </div>
      {showSwitchBranchModal && (
        <WorkspaceSwitchBranchModal
          show={showSwitchBranchModal}
          onClose={() => {
            setShowSwitchBranchModal(false);
            setPendingAddDataSource(null);
          }}
          onBranchSwitch={() => {
            if (pendingAddDataSource) {
              loadingSeenRef.current = false;
              setPendingCreateDS(pendingAddDataSource);
              setPendingAddDataSource(null);
            }
            setShowSwitchBranchModal(false);
          }}
        />
      )}
    </div>
  );
};
const CATEGORY_BY_TYPE = {
  database: 'Databases',
  api: 'APIs',
  ai: 'AI',
  'cloud-storage': 'Cloud Storages',
};

const getManifestData = (datasource) => {
  const manifestData = datasource?.manifestFile?.data;
  if (!manifestData) return {};

  return manifestData;
};

export const getDataSourceCategory = (datasource) => {
  const manifestData = getManifestData(datasource);
  const sourceMetadata = manifestData['tj:source'] || manifestData.source || {};
  const manifestType = sourceMetadata?.type || manifestData?.type;

  if (!manifestType || manifestType === 'object') return null;

  return Object.prototype.hasOwnProperty.call(CATEGORY_BY_TYPE, manifestType) ? manifestType : null;
};

export const getDataSourceGroupLabel = (datasource) => {
  const category = getDataSourceCategory(datasource);
  if (!category) return 'Plugins';

  return CATEGORY_BY_TYPE[category];
};
import React, { useContext, useRef, useState } from 'react';
import cx from 'classnames';
import { useNavigate } from 'react-router-dom';
import { Overlay, Popover } from 'react-bootstrap';
import { DynamicIcon } from 'lucide-react/dynamic.mjs';
import { EllipsisVerticalIcon } from 'lucide-react';
import { Button } from '@/components/ui/Button/Button';
import { GlobalDataSourcesContext } from '../../pages/GlobalDataSourcesPage';
import { DataSourceTypes } from '../../../common/components/DataSourceComponents';
import { getSvgIcon } from '@/_helpers/appUtils';
import useGlobalDatasourceUnsavedChanges from '@/_hooks/useGlobalDatasourceUnsavedChanges';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import { ToolTip } from '@/_components';
import { DATA_SOURCE_TYPE } from '@/_helpers/constants';
import { decodeEntities, getWorkspaceId } from '@/_helpers/utils';
import { appendBranchName } from '@/_helpers/active-branch';
import { useWorkspaceBranchesStore } from '@/_stores/workspaceBranchesStore';
import { useLicenseStore } from '@/_stores/licenseStore';
import { isGitSyncLicenseInvalid } from '@/_helpers/gitSyncLicense';
import { PushAppsModal } from '@ee/modules/Appbuilder/components/GitSyncManager/PushAppsModal';

const DUMMY_DS_LABEL = 'Undefined data source';
const buildDummyDsTooltip = (coRelationId) =>
  coRelationId
    ? `Data source #${coRelationId} is missing, pull from git to resolve this`
    : 'Data source is missing, pull from git to resolve this';

export const ListItem = ({
  dataSource,
  key,
  active,
  onDelete,
  updateSelectedDatasource,
  toolTipText,
  disableDelButton = false,
  // When provided, the row's right slot shows a "⋮" menu (e.g. Move folder / Delete) instead of
  // the bare delete button. Each option: { label, icon, danger?, onClick(dataSource) }.
  menuOptions,
}) => {
  const {
    setSelectedDataSource,
    toggleDataSourceManagerModal,
    environments,
    setCurrentEnvironment,
    setActiveDatasourceList,
    canDeleteDataSource,
  } = useContext(GlobalDataSourcesContext);
  const { handleActions } = useGlobalDatasourceUnsavedChanges();
  const navigate = useNavigate();
  const workspaceId = getWorkspaceId();
  const [syncIconHovered, setSyncIconHovered] = useState(false);
  const [rowHovered, setRowHovered] = useState(false);
  const [pushModalOpen, setPushModalOpen] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const darkMode = localStorage.getItem('darkMode') === 'true';
  const menuBtnRef = useRef(null);
  const hasMenu = menuOptions?.length > 0;
  const wsCurrentBranch = useWorkspaceBranchesStore((state) => state.currentBranch);
  const isGitSyncConfigured = useWorkspaceBranchesStore((state) => state.isGitSyncConfigured);
  const featureAccess = useLicenseStore((state) => state.featureAccess);
  // Git configured but the license is expired/invalid → data sources are read-only: can't open or
  // delete them (the add button is disabled in GlobalDataSources).
  const isGitLicenseLocked = isGitSyncConfigured && isGitSyncLicenseInvalid(featureAccess);
  const isSampleDb = dataSource.type == DATA_SOURCE_TYPE.SAMPLE;
  const isOnDefaultBranch = !!(wsCurrentBranch?.is_default || wsCurrentBranch?.isDefault);
  const isUnsynced =
    isGitSyncConfigured &&
    wsCurrentBranch &&
    isOnDefaultBranch &&
    (dataSource?.is_synced === false || dataSource?.isSynced === false);

  const getSourceMetaData = (dataSource) => {
    if (dataSource.pluginId) {
      return dataSource.plugin?.manifestFile?.data.source;
    }

    return DataSourceTypes.find((source) => source?.kind === dataSource?.kind);
  };

  const sourceMeta = getSourceMetaData(dataSource);

  // sourceMeta would be missing on development setup when switching between branches
  // if ds is already in branch while not available in another
  const icon =
    dataSource.type === DATA_SOURCE_TYPE.SAMPLE ? (
      <img src="assets/images/tj-logo.svg" style={{ padding: '0px' }} />
    ) : (
      getSvgIcon(sourceMeta?.kind?.toLowerCase(), 24, 24, dataSource?.plugin?.iconFile?.data)
    );

  const focusModal = () => {
    const element = document.getElementsByClassName('form-control-plaintext form-control-plaintext-sm')[0];
    element?.focus();
  };

  const selectDataSource = () => {
    setActiveDatasourceList('');
    setSelectedDataSource(dataSource);
    setCurrentEnvironment(environments[0]);
    toggleDataSourceManagerModal(true);
    focusModal();
    updateSelectedDatasource(dataSource?.name);
    navigate(appendBranchName(`/${workspaceId}/data-sources/${dataSource.id}`), { replace: true });
  };

  //const isSampleDb = dataSource.type == DATA_SOURCE_TYPE.SAMPLE;
  const showDeleteButton = !isSampleDb && canDeleteDataSource();

  return (
    <>
      <ToolTip
        placement="right"
        show={toolTipText ? true : false}
        message={'Sample data source\ncannot be deleted'}
        tooltipClassName="tooltip-sampl-db"
      >
        <div
          key={key}
          className={cx('mx-3 rounded-3 datasources-list', {
            'datasources-list-item': active,
          })}
          onMouseEnter={() => setRowHovered(true)}
          onMouseLeave={() => setRowHovered(false)}
        >
          <div
            role="button"
            onClick={() => {
              if (isGitLicenseLocked) return;
              handleActions(selectDataSource);
            }}
            className="col d-flex align-items-center overflow-hidden"
            style={isGitLicenseLocked ? { cursor: 'not-allowed', opacity: 0.6 } : undefined}
            data-cy={`${String(dataSource.name).toLowerCase().replace(/\s+/g, '-')}-button`}
          >
            <div className="ds-svg-container">{icon}</div>

            <div
              className="font-400 tj-text-xsm text-truncate tw-flex tw-items-center tw-gap-1"
              style={{ paddingLeft: '6px' }}
            >
              {dataSource.is_dummy ? DUMMY_DS_LABEL : decodeEntities(dataSource.name)}
              {dataSource.is_dummy && (
                <ToolTip placement="right" message={buildDummyDsTooltip(dataSource.co_relation_id)}>
                  <span className="tw-inline-flex tw-items-center" data-cy="dummy-ds-warning-icon">
                    <SolidIcon name="warning" width="14" fill="var(--icon-warning)" />
                  </span>
                </ToolTip>
              )}
              {isSampleDb && (
                <div
                  className="font-400 tj-text-xxsm text-truncate"
                  style={{ paddingTop: '3px', paddingLeft: '2px', color: '#687076' }}
                >{`(postgres)`}</div>
              )}
            </div>
          </div>
          {/* On hover: refresh icon appears to the left of the delete button */}
          {isUnsynced && rowHovered && (
            <div className="col-auto">
              <ToolTip message="Click to push datasource to git" placement="top">
                <div
                  onMouseEnter={() => setSyncIconHovered(true)}
                  onMouseLeave={() => setSyncIconHovered(false)}
                  onClick={() => setPushModalOpen(true)}
                  style={{
                    width: '24px',
                    height: '24px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    borderRadius: '4px',
                    backgroundColor: syncIconHovered ? '#FFEEF0' : 'transparent',
                    transition: 'background-color 0.15s',
                    cursor: 'pointer',
                  }}
                  data-cy="ds-unsynced-badge"
                >
                  <SolidIcon name="refresh" width="14" fill="#E54D2E" />
                </div>
              </ToolTip>
            </div>
          )}
          {/* Right slot: refresh icon when not hovering (unsynced), delete button when hovering */}
          {isUnsynced && !rowHovered ? (
            <div className="col-auto">
              <ToolTip message="Datasource not synced in remote git" placement="top">
                <div
                  onClick={() => setPushModalOpen(true)}
                  style={{
                    width: '24px',
                    height: '24px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    borderRadius: '4px',
                    cursor: 'pointer',
                  }}
                  data-cy="ds-unsynced-badge-idle"
                >
                  <SolidIcon name="refresh" width="14" fill="#E54D2E" />
                </div>
              </ToolTip>
            </div>
          ) : hasMenu ? (
            <div
              className={cx('col-auto datasource-row-menu-trigger', { 'is-open': showMenu })}
              onClick={(e) => e.stopPropagation()}
            >
              <Button
                ref={menuBtnRef}
                iconOnly
                size="small"
                variant="outline"
                onClick={(e) => {
                  e.stopPropagation();
                  if (isGitLicenseLocked) return;
                  setShowMenu((v) => !v);
                }}
                data-cy={`${String(dataSource.name).toLowerCase().replace(/\s+/g, '-')}-menu-btn`}
              >
                <EllipsisVerticalIcon color="var(--icon-strong)" size={12} />
              </Button>
            </div>
          ) : (
            showDeleteButton && (
              <div className="col-auto">
                <button
                  title={'Delete'}
                  disabled={disableDelButton || isGitLicenseLocked}
                  className="ds-delete-btn"
                  onClick={() => {
                    if (isGitLicenseLocked) return;
                    onDelete(dataSource);
                  }}
                  data-cy={`${String(dataSource.name).toLowerCase().replace(/\s+/g, '-')}-delete-button`}
                >
                  <div>
                    <SolidIcon
                      width="14"
                      height="14"
                      name="delete"
                      fill={disableDelButton || isGitLicenseLocked ? '#E6E8EB' : '#E54D2E'}
                      className={disableDelButton || isGitLicenseLocked ? 'disabled-button' : ''}
                    />
                  </div>
                </button>
              </div>
            )
          )}
        </div>
      </ToolTip>
      {hasMenu && (
        <Overlay
          show={showMenu}
          target={menuBtnRef.current}
          placement="bottom-start"
          rootClose
          transition={false}
          onHide={() => setShowMenu(false)}
          popperConfig={{ modifiers: [{ name: 'offset', options: { offset: [0, 4] } }] }}
        >
          {(overlayProps) => (
            <Popover
              {...overlayProps}
              id={`datasource-row-menu-${dataSource.id}`}
              className={cx('transparent-popover', { 'dark-theme': darkMode })}
              onClick={(e) => e.stopPropagation()}
            >
              <div className={cx('datasource-folder-context-menu', { 'dark-theme': darkMode })}>
                {menuOptions.map((option) => (
                  <button
                    key={option.label}
                    className={cx('datasource-folder-menu-item', {
                      'datasource-folder-menu-item--delete': option.danger,
                    })}
                    onClick={() => {
                      setShowMenu(false);
                      option.onClick(dataSource);
                    }}
                    data-cy={`${String(dataSource.name).toLowerCase().replace(/\s+/g, '-')}-${String(option.label)
                      .toLowerCase()
                      .replace(/\s+/g, '-')}-menu-item`}
                  >
                    {option.icon && (
                      <DynamicIcon
                        name={option.icon}
                        size={16}
                        style={{ color: option.danger ? 'var(--tomato9, #e54d2e)' : 'var(--icon-default, #6a727c)' }}
                      />
                    )}
                    {option.label}
                  </button>
                ))}
              </div>
            </Popover>
          )}
        </Overlay>
      )}
      {PushAppsModal && isUnsynced && (
        <PushAppsModal
          show={pushModalOpen}
          onClose={() => setPushModalOpen(false)}
          resourceType="datasource"
          resourceName={dataSource.name}
          onSuccess={() => setPushModalOpen(false)}
        />
      )}
    </>
  );
};
