        fill="url(#paint0_linear_1488_148)"
      />
    </g>
    <defs>
      <linearGradient
        id="paint0_linear_1488_148"
        x1="1.99979"
        y1="1.00128"
        x2="17.4998"
        y2="17.5013"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor="#FC5F70" />
        <stop offset="1" stopColor="#8E4EC6" />
      </linearGradient>
      <clipPath id="clip0_1488_148">
        <rect width="14" height="14" fill="white" />
