const WorkspaceInvitationPage = (props) => {
  const [isLoading, setisLoading] = React.useState(false);
  const [linkExpired, setLinkExpired] = React.useState(false);
  const [expiredOrgSlug, setExpiredOrgSlug] = React.useState(null);
  const defaultState = checkWhiteLabelsDefaultState();
  const whiteLabelText = retrieveWhiteLabelText();
  const userName = props.name || '';
  const userEmail = props.email || 'abc@gmail.com';
  const invitedOrganizationName = props.invitedOrganizationName || `Tooljet's workspace`;

  // TODO: handle from the cloud
  const organizationId = new URLSearchParams(props?.location?.search).get('oid');
  useEnterKeyPress(() => acceptInvite());

  useEffect(() => {
    authenticationService.deleteLoginOrganizationId();
    setFaviconAndTitle(props?.location);
  }, []);

  const formAreaStyles = {
    marginTop: '40px',
  };
  const acceptInvite = (e) => {
    e?.preventDefault();
    const parts = props.location.pathname.split('/');
    const token = parts[2];
    setisLoading(true);
    appService
      .acceptInvite({
        token,
      })
      .then((data) => {
        toast.success(`Added to the workspace successfully.`);
        updateCurrentSession({
          isUserLoggingIn: true,
        });
        onLoginSuccess(data, props.navigate);
      })
      .catch((errorObj) => {
        if (errorObj?.data?.statusCode === 410) {
          const orgSlug = errorObj?.data?.organizationSlug || null;
          // Prevent auto-authorization on login page and prevent /error/no-active-workspace
          // redirect when useSessionManagement fires on AuthRoute mount (Sign-in click)
          updateCurrentSession({ authentication_status: false, noWorkspaceAttachedInTheSession: false });
          setExpiredOrgSlug(orgSlug);
          setLinkExpired(true);
        } else if (errorObj?.error && errorObj.error.includes('reached the number of workspaces')) {
          // Handled globally by the WorkspaceLimitModal in handle-response.js
        } else {
          toast.error('Error while setting up your account.', { position: 'top-center' });
        }
        setisLoading(false);
      });
  };

  const LeftSideComponent = () => {
    return (
      <OnboardingUIWrapper>
        <div className="onboarding-form-width">
          <FormHeader>{`Join ${invitedOrganizationName}`}</FormHeader>
          <FormDescription>{`You are invited to ${
            invitedOrganizationName
              ? `a workspace ${invitedOrganizationName}. Accept the invite to join the workspace.`
              : whiteLabelText
          }`}</FormDescription>
          <form className="form-input-area" style={formAreaStyles}>
            <FormTextInput
              label="Name"
              value={userName}
              disabled={true}
              name="name"
              dataCy="name-input"
              readOnly="true"
            />
            <FormTextInput
              label="Email"
              value={userEmail}
              disabled={true}
              readOnly="true"
              name="email"
              dataCy="email-input"
            />
            <SubmitButton
              onClick={(e) => acceptInvite(e)}
              className="accept-invite-button"
              buttonText="Accept Invite"
              isLoading={isLoading}
            />
          </form>
          {defaultState && <TermsAndPrivacyInfo />}
        </div>
      </OnboardingUIWrapper>
    );
  };
  if (linkExpired) {
    return (
      <OnboardingBackgroundWrapper
        MiddleComponent={() => <LinkExpiredCard variant="invite" organizationSlug={expiredOrgSlug} />}
      />
    );
  }

  return (
    <OnboardingBackgroundWrapper
      className="feature-graphic-layout"
      LeftSideComponent={LeftSideComponent}
      RightSideComponent={FeatureGraphicRightPanel}
    />
  );
};

