import { Decoration, DecorationSet, EditorView, ViewPlugin, ViewUpdate } from '@codemirror/view';
import { RangeSetBuilder, StateEffect } from '@codemirror/state';
import useStore from '@/AppBuilder/_stores/store';
import type { CodeSearchState } from '@/AppBuilder/_stores/slices/codeSearchSlice';
import { buildMatcher, MIN_TERM_LENGTH } from '@/AppBuilder/LeftSidebar/CodeSearch/searchRecords';
import { editorHoldsField, landInEditor } from '@/AppBuilder/LeftSidebar/CodeSearch/highlightMatch';

// Marks every match of the code search term in this editor while the Code search panel is open,
// so a jump lands on a field whose matches are all visible at a glance. Also selects a clicked
// result's match when this editor shows that field (the store's focus request).
const matchMark = Decoration.mark({ class: 'tj-code-search-match' });
const refresh = StateEffect.define<null>();

// The store fields this plugin reads.
type HighlightState = CodeSearchState & { isSidebarOpen: boolean; selectedSidebarItem: string };

const activeMatcher = (state: HighlightState): RegExp | null => {
  const { term, options } = state.codeSearch;
  const panelOpen = state.isSidebarOpen && state.selectedSidebarItem === 'search';
  if (!panelOpen || !term || term.length < MIN_TERM_LENGTH) return null;
  // Highlighting runs on the main thread, where a backtracking regex (`(a+)+$`) would freeze the
  // editor; regex matching only runs in the code-search worker, which can be terminated.
  if (options.regex) return null;
  return buildMatcher(term, options).matcher || null;
};

const buildDecorations = (view: EditorView, matcher: RegExp | null): DecorationSet => {
  const builder = new RangeSetBuilder<Decoration>();
  if (!matcher) return builder.finish();
  for (const { from, to } of view.visibleRanges) {
    const text = view.state.sliceDoc(from, to);
    matcher.lastIndex = 0;
    let hit;
    while ((hit = matcher.exec(text)) !== null) {
      if (hit[0] === '') {
        matcher.lastIndex++;
        continue;
      }
      builder.add(from + hit.index, from + hit.index + hit[0].length, matchMark);
    }
  }
  return builder.finish();
};

// Read when it runs, not when it was scheduled: the first editor holding the field takes and clears
// the request, so a second one showing the same field leaves it.
const takeFocus = (view: EditorView) => {
  const { codeSearch, consumeCodeSearchFocus } = useStore.getState();
  const { focusRequest } = codeSearch;
  if (!focusRequest || !view.dom.isConnected || !editorHoldsField(view, focusRequest)) return;
  consumeCodeSearchFocus(focusRequest.nonce);
  landInEditor(view, focusRequest);
};

// On a microtask, after the store update that scheduled it has reached every editor. A promise job,
// not queueMicrotask, so test clocks that fake timers leave it running.
const deferTakeFocus = (view: EditorView) => void Promise.resolve().then(() => takeFocus(view));

// One store subscription per mounted editor (tens in the Inspector); a single shared subscription
// would scale better if editor counts grow large.
export const codeSearchHighlight = ViewPlugin.fromClass(
  class {
    matcher: RegExp | null;
    decorations: DecorationSet;
    unsubscribe: () => void;

    constructor(view: EditorView) {
      this.matcher = activeMatcher(useStore.getState());
      this.decorations = buildDecorations(view, this.matcher);
      // A request left before this editor mounted (its tab or panel was still opening).
      deferTakeFocus(view);
      this.unsubscribe = useStore.subscribe((state: HighlightState, previous: HighlightState) => {
        const { focusRequest } = state.codeSearch;
        if (focusRequest && focusRequest !== previous.codeSearch.focusRequest) deferTakeFocus(view);
        // Only what the matcher reads: result clicks also update codeSearch (reveal requests).
        const changed =
          state.codeSearch.term !== previous.codeSearch.term ||
          state.codeSearch.options !== previous.codeSearch.options ||
          state.isSidebarOpen !== previous.isSidebarOpen ||
          state.selectedSidebarItem !== previous.selectedSidebarItem;
        if (!changed) return;
        this.matcher = activeMatcher(state);
        // Defer: the store can update while another editor is mid-dispatch.
        queueMicrotask(() => view.dom.isConnected && view.dispatch({ effects: refresh.of(null) }));
      });
    }

    update(update: ViewUpdate) {
      const refreshed = update.transactions.some((tr) => tr.effects.some((effect) => effect.is(refresh)));
      if (refreshed || update.docChanged || update.viewportChanged) {
        this.decorations = buildDecorations(update.view, this.matcher);
      }
    }

    destroy() {
      this.unsubscribe();
    }
  },
  { decorations: (plugin) => plugin.decorations }
);
// Flattens the saved app definition into one searchable row per text field.
// Pure: no store access, so it can move into a Web Worker unchanged. Reads the saved definition
// only — never resolved state — so `{{secrets.x}}` is indexed as written, never as its value.

export type EntityType = 'component' | 'query' | 'event' | 'page' | 'app';

// One thing navigation asks the editor to open; see useCodeSearchReveal.
export interface RevealStep {
  kind:
    | 'listItem'
    | 'page'
    | 'queryTab'
    | 'queryParam'
    | 'restTab'
    | 'popoverTab'
    | 'event'
    | 'preloadedScript'
    | 'inspectorTab'; // Properties / Styles of a component or page settings; added by navigation
  ownerId: string | null;
  itemId: string;
}

// The saved app definition is untyped store data; it is read defensively throughout.
type Saved = any;

interface RecordBase {
  entityType: EntityType;
  entityId: string;
  entityName: string;
  entitySubtype?: string;
  componentType?: string;
  pageId?: string | null;
  query?: Saved;
  // Events: the component / query / page that owns the handler.
  ownerType?: EntityType;
  ownerId?: string;
  eventId?: string;
  reveal?: RevealStep[];
}

export interface SearchRecord extends RecordBase {
  fieldPath: string[];
  fieldLabel: string;
  shortLabel: string;
  text: string;
}

type Labels = { displayName?: string } & Record<string, Record<string, { displayName: string }> | string | undefined>;

export interface PlainDefs {
  widgetDefs: Record<string, Labels | undefined>;
  actionDefs: { id: string; name: string }[];
  pageSettingsDef: Labels | undefined;
}

// Definitions are read defensively, so raw widget configs work as well as their plain labels.
export interface SearchInput {
  widgetDefs?: Record<string, Saved>;
  actionDefs?: PlainDefs['actionDefs'];
  pageSettingsDef?: Saved;
  pages?: Saved[];
  queries?: Saved[];
  events?: Saved[];
  globalSettings?: Saved;
  pageSettings?: Saved;
  translate?: (text: string) => string;
}

const COMPONENT_SECTIONS = ['properties', 'styles', 'general', 'generalStyles', 'validation', 'others'];
const SECTION_LABELS: Record<string, string> = {
  properties: 'Properties',
  styles: 'Styles',
  general: 'Properties',
  generalStyles: 'Styles',
  validation: 'Validation',
  others: 'Others',
};
// Keys that never hold user-authored text; indexing them only adds noise (ids, grid coordinates).
const SKIP_KEYS = new Set(['layouts', 'id', 'createdAt', 'updatedAt', 'parent', 'fxActive', 'isDefault']);
// Page keys indexed elsewhere (name, handle, components) or that are internal bookkeeping.
const PAGE_SKIP_KEYS = new Set([
  'components',
  'name',
  'handle',
  'appId',
  'pageGroupId',
  'index',
  'permissions',
  'isPageGroup',
]);
// Global settings indexed with their own labels below (preloaded JS, libraries) or not app code at
// all (theme: the workspace design-system palette, dozens of colors that would drown real matches).
const GLOBAL_SETTINGS_SKIP_KEYS = new Set(['preloadedScript', 'libraries', 'theme']);
const BARE_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// `onRowClicked` → `On row clicked`, `url_params` → `Url params` (sentence case, like the Inspector).
const humanize = (key: string): string =>
  String(key)
    .replace(/[_-]+/g, ' ')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .toLowerCase()
    .replace(/^./, (c) => c.toUpperCase());

// Calls visit(path, value) for every string/number/boolean leaf under `value`.
const walkLeaves = (value: Saved, path: string[], visit: (path: string[], text: string) => void): void => {
  if (value === null || value === undefined) return;
  if (typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (SKIP_KEYS.has(key)) continue;
      walkLeaves(child, [...path, key], visit);
    }
    return;
  }
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const text = String(value);
    if (text !== '') visit(path, text);
  }
};

// Trigger names for events that don't come from a widget config (query and page handlers).
const NON_WIDGET_EVENT_NAMES: Record<string, string> = {
  onDataQuerySuccess: 'Query Success',
  onDataQueryFailure: 'Query Failure',
  onPageLoad: 'On page load',
};
// Ids are indexed by their display names (Event, Action) below. `component` is the owner's widget
// type, written at creation with no control in the popover.
const EVENT_SKIP_KEYS = new Set(['eventId', 'actionId', 'component']);
// Action params store ids under `queryId`, `componentId`, …; the card labels them `Query`, `Component`.
const stripIdSuffix = (key: string) => String(key).replace(/(.)Id$/, '$1');

// `properties.data.value` is stored as `{ data: { value } }`; the field is `data`. A list item's own
// `value` (`options[0].value`) is a real field, not that wrapper, so it stays.
const stripValueKey = (path: string[]) =>
  path[path.length - 1] === 'value' && !/^\d+$/.test(path[path.length - 2]) ? path.slice(0, -1) : path;

const STYLE_SECTIONS = new Set(['styles', 'generalStyles']);

// Fields the Inspector swaps on a toggle: on → the dynamic code field, off → the static list. Only
// the shown one is indexed, so a column never matches twice (as list rows and as default code).
// Option widgets share one toggle (`advanced`, "Dynamic options").
const dynamicOptions = { toggle: 'advanced', dynamic: 'schema', list: 'options' };
const DYNAMIC_LIST_TOGGLES: Record<string, { toggle: string; dynamic: string; list: string }> = {
  Table: { toggle: 'useDynamicColumn', dynamic: 'columnData', list: 'columns' },
  KeyValuePair: { toggle: 'useDynamicField', dynamic: 'fieldDynamicData', list: 'fields' },
  Tags: { ...dynamicOptions, dynamic: 'data' },
  Steps: { ...dynamicOptions, list: 'steps' },
  DropdownV2: dynamicOptions,
  MultiselectV2: dynamicOptions,
  RadioButtonV2: dynamicOptions,
  TagsInput: dynamicOptions,
  ButtonGroupV2: dynamicOptions,
  PopoverMenu: dynamicOptions,
  ReorderableList: dynamicOptions,
};
// A toggle bound to an expression can't be resolved here; both fields stay indexed then.
const toggleState = (value: Saved): boolean | undefined => {
  if (value === undefined || value === false || /^\{\{\s*false\s*\}\}$/.test(String(value))) return false;
  if (value === true || /^\{\{\s*true\s*\}\}$/.test(String(value))) return true;
  return undefined;
};
const hiddenPropertyOf = (type: string, properties: Saved): string | undefined => {
  const swap = DYNAMIC_LIST_TOGGLES[type];
  if (!swap) return undefined;
  const on = toggleState(properties?.[swap.toggle]?.value);
  return on === undefined ? undefined : on ? swap.list : swap.dynamic;
};

// Short name for a nested settings path: `Page header · Height` rather than five `Page header` rows.
const pathShortLabel = (fieldPath: string[]) =>
  fieldPath.length > 1
    ? `${humanize(fieldPath[0])} · ${humanize(fieldPath[fieldPath.length - 1])}`
    : humanize(fieldPath[0]);

// A key-value row (REST headers, params, cookies, body) is stored as `[key, value]`.
const isKeyValuePair = (item: Saved): boolean =>
  Array.isArray(item) && item.length === 2 && typeof item[0] === 'string';

// A list item's own name (`email` column, `Submit` action, `page` header), or its position when it has none.
const itemName = (item: Saved, index: string): string =>
  [isKeyValuePair(item) ? item[0] : undefined, item?.name, item?.label, item?.title, item?.key, item?.buttonText].find(
    (v) => typeof v === 'string' && v.trim()
  ) ?? `#${Number(index) + 1}`;

// How a list editor finds one of its items: by id, else by the value / title / name it is keyed on,
// else (a Form's field) by the component it renders.
const itemIdentity = (item: Saved): string | undefined => {
  if (!item || typeof item !== 'object') return undefined;
  const identity = [item.id, item.value, item.title, item.name, item.componentId].find((v) => v != null && v !== '');
  return identity === undefined ? undefined : String(identity);
};

// Readable rest of a field path: drops the `value` wrapper and names list items instead of
// numbering them (`Table Columns › email › Name`, not `› Value › 3 › Name`). Also returns the
// identity of each list item on the way down, outermost first, so navigation can open them.
const readableRest = (savedField: Saved, rest: string[], { valueWrapper = true } = {}) => {
  const parts: string[] = [];
  const itemIds: string[] = [];
  let node = savedField;
  rest.forEach((key, i) => {
    const parent = node;
    node = parent?.[key];
    if (isKeyValuePair(parent)) {
      parts.push(String(key) === '0' ? 'Key' : 'Value');
    } else if (Array.isArray(parent)) {
      parts.push(itemName(node, key));
      const identity = itemIdentity(node);
      if (identity !== undefined) itemIds.push(identity);
    } else if (!(valueWrapper && i === 0 && key === 'value')) {
      parts.push(humanize(key));
    }
  });
  return { parts, itemIds };
};

// Full path for the tooltip, short name for the result row (`Disable`, `Style · Box shadow`).
const componentFieldLabels = (widgetDef: Saved, section: string, fieldPath: string[], saved: Saved) => {
  const key = fieldPath[0];
  const name = widgetDef?.[section]?.[key]?.displayName?.trim() || humanize(key);
  const { parts, itemIds } = readableRest(saved?.[key], fieldPath.slice(1));
  const field = [STYLE_SECTIONS.has(section) ? `Style · ${name}` : name, ...parts].join(' › ');
  return {
    full: [SECTION_LABELS[section], name, ...parts].join(' › '),
    short: field,
    itemIds,
  };
};

// Query options shown outside the Setup tab (QueryManagerBody renders only the active tab).
const TRANSFORMATION_OPTIONS = new Set([
  'transformation',
  'transformations',
  'transformationLanguage',
  'enableTransformation',
]);
const SETTINGS_OPTIONS = new Set([
  'runOnPageLoad',
  'runOnDependencyChange',
  'requestConfirmation',
  'requestConfirmationFx',
  'confirmationMessage',
  'showSuccessNotification',
  'successMessage',
  'notificationDuration',
  'retry_network_errors',
  'query_timeout',
  'disableQuery',
  'disabledMessage',
  'events',
]);

// The query manager tab a query field (or query event handler) is edited in.
export const queryTabFor = (record: Pick<SearchRecord, 'entityType' | 'fieldPath'>): string => {
  if (record.entityType === 'event') return 'settings';
  if (record.fieldPath[0] !== 'options') return 'setup';
  if (TRANSFORMATION_OPTIONS.has(record.fieldPath[1])) return 'transformation';
  if (SETTINGS_OPTIONS.has(record.fieldPath[1])) return 'settings';
  return 'setup';
};

// Column fields edited on the column popover's Styles tab (Table/ColumnManager/StylesTabElements).
const TABLE_COLUMN_STYLE_KEYS = new Set([
  'horizontalAlignment',
  'activeColor',
  'borderRadius',
  'objectFit',
  'toggleOnBg',
  'toggleOffBg',
  'textColor',
  'cellBackgroundColor',
  'linkColor',
  'underlineColor',
  'underline',
  'selectedBgColorStars',
  'selectedBgColorHearts',
  'unselectedBgColor',
]);

// Reveal steps: what navigation asks the editor to open, outermost first, so the match is on screen.
// Each is consumed by the component that shows it (see useCodeSearchReveal).
const listItemStep = (ownerId: string, itemId: string): RevealStep => ({
  kind: 'listItem',
  ownerId,
  itemId,
});
const pageStep = (pageId: string): RevealStep => ({ kind: 'page', ownerId: null, itemId: pageId });
const queryTabStep = (queryId: string, tab: string): RevealStep => ({
  kind: 'queryTab',
  ownerId: queryId,
  itemId: tab,
});

// Request sub-tabs, by query kind: option key → tab key (REST shows `url_params` as `params` and
// edits the raw body in its Body tab; GraphQL's tabs are keyed by the option name).
const REQUEST_TABS: Record<string, Record<string, string>> = {
  restapi: {
    headers: 'headers',
    url_params: 'params',
    body: 'body',
    raw_body: 'body',
    json_body: 'body',
    cookies: 'cookies',
  },
  graphql: { headers: 'headers', url_params: 'url_params', cookies: 'cookies' },
};

// Inside the Setup tab: a parameter's popover (`parameters[i]`, by name) or a request sub-tab.
const queryOptionReveal = (query: Saved, path: string[]): RevealStep[] => {
  const steps = [queryTabStep(query.id, queryTabFor({ entityType: 'query', fieldPath: ['options', ...path] }))];
  const paramName = path[0] === 'parameters' ? query.options.parameters?.[path[1]]?.name : undefined;
  if (paramName)
    steps.push({
      kind: 'queryParam',
      ownerId: query.id,
      itemId: String(paramName),
    });
  const tab = REQUEST_TABS[query.kind]?.[path[0]];
  if (tab) steps.push({ kind: 'restTab', ownerId: query.id, itemId: tab });
  return steps;
};

const componentFieldReveal = (
  componentId: string,
  type: string,
  section: string,
  fieldPath: string[],
  itemIds: string[]
): RevealStep[] => {
  const steps = itemIds.map((itemId) => listItemStep(componentId, itemId));
  // properties.columns.value[i].<styleKey>
  const isColumnStyle =
    type === 'Table' && section === 'properties' && fieldPath[0] === 'columns' && fieldPath.length === 4;
  if (isColumnStyle && TABLE_COLUMN_STYLE_KEYS.has(fieldPath[3]) && itemIds[0]) {
    steps.push({ kind: 'popoverTab', ownerId: itemIds[0], itemId: 'styles' });
  }
  return steps;
};

// Where a handler's list is shown, from how the handler is stored: a query's Settings tab, a page's
// popover, a Table column's popover (`ref` = column name; `<column>::<buttonId>` for a button in a
// button column), a Table action (`ref` = action name), a Navigation item (`ref` = item id), or the
// component's own Events section.
const eventReveal = (event: Saved, columnsOf: (componentId: string) => Saved[]): RevealStep[] => {
  const { sourceId, target } = event;
  const ref = event.event?.ref;
  const handler: RevealStep = { kind: 'event', ownerId: sourceId, itemId: event.id };
  if (target === 'data_query') return [queryTabStep(sourceId, 'settings'), handler];
  if (target === 'page') return [pageStep(sourceId), handler];
  if (target === 'table_column') {
    const [columnRef, buttonId] = String(ref ?? '').split('::');
    const column = columnsOf(sourceId).find((c) => c?.name === columnRef || c?.key === columnRef);
    const steps = column?.id != null ? [listItemStep(sourceId, String(column.id))] : [];
    // A button column's button opens inside its column's popover, and lists its own handlers.
    if (buttonId) steps.push(listItemStep(sourceId, buttonId));
    return [...steps, handler];
  }
  if (ref) return [listItemStep(sourceId, String(ref)), handler];
  return [handler];
};

// A widget config (or the page settings config) keeps only its display labels: `displayName` and
// `<section>.<key>.displayName` (sections include `events`). Configs also hold functions and JSX,
// which can't be posted to the search worker.
const plainLabels = (def: Saved): Labels | undefined => {
  if (!def || typeof def !== 'object') return undefined;
  const plain: Labels = typeof def.displayName === 'string' ? { displayName: def.displayName } : {};
  for (const [section, fields] of Object.entries(def)) {
    if (!fields || typeof fields !== 'object' || Array.isArray(fields)) continue;
    const labels = Object.entries(fields).filter(
      ([, field]: [string, Saved]) => typeof field?.displayName === 'string'
    );
    if (labels.length)
      plain[section] = Object.fromEntries(labels.map(([key, field]) => [key, { displayName: field.displayName }]));
  }
  return plain;
};

// The parts of the editor's definitions buildSearchRecords reads, as plain cloneable data.
export const toPlainDefs = ({
  widgetDefs = {},
  actionDefs = [],
  pageSettingsDef = {},
}: {
  widgetDefs?: Record<string, Saved>;
  actionDefs?: Saved[];
  pageSettingsDef?: Saved;
}): PlainDefs => ({
  widgetDefs: Object.fromEntries(Object.entries(widgetDefs).map(([type, def]) => [type, plainLabels(def)])),
  actionDefs: actionDefs.map(({ id, name }) => ({ id, name })),
  pageSettingsDef: plainLabels(pageSettingsDef),
});

export const buildSearchRecords = ({
  pages = [],
  queries = [],
  events = [],
  globalSettings = {},
  pageSettings = null,
  translate = (text) => text,
  widgetDefs = {},
  actionDefs = [],
  pageSettingsDef = {},
}: SearchInput): SearchRecord[] => {
  const idNames: Record<string, string> = {};
  for (const page of pages) {
    idNames[page.id] = page.name;
    for (const [id, { component } = {}] of Object.entries<Saved>(page.components || {})) idNames[id] = component?.name;
  }
  for (const query of queries) idNames[query.id] = query.name;

  const records: SearchRecord[] = [];
  // Owner lookup for events: an event's sourceId is a component, query or page id.
  const owners = new Map<string, RecordBase>();
  const savedColumns = new Map<string, Saved[]>();
  const columnsOf = (componentId: string) => savedColumns.get(componentId) || [];
  const push = (base: RecordBase, fieldPath: string[], fieldLabel: string, value: string, shortLabel = fieldLabel) => {
    records.push({
      ...base,
      fieldPath,
      fieldLabel,
      shortLabel,
      text: translate(value),
    });
  };

  for (const page of pages) {
    const pageBase: RecordBase = {
      entityType: 'page',
      entityId: page.id,
      entityName: page.name,
      entitySubtype: 'Page',
      pageId: page.id,
      reveal: [pageStep(page.id)],
    };
    owners.set(page.id, pageBase);
    push(pageBase, ['name'], 'Name', page.name);
    if (page.handle) push(pageBase, ['handle'], 'Handle', page.handle);
    // hidden / disabled conditions, icon, URL, open-in, …
    walkLeaves(page, [], (path, text) => {
      if (PAGE_SKIP_KEYS.has(path[0])) return;
      const fieldPath = stripValueKey(path);
      if (fieldPath.length === 0) return;
      push(pageBase, fieldPath, fieldPath.map(humanize).join(' › '), text, pathShortLabel(fieldPath));
    });

    for (const [componentId, { component } = {}] of Object.entries<Saved>(page.components || {})) {
      if (!component) continue;
      const type = component.component;
      const widgetDef = widgetDefs[type];
      const base: RecordBase = {
        entityType: 'component',
        entityId: componentId,
        entityName: component.name,
        entitySubtype: widgetDef?.displayName || type,
        componentType: type,
        pageId: page.id,
      };
      owners.set(componentId, base);
      if (Array.isArray(component.definition?.properties?.columns?.value)) {
        savedColumns.set(componentId, component.definition.properties.columns.value);
      }
      push(base, ['name'], 'Name', component.name);
      const hiddenProperty = hiddenPropertyOf(type, component.definition?.properties);
      for (const section of COMPONENT_SECTIONS) {
        const saved = component.definition?.[section];
        walkLeaves(saved, [], (path, text) => {
          const fieldPath = stripValueKey(path);
          if (fieldPath.length === 0) return;
          if (section === 'properties' && fieldPath[0] === hiddenProperty) return;
          const labels = componentFieldLabels(widgetDef, section, fieldPath, saved);
          const reveal = componentFieldReveal(componentId, type, section, fieldPath, labels.itemIds);
          push(reveal.length ? { ...base, reveal } : base, [section, ...fieldPath], labels.full, text, labels.short);
        });
      }
    }
  }

  for (const query of queries) {
    const base: RecordBase = {
      entityType: 'query',
      entityId: query.id,
      entityName: query.name,
      entitySubtype: query.kind,
      query,
      pageId: null,
    };
    owners.set(query.id, base);
    push(base, ['name'], 'Name', query.name);
    walkLeaves(query.options, [], (path, text) => {
      const reveal = queryOptionReveal(query, path);
      // Query options have no `{ value }` wrapper; list items are named like component lists.
      const { parts } = readableRest(query.options[path[0]], path.slice(1), {
        valueWrapper: false,
      });
      const label = [humanize(path[0]), ...parts].join(' › ');
      push({ ...base, reveal }, ['options', ...path], label, text, label);
    });
  }

  // Handlers sharing a trigger and action on one owner look alike, so those get a suffix.
  const ownedEvents = events.filter((event) => owners.has(event.sourceId));
  const kindOf = (event: Saved) => `${event.sourceId}:${event.event?.eventId}:${event.event?.actionId}`;
  const lookAlikes: Record<string, Saved[]> = {};
  for (const event of ownedEvents) (lookAlikes[kindOf(event)] ||= []).push(event);
  // Told apart by handler name, unless the names repeat too (auto-named handlers): then by position.
  const suffixOf = (event: Saved) => {
    const group = lookAlikes[kindOf(event)];
    if (group.length < 2) return '';
    const namesUnique = group.every((other: Saved) => other === event || other.name !== event.name);
    if (event.name && namesUnique) return ` (${event.name})`;
    const byIndex = [...group].sort((a: Saved, b: Saved) => (a.index ?? 0) - (b.index ?? 0));
    return ` #${byIndex.indexOf(event) + 1}`;
  };

  for (const event of ownedEvents) {
    const owner = owners.get(event.sourceId) as RecordBase;
    const { eventId, actionId } = event.event || {};
    // Same text the handler card shows: `<trigger> → <action>`.
    const trigger =
      widgetDefs[owner.componentType ?? '']?.events?.[eventId]?.displayName ||
      NON_WIDGET_EVENT_NAMES[eventId] ||
      humanize(eventId || event.name || 'event');
    const action = actionDefs.find((def) => def.id === actionId)?.name;
    const handler = (action ? `${trigger} → ${action}` : trigger) + suffixOf(event);
    const fullPrefix = ['Events', event.name, handler].filter(Boolean).join(' › ');
    const base: RecordBase = {
      ...owner,
      ownerType: owner.entityType,
      ownerId: owner.entityId,
      entityType: 'event',
      eventId: event.id,
      reveal: eventReveal(event, columnsOf),
    };
    if (event.name) push(base, ['name'], `${fullPrefix} › Event name`, event.name, `${handler} › Event name`);
    // The popover's Event and Action dropdowns, as one row titled like the handler card. No short
    // label: the row's text is its title, so the match is marked in place.
    push(base, ['handler'], fullPrefix, handler, '');
    walkLeaves(event.event, [], (path, text) => {
      if (EVENT_SKIP_KEYS.has(path[0])) return;
      // Event actions store bare ids (queryId, componentId): show the name, drop ids of deleted
      // entities. Anywhere else a UUID is text someone typed, and stays as written.
      if (BARE_UUID.test(text)) {
        if (!idNames[text]) return;
        text = idNames[text];
      }
      const field = path.map((key, i) => humanize(i === path.length - 1 ? stripIdSuffix(key) : key)).join(' › ');
      push(base, ['event', ...path], `${fullPrefix} › ${field}`, text, `${handler} › ${field}`);
    });
  }

  // App-wide page navigation settings (header, menu, pill styles); edited in the Pages panel.
  const pageSettingsBase: RecordBase = {
    entityType: 'app',
    entityId: 'pageSettings',
    entityName: 'Pages and navigation',
    entitySubtype: 'Page settings',
    pageId: null,
  };
  for (const section of ['properties', 'styles']) {
    const saved = pageSettings?.definition?.[section];
    walkLeaves(saved, [], (path, text) => {
      const fieldPath = stripValueKey(path);
      if (fieldPath.length === 0) return;
      const labels = componentFieldLabels(pageSettingsDef, section, fieldPath, saved);
      push(pageSettingsBase, [section, ...fieldPath], labels.full, text, labels.short);
    });
  }

  const appBase: RecordBase = {
    entityType: 'app',
    entityId: 'app',
    entityName: 'App',
    entitySubtype: 'Global settings',
    pageId: null,
  };
  const preloaded = globalSettings?.preloadedScript?.javascript;
  if (preloaded) {
    const reveal: RevealStep[] = [{ kind: 'preloadedScript', ownerId: null, itemId: 'javascript' }];
    push({ ...appBase, reveal }, ['preloadedScript', 'javascript'], 'Preloaded JavaScript', preloaded);
  }
  walkLeaves(globalSettings, [], (path, text) => {
    if (GLOBAL_SETTINGS_SKIP_KEYS.has(path[0])) return;
    const fieldPath = stripValueKey(path);
    if (fieldPath.length === 0) return;
    push(appBase, fieldPath, fieldPath.map(humanize).join(' › '), text, pathShortLabel(fieldPath));
  });
  (globalSettings?.libraries?.javascript || []).forEach((library: Saved, index: number) => {
    const value = typeof library === 'string' ? library : library?.url || library?.name;
    if (value) push(appBase, ['libraries', 'javascript', String(index)], 'JavaScript libraries', value);
  });

  return records;
};
import { EditorView } from '@codemirror/view';
import { EditorSelection } from '@codemirror/state';
import type { FocusTarget } from '@/AppBuilder/_stores/slices/codeSearchSlice';
import type { RevealStep, SearchRecord } from './buildSearchRecords';
import type { SearchMatch } from './searchRecords';

// Where a result lands once navigation has opened its place. A field shown in a code editor is
// selected by that editor itself (it takes the store's focus request, see codeSearchHighlight);
// the DOM lookups here are the fallback for fields without one, and for popover rows.

type FoundEditor = { element: HTMLElement; view: EditorView };

const FLASH_CLASS = 'tj-code-search-flash';
const FLASH_MS = 1500;
const TIMEOUT_MS = 2000;

const flash = (element: HTMLElement | null) => {
  if (!element) return;
  element.classList.remove(FLASH_CLASS);
  void element.offsetWidth; // restart the animation when the same element flashes twice
  element.classList.add(FLASH_CLASS);
  setTimeout(() => element.classList.remove(FLASH_CLASS), FLASH_MS);
};

// Pages are edited in their details popover; libraries and the preloaded script in the Libraries
// panel; other app settings in Global settings; components and page settings in the right sidebar.
const PANEL_SELECTORS: Record<string, string> = {
  query: '.query-manager',
  page: '#add-new-page-popup',
};
const LIBRARY_FIELDS = new Set(['preloadedScript', 'libraries']);
const panelSelectorFor = (record: SearchRecord) => {
  const ownerType = record.ownerType || record.entityType;
  if (ownerType === 'app' && LIBRARY_FIELDS.has(record.fieldPath[0])) return '.app-libraries-panel';
  if (record.entityId === 'app') return '.global-settings-panel';
  return PANEL_SELECTORS[ownerType] || '.editor-sidebar .inspector';
};

// Inactive tab panes and closed sections stay mounted; only what is on screen can be the field. A
// field in a collapsed Inspector section counts when the section itself is on screen: landing on
// it expands the section (expandCollapsedAccordion).
const isVisible = (element: Element) => {
  const collapsed = element.closest('.accordion-collapse:not(.show)');
  return (collapsed?.parentElement ?? element).getClientRects().length > 0;
};

const editorsIn = (scope: Element): FoundEditor[] =>
  [...scope.querySelectorAll<HTMLElement>('.cm-editor')]
    .filter(isVisible)
    .map((element) => ({ element, view: EditorView.findFromDOM(element) }))
    .filter((editor): editor is FoundEditor => Boolean(editor.view));

// The editor whose text equals the indexed field is the field itself (editors render
// replaceIdsWithName(initialValue), the same text the index holds). Otherwise, when allowed, the
// first editor that contains the match.
const findEditor = (scope: Element, target: FocusTarget, allowPartial: boolean) => {
  const editors = editorsIn(scope);
  const exact = editors.find(({ view }) => view.state.doc.toString() === target.text);
  if (exact || !allowPartial) return exact;
  const needle = target.text.slice(target.start, target.end);
  return editors.find(({ view }) => view.state.doc.toString().includes(needle));
};

const STYLE_SECTIONS = ['styles', 'generalStyles'];
// Leading path keys that name where a field is stored, not the field (`properties.data`, `options.url`).
const SECTION_KEYS = new Set(['properties', 'styles', 'general', 'generalStyles', 'validation', 'others', 'options']);

// Component fields and app-wide page settings both live under Properties / Styles tabs.
const hasInspectorTabs = (record: SearchRecord) =>
  record.ownerType === 'component' || record.entityType === 'component' || record.entityId === 'pageSettings';

// The Properties / Styles tab a field lives under (the Inspector's or page settings' tab key).
export const tabKeyFor = (record: SearchRecord) => {
  if (!hasInspectorTabs(record)) return null;
  return record.entityType !== 'event' && STYLE_SECTIONS.includes(record.fieldPath[0]) ? 'styles' : 'properties';
};

const expandCollapsedAccordion = (element: Element) => {
  const collapsed = element.closest('.accordion-collapse:not(.show)');
  collapsed?.parentElement?.querySelector<HTMLElement>(':scope > .accordion-header')?.click();
};

const keyedIn = (scope: Element, key: string) =>
  [...scope.querySelectorAll<HTMLElement>(`[data-param="${CSS.escape(key)}"]`)].filter(isVisible);

// Elements tagged with the deepest path key tagged in `scope`. Earlier keys only break ties: an element
// nested in one tagged with an earlier key wins (`pageHeader` › `showOnDesktop`, not the footer's).
// Deepest first, because a path's middle keys can name other fields (`columns.value[i].label`).
const deepestTagged = (scope: Element, keys: string[]): HTMLElement[] | null => {
  for (let i = keys.length - 1; i >= 0; i--) {
    const found = keyedIn(scope, keys[i]);
    if (!found.length) continue;
    const nested = found.filter((element) =>
      keys.slice(0, i).some((key) => {
        const ancestor = element.parentElement?.closest(`[data-param="${CSS.escape(key)}"]`);
        return ancestor && scope.contains(ancestor);
      })
    );
    return nested.length ? nested : found;
  }
  return null;
};

// Keys a wrapper of the field may be tagged with. Inside an opened request tab any path key may be
// the tagged one, since the tab holds only that item. In a whole panel the field's own key must be
// tagged, or an inner key like `name` could land on another field.
const anchorKeys = ({ keys, inOpenedTab }: FocusTarget) => (inOpenedTab ? keys : keys.slice(0, 1));

// The field's own wrappers (`data-param="<key>"`); in a whole panel, deeper keys narrow within it.
const findFieldElements = (scope: Element, target: FocusTarget) => {
  if (target.inOpenedTab) return deepestTagged(scope, target.keys);
  const anchors = keyedIn(scope, target.keys[0]);
  if (!anchors.length) return null;
  const inner = anchors.flatMap((anchor) => deepestTagged(anchor, target.keys.slice(1)) || []);
  return inner.length ? inner : anchors;
};

// A match that lives in a popover flashes that popover's row. Search already shows the path inside it.
// These are not opened.
const POPOVER_KINDS = new Set<RevealStep['kind']>(['listItem', 'event', 'page', 'queryParam', 'preloadedScript']);
export const popoverStepOf = (record: SearchRecord) =>
  (record.reveal || []).find((step) => POPOVER_KINDS.has(step.kind));
const popoverTrigger = (record: SearchRecord, step: RevealStep): HTMLElement | null => {
  const id = CSS.escape(String(step.itemId));
  if (step.kind === 'event')
    return document.querySelector<HTMLElement>(`[data-event-id="${CSS.escape(record.eventId || '')}"]`);
  if (step.kind === 'page') return document.querySelector<HTMLElement>(`[data-page-id="${id}"]`);
  if (step.kind === 'preloadedScript') return document.querySelector<HTMLElement>('[data-preloaded-script]');
  return document.querySelector<HTMLElement>(`[data-list-item-id="${id}"]`);
};

// Steps whose opened place is marked `data-reveal-root="<kind>:<itemId>"`: a request sub-tab's pane
// (inactive panes stay mounted, so the match must not land in one). Other tabs have no root.
const ROOT_KINDS = new Set<RevealStep['kind']>(['restTab']);

// What the field's editor needs to recognise and select the match: where to look, the keys its
// wrapper is tagged with, and the clicked occurrence. `openedSteps` are the tabs navigation opened.
export const focusTargetFor = (match: SearchMatch, openedSteps: RevealStep[] = []): FocusTarget => {
  const { record, start, end } = match;
  const roots = openedSteps.filter((step) => ROOT_KINDS.has(step.kind));
  const innermost = roots[roots.length - 1];
  const keys = record.fieldPath.map(String);
  const own = SECTION_KEYS.has(keys[0]) && keys.length > 1 ? keys.slice(1) : keys;
  return {
    scope: innermost
      ? `[data-reveal-root="${`${innermost.kind}:${innermost.itemId}`.replace(/["\\]/g, '\\$&')}"]`
      : panelSelectorFor(record),
    keys: innermost ? keys : own,
    inOpenedTab: Boolean(innermost),
    text: record.text,
    start,
    end,
  };
};

// Where the clicked occurrence starts in `text`: the same offset when it is the indexed text, else
// the same-numbered copy of the needle (the 3rd `foo` stays the 3rd), else the first.
const occurrenceStart = (text: string, target: FocusTarget) => {
  const needle = target.text.slice(target.start, target.end);
  if (text === target.text) return target.start;
  let nth = 0;
  for (let at = target.text.indexOf(needle); at >= 0 && at < target.start; at = target.text.indexOf(needle, at + 1))
    nth++;
  let from = text.indexOf(needle);
  for (let i = 0; i < nth && from >= 0; i++) {
    const next = text.indexOf(needle, from + 1);
    if (next < 0) break;
    from = next;
  }
  return from;
};

const selectOccurrence = (view: EditorView, target: FocusTarget) => {
  const from = occurrenceStart(view.state.doc.toString(), target);
  if (from < 0) return;
  view.dispatch({
    selection: EditorSelection.single(from, from + target.end - target.start),
    scrollIntoView: true,
  });
  view.focus();
};

// A plain text input holding the field (a name, a handle): select the match in it.
const selectInInput = (element: HTMLElement, target: FocusTarget) => {
  const input = (
    element.matches('input, textarea') ? element : element.querySelector('input[type="text"], textarea')
  ) as HTMLInputElement | HTMLTextAreaElement | null;
  if (!input || input.disabled) return;
  const from = occurrenceStart(input.value, target);
  if (from < 0) return;
  input.focus();
  input.setSelectionRange(from, from + target.end - target.start);
};

const revealAndFlash = (element: HTMLElement, afterScroll?: () => void) => {
  expandCollapsedAccordion(element);
  // Let the accordion expand paint before scrolling to the field.
  requestAnimationFrame(() => {
    element.scrollIntoView?.({ block: 'center' });
    afterScroll?.();
    flash(element);
  });
};

// The `data-param` keys tagged on `element`'s ancestors inside `scope`.
const taggedKeysOf = (element: Element, scope: Element) => {
  const keys: string[] = [];
  for (let at = element.parentElement; at && at !== scope; at = at.parentElement) {
    const key = at.getAttribute('data-param');
    if (key) keys.push(key);
  }
  return keys;
};

// Whether this code editor shows the requested field: it is on screen in the requested place, holds
// exactly the indexed text, and its wrapper is tagged with the field's key. An editor with no tagged
// wrapper (a query's main editor) is the field only when nothing on screen there carries the key.
export const editorHoldsField = (view: EditorView, target: FocusTarget) => {
  const scope = view.dom.closest(target.scope);
  if (!scope || !isVisible(view.dom) || view.state.doc.toString() !== target.text) return false;
  const anchors = anchorKeys(target);
  const tagged = taggedKeysOf(view.dom, scope);
  if (tagged.length) return tagged.some((key) => anchors.includes(key));
  return anchors.every((key) => !keyedIn(scope, key).length);
};

// Flashed around the editor: CodeMirror rewrites its own root's class whenever it updates.
export const landInEditor = (view: EditorView, target: FocusTarget) =>
  revealAndFlash(view.dom.parentElement ?? view.dom, () => selectOccurrence(view, target));

// A field no code editor took: its own tagged row (a toggle, select, picker or plain input, or an
// editor whose text differs from the index). False when the place shows no such row.
export const landOnTaggedField = (target: FocusTarget) => {
  const scope = document.querySelector<HTMLElement>(target.scope);
  const elements = scope && findFieldElements(scope, target);
  if (!elements) return false;
  const editor = elements.map((element) => findEditor(element, target, true)).find(Boolean);
  if (editor) landInEditor(editor.view, target);
  else revealAndFlash(elements[0], () => selectInInput(elements[0], target));
  return true;
};

// Last resort: any editor there containing the match, else the whole place.
export const landAnywhere = (target: FocusTarget) => {
  const scope = document.querySelector<HTMLElement>(target.scope);
  const editor = scope && findEditor(scope, target, true);
  if (editor) landInEditor(editor.view, target);
  else flash(scope);
};

// A popover match flashes the row that opens it, once that row has rendered. The field inside stays
// closed; the result label already says which control is in there.
export const flashPopover = (match: SearchMatch, step: RevealStep) => {
  const { record } = match;
  const started = performance.now();
  const tick = () => {
    const trigger = popoverTrigger(record, step);
    if (trigger && isVisible(trigger)) return revealAndFlash(trigger);
    if (performance.now() - started > TIMEOUT_MS)
      return flash(document.querySelector<HTMLElement>(panelSelectorFor(record)));
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
};
// Matches a term against the rows from buildSearchRecords and groups the hits for display:
// section (Components / Queries / Events / Pages & app) → entity → one row per field, every
// occurrence in that row.
// Pure, like buildSearchRecords; both run in the code-search worker (codeSearch.worker.ts).

import {
  buildSearchRecords,
  type EntityType,
  type PlainDefs,
  type SearchInput,
  type SearchRecord,
} from './buildSearchRecords';
import { replaceIdsWithName } from '@/AppBuilder/_stores/utils/replaceIdsWithName';

export interface MatchOptions {
  caseSensitive?: boolean;
  wholeWord?: boolean;
  regex?: boolean;
}

export interface SearchFilters extends MatchOptions {
  type?: 'all' | EntityType;
  currentPageOnly?: boolean;
}

export interface Match {
  start: number;
  end: number;
  occurrence: number;
}

// One clicked occurrence: what navigation opens and highlights.
export type SearchMatch = Match & { record: SearchRecord };

export interface PreviewSegment {
  text: string;
  match: boolean;
  occurrence?: number;
}

export interface ResultRow {
  record: SearchRecord;
  matches: Match[];
  preview: PreviewSegment[];
}

export interface ResultEntity {
  entityId: string;
  entityType: EntityType;
  entityName: string;
  entitySubtype?: string;
  componentType?: string;
  query?: SearchRecord['query'];
  // The page a component (or an event's owner) is on; shown as a tag, since sections don't split by page.
  pageId?: string | null;
  defined: boolean;
  count: number;
  rows: ResultRow[];
}

export type SectionKey = 'components' | 'queries' | 'events' | 'pages';

export interface ResultGroup {
  key: SectionKey;
  count: number;
  entities: ResultEntity[];
}

export interface SearchResult {
  groups: ResultGroup[];
  rows: ResultRow[];
  total: number;
  fieldCount: number;
  truncated: boolean;
  typeCounts: Record<'all' | EntityType, number>;
  error: string | null;
}

// A page as the searcher needs it: its id for ordering, plus whatever buildSearchRecords reads.
type SearchPage = { id: string; components?: Record<string, { component?: { name?: string } }> };

// What the panel posts: the app definition (only when it changed) and the search to run.
export interface SearchInputDefinition extends Omit<SearchInput, 'pages' | 'translate' | keyof PlainDefs> {
  pages: SearchPage[];
  queryIdNameMapping?: Record<string, string>;
  defs: PlainDefs;
}

export interface SearchRequest {
  input?: SearchInputDefinition;
  term: string;
  filters?: SearchFilters;
  currentPageId?: string | null;
}

export const MIN_TERM_LENGTH = 2;
export const MAX_RESULTS = 1000; // field rows
export const RESULT_TYPES: EntityType[] = ['component', 'query', 'event', 'page', 'app'];
const PREVIEW_LEAD = 10; // characters kept before the first match, so the match is always in view
const PREVIEW_LENGTH = 160; // wider than the panel on purpose; CSS ellipsis does the visual cut

const escapeRegExp = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Returns a global RegExp for the term, or { error } when the user's regex does not compile.
export const buildMatcher = (
  term: string,
  { caseSensitive = false, wholeWord = false, regex = false }: MatchOptions = {}
): { matcher?: RegExp; error?: string } => {
  const source = regex ? term : escapeRegExp(term);
  try {
    return { matcher: new RegExp(wholeWord ? `\\b(?:${source})\\b` : source, caseSensitive ? 'g' : 'gi') };
  } catch {
    return { error: 'Invalid regular expression' };
  }
};

const findMatches = (matcher: RegExp, text: string) => {
  const matches: Match[] = [];
  matcher.lastIndex = 0;
  let hit;
  while ((hit = matcher.exec(text)) !== null) {
    if (hit[0] === '') {
      matcher.lastIndex++; // zero-width regex (e.g. `^`) would loop forever
      continue;
    }
    matches.push({ start: hit.index, end: hit.index + hit[0].length, occurrence: matches.length });
  }
  return matches;
};

// Where the preview starts: after the last separator in the lead before the first match, so it opens
// on the matched token (`email: 'olivia…`, not `…05/2022', email:`). No separator → a fixed lead,
// cut mid-token, so only that start is marked with `…`.
const PREVIEW_BREAK = /[\s,;{}()[\]]/;
const previewStart = (text: string, matchStart: number) => {
  const leadFrom = Math.max(0, matchStart - PREVIEW_LEAD);
  for (let i = matchStart - 1; i >= leadFrom; i--) if (PREVIEW_BREAK.test(text[i])) return { from: i + 1, cut: false };
  return { from: leadFrom, cut: leadFrom > 0 };
};

// Text segments for one row: starts on the first match's token, every match inside is marked.
// Whitespace runs collapse to one space so multi-line code previews as one line.
// A title (a row with no short label, e.g. `Row clicked → Show Alert`) is shown whole.
export const buildPreview = (text: string, matches: Match[], { title = false } = {}): PreviewSegment[] => {
  const { from, cut } = title ? { from: 0, cut: false } : previewStart(text, matches[0].start);
  const to = Math.min(text.length, from + PREVIEW_LENGTH);
  const clean = (value: string) => value.replace(/\s+/g, ' ');
  const segments: PreviewSegment[] = cut ? [{ text: '…', match: false }] : [];
  let cursor = from;
  for (const { start, end, occurrence } of matches) {
    if (start >= to) break;
    if (start > cursor) segments.push({ text: clean(text.slice(cursor, start)), match: false });
    segments.push({ text: clean(text.slice(start, Math.min(end, to))), match: true, occurrence });
    cursor = Math.min(end, to);
  }
  if (cursor < to) segments.push({ text: clean(text.slice(cursor, to)), match: false });
  return segments;
};

// Fixed section order; pages and app-wide settings share the last one.
const SECTION_ORDER: SectionKey[] = ['components', 'queries', 'events', 'pages'];
export const SECTION_OF: Record<EntityType, SectionKey> = {
  component: 'components',
  query: 'queries',
  event: 'events',
  page: 'pages',
  app: 'pages',
};

export const searchRecords = (
  records: SearchRecord[],
  term: string,
  {
    caseSensitive = false,
    wholeWord = false,
    regex = false,
    type = 'all',
    currentPageOnly = false,
  }: SearchFilters = {},
  { currentPageId = null, pages = [] }: { currentPageId?: string | null; pages?: { id: string }[] } = {}
): SearchResult => {
  const typeCounts = Object.fromEntries(['all', ...RESULT_TYPES].map((key) => [key, 0])) as SearchResult['typeCounts'];
  const empty: SearchResult = {
    groups: [],
    rows: [],
    total: 0,
    fieldCount: 0,
    truncated: false,
    typeCounts,
    error: null,
  };
  if (!term || term.length < MIN_TERM_LENGTH) return empty;

  const { matcher, error } = buildMatcher(term, { caseSensitive, wholeWord, regex });
  if (error) return { ...empty, error };

  // Current-page scope narrows the search itself; the type filter only narrows what is shown,
  // so chip counts always tell the user what a filter hides.
  const inScope = currentPageOnly ? (record: SearchRecord) => record.pageId === currentPageId : () => true;

  const rows: ResultRow[] = [];
  let total = 0;
  let fieldCount = 0;
  for (const record of records) {
    if (!inScope(record)) continue;
    const matches = findMatches(matcher as RegExp, record.text);
    if (!matches.length) continue;
    typeCounts.all += matches.length;
    typeCounts[record.entityType] += matches.length;
    if (type !== 'all' && record.entityType !== type) continue;
    total += matches.length;
    fieldCount++;
    if (rows.length < MAX_RESULTS)
      rows.push({ record, matches, preview: buildPreview(record.text, matches, { title: !record.shortLabel }) });
  }

  // Entities are keyed by id while grouping, then listed in display order.
  type GroupDraft = Omit<ResultGroup, 'entities'> & { entities: Map<string, ResultEntity> };
  const groups = new Map<SectionKey, GroupDraft>();
  for (const row of rows) {
    const { record } = row;
    const groupKey = SECTION_OF[record.entityType];
    if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, count: 0, entities: new Map() });
    const group = groups.get(groupKey) as GroupDraft;
    // In Events, handlers are listed under the component / query / page that owns them.
    const entityId = record.ownerId || record.entityId;
    if (!group.entities.has(entityId)) {
      group.entities.set(entityId, {
        entityId,
        entityType: record.ownerType || record.entityType,
        entityName: record.entityName,
        entitySubtype: record.entitySubtype,
        componentType: record.componentType,
        query: record.query,
        pageId: record.pageId,
        defined: false,
        count: 0,
        rows: [],
      });
    }
    const entity = group.entities.get(entityId) as ResultEntity;
    entity.rows.push(row);
    entity.count += row.matches.length;
    group.count += row.matches.length;
  }

  const sameName = (name: string) =>
    caseSensitive ? name === term : String(name).toLowerCase() === term.toLowerCase();
  const pageOrder = new Map(pages.map((page, index) => [page.id, index]));
  // The entity the term names first ("defined here"; everything else references it), then the
  // current page's, then by page order; app-wide entities (no page) last.
  const entityRank = (entity: ResultEntity) => {
    if (entity.defined) return -2;
    if (entity.pageId && entity.pageId === currentPageId) return -1;
    return entity.pageId ? (pageOrder.get(entity.pageId) ?? pages.length) : pages.length + 1;
  };

  const sortedGroups: ResultGroup[] = SECTION_ORDER.flatMap((key) => {
    const group = groups.get(key);
    if (!group) return [];
    const entities = [...group.entities.values()];
    // Events are listed under their owner, which the term naming doesn't make a definition.
    if (key !== 'events') for (const entity of entities) entity.defined = sameName(entity.entityName);
    entities.sort((a, b) => entityRank(a) - entityRank(b));
    return [{ ...group, entities }];
  });

  // Rows in display order, for keyboard navigation and the flat list view.
  const orderedRows = sortedGroups.flatMap((group) => group.entities.flatMap((entity) => entity.rows));

  return {
    groups: sortedGroups,
    rows: orderedRows,
    total,
    fieldCount,
    truncated: fieldCount > rows.length,
    typeCounts,
    error: null,
  };
};

// One search session: `input` (the app definition, see CodeSearch.jsx) rebuilds the records; a
// search without it reuses the last ones, so only definition changes pay for indexing. Page order
// comes from the indexed pages, so a search only sends `currentPageId`.
export const createSearcher = () => {
  let records: SearchRecord[] = [];
  let pages: SearchPage[] = [];
  return ({ input, term, filters, currentPageId }: SearchRequest): SearchResult => {
    if (input) {
      const { queryIdNameMapping, defs, ...rest } = input;
      pages = input.pages;
      const mappings = {
        components: Object.fromEntries(
          pages.flatMap((page) =>
            Object.entries(page.components || {}).map(([id, { component } = {}]) => [id, component?.name])
          )
        ),
        queries: queryIdNameMapping || {},
      };
      records = buildSearchRecords({ ...rest, ...defs, translate: (text) => replaceIdsWithName(text, mappings) });
    }
    return searchRecords(records, term, filters, { currentPageId, pages });
  };
};
import { useEffect, useRef } from 'react';
import useStore from '@/AppBuilder/_stores/store';
import type { CodeSearchState } from '@/AppBuilder/_stores/slices/codeSearchSlice';
import type { RevealStep } from './buildSearchRecords';

/**
 * Lets code search open an item this component shows behind a click (a list row's popover, an
 * event handler, a tab). `open(itemId)` opens it and returns true when this instance owns the item;
 * the request is then consumed. Several instances may share a kind and owner (a Table's component,
 * column and action event lists), so ownership is decided by `open`, not by mounting.
 *
 * `deps`: values `open` reads (e.g. the loaded list), so a request that arrived before the item
 * existed is retried once it does.
 */
export const useCodeSearchReveal = (
  kind: RevealStep['kind'],
  ownerId: string | null | undefined,
  open: (itemId: string) => boolean,
  deps: unknown[] = []
): void => {
  const request = useStore((state: CodeSearchState) => state.codeSearch.revealRequest);
  const openRef = useRef(open);
  openRef.current = open;

  useEffect(() => {
    if (!request || request.kind !== kind || request.ownerId !== ownerId) return;
    if (openRef.current(request.itemId)) useStore.getState().consumeCodeSearchReveal(request.nonce);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [request, kind, ownerId, ...deps]);
};
import React from 'react';
import * as TooltipPrimitive from '@radix-ui/react-tooltip';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/Rocket/shadcn/tooltip';
import type { TooltipBinding } from './types';

const TypedTooltipContent = TooltipContent as React.ComponentType<
  React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>
>;

type TooltipSide = 'top' | 'right' | 'bottom' | 'left';

export type BindingTooltipProps = {
  id?: string;
  title?: string;
  bindings?: TooltipBinding[];
  placement?: TooltipSide | `${TooltipSide}-start` | `${TooltipSide}-end`;
  /**
   * The card's colours come from the `--*-inverse` tokens, whose dark values are only
   * defined under `.dark-theme`. That class sits on inner wrappers, never on <body>, and
   * this content is portalled to <body> — so the class has to travel with it or the card
   * stays light in dark mode.
   */
  darkMode?: boolean;
  /** A single element — TooltipTrigger clones it via asChild. */
  children: React.ReactElement;
};

const sideOf = (placement: BindingTooltipProps['placement']): TooltipSide => {
  if (!placement) return 'right';
  if (placement.startsWith('top')) return 'top';
  if (placement.startsWith('bottom')) return 'bottom';
  if (placement.startsWith('left')) return 'left';
  return 'right';
};

/**
 * Dark card shown on hover over a relationship row: a sentence describing the
 * relationship, then one `label / expression` pair per binding behind it.
 * Renders the child untouched when there is nothing to explain.
 */
export const BindingTooltip = ({
  id,
  title,
  bindings,
  placement = 'right',
  darkMode = false,
  children,
}: BindingTooltipProps): React.ReactElement => {
  const resolved = (bindings ?? []).filter((binding) => binding.expression);
  if (!title || resolved.length === 0) return children;

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>{children}</TooltipTrigger>
        <TypedTooltipContent
          id={id}
          side={sideOf(placement)}
          sideOffset={8}
          className={`dependency-binding-tooltip tw-bg-transparent tw-p-0 tw-shadow-none tw-overflow-visible tw-text-inherit ${
            darkMode ? 'dark-theme' : ''
          }`}
        >
          <div className="dependency-binding-card">
            <div className="dependency-binding-title">
              <span className="dependency-binding-title-text">{title}</span>
            </div>
            <div className="dependency-binding-body">
              {resolved.map((binding) => (
                <div className="dependency-binding-entry" key={binding.label}>
                  <div className="dependency-binding-label">{binding.label}</div>
                  <div className="dependency-binding-expression">{binding.expression}</div>
                </div>
              ))}
            </div>
          </div>
        </TypedTooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

export default BindingTooltip;
import React from 'react';
import { decodeEntities } from '@/_helpers/utils';
import { activateOnEnterOrSpace } from '@/AppBuilder/Shared/EntityUsage/keyboard';
import BindingTooltip from './BindingTooltip';
import type { RowTooltip } from './types';

// Wraps every case-insensitive occurrence of `term` in a <mark> so the reason a row
// survived the search is visible.
const withHighlight = (text: string, term?: string): React.ReactNode => {
  if (!term) return text;
  const needle = term.toLowerCase();
  const haystack = text.toLowerCase();
  const parts: React.ReactNode[] = [];
  let cursor = 0;
  let at = haystack.indexOf(needle);
  while (at !== -1) {
    if (at > cursor) parts.push(text.slice(cursor, at));
    parts.push(
      <mark className="dependency-row-highlight" key={`${at}-${needle}`}>
        {text.slice(at, at + needle.length)}
      </mark>
    );
    cursor = at + needle.length;
    at = haystack.indexOf(needle, cursor);
  }
  if (cursor === 0) return text;
  if (cursor < text.length) parts.push(text.slice(cursor));
  return parts;
};

/**
 * One entity row. Compact (single line) on the main tab's query/variable lists;
 * stacked (name + type + relationship tags) for components and every detail row.
 */
export type DependencyEntityRowProps = {
  icon?: React.ReactNode;
  name: string;
  subtitle?: string;
  tags?: string[];
  tooltip?: RowTooltip;
  highlight?: string;
  selected?: boolean;
  onClick?: () => void;
  dataCy?: string;
  /** Forwarded to the portalled tooltip, which cannot inherit the panel's theme class. */
  darkMode?: boolean;
};

export const DependencyEntityRow = ({
  icon,
  name,
  subtitle,
  tags = [],
  tooltip,
  highlight,
  selected = false,
  onClick,
  dataCy,
  darkMode = false,
}: DependencyEntityRowProps) => {
  const stacked = Boolean(subtitle) || tags.length > 0;
  const label = decodeEntities(name);

  const row = (
    <div
      className={`dependency-row ${stacked ? 'stacked' : 'compact'} ${onClick ? 'clickable' : ''} ${
        selected ? 'selected' : ''
      }`}
      onClick={onClick}
      onKeyDown={activateOnEnterOrSpace(onClick)}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      data-cy={dataCy}
    >
      <span className="dependency-row-icon">{icon}</span>
      <span className="dependency-row-content">
        <span className="dependency-row-name text-truncate">{withHighlight(label, highlight)}</span>
        {subtitle && <span className="dependency-row-subtitle text-truncate">{subtitle}</span>}
        {tags.map((tag, index) => (
          // eslint-disable-next-line react/no-array-index-key
          <span className="dependency-row-tag" key={`${tag}-${index}`}>
            {tag}
          </span>
        ))}
      </span>
    </div>
  );

  if (!tooltip) return row;
  return (
    <BindingTooltip id={tooltip.id} title={tooltip.title} bindings={tooltip.bindings} darkMode={darkMode}>
      {row}
    </BindingTooltip>
  );
};

export default DependencyEntityRow;
