export type VariableUsage = {
  name: string;
  scope: 'app' | 'page';
  setBy: UsageEntry[];
  readBy: UsageEntry[];
};

/** Per-component usage the caller has already computed, keyed by component id. */
export type ComponentUsageById = Record<string, ReturnType<typeof getComponentUsage>>;

/**
