              </ButtonSolid>
            )}
          </div>
        </div>
        {showReport && (
          <ErrorReportModal
            show={showReport}
            onClose={this.closeReport}
            error={error}
            errorInfo={errorInfo}
            eventId={eventId}
            label={label}
            darkMode={darkMode}
          />
        )}
      </>
